INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('02dcdef696e23f14e4a45096c6e8f373', '0', NULL, '2026-07-14 11:02:30', NULL, '2026-07-14 11:02:30', NULL, '8ecbc53f72b96e01428af3521a4737c1', 'source_code', 'c', 'x86_64/arm64', 'risc-v', '#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_X86) && !defined(ARCH_SH4)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif\n\n#if defined(ARCH_X86_64)\n...\n#elif defined(ARCH_ARM64)\n...\n#elif defined(ARCH_X86)\n...\n#elif defined(ARCH_SH4)\n...\n#else\n#    error \"Unsupported architecture\"\n#endif', '#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_X86) && !defined(ARCH_SH4) && !defined(ARCH_ARM64) && !defined(ARCH_RISCV64) && !defined(ARCH_RISCV32)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    elif defined(__riscv)\n#        if __riscv_xlen == 64\n#            define ARCH_RISCV64 1\n#        elif __riscv_xlen == 32\n#            define ARCH_RISCV32 1\n#        else\n#            error \"Unsupported RISC-V XLEN\"\n#        endif\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif\n\n#if defined(ARCH_X86_64)\n...\n#elif defined(ARCH_ARM64)\n...\n#elif defined(ARCH_RISCV64)\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-riscv64.h\"\n    #define SYSNUMS_ABI1    sysnums_riscv64\n    #define SYSTRAP_SIZE 4\n    #ifndef AUDIT_ARCH_RISCV64\n        #define AUDIT_ARCH_RISCV64 (243 | __AUDIT_ARCH_64BIT | __AUDIT_ARCH_LE)\n    #endif\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_RISCV64, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n    #define HOST_ELF_MACHINE {243, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define LOADER_ADDRESS     0x4000000000\n    #define EXEC_PIC_ADDRESS   0x5000000000\n    #define INTERP_PIC_ADDRESS 0x5f00000000\n#elif defined(ARCH_RISCV32)\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-riscv32.h\"\n    #define SYSNUMS_ABI1    sysnums_riscv32\n    #define SYSTRAP_SIZE 4\n    #ifndef AUDIT_ARCH_RISCV32\n        #define AUDIT_ARCH_RISCV32 (243 | __AUDIT_ARCH_LE)\n    #endif\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_RISCV32, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n    #define HOST_ELF_MACHINE {243, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define NO_MISALIGNED_ACCESS 1\n    #define LOADER_ADDRESS     0x40000000\n    #define EXEC_PIC_ADDRESS   0x50000000\n    #define INTERP_PIC_ADDRESS 0x5f000000\n#elif defined(ARCH_X86)\n...\n#elif defined(ARCH_SH4)\n...\n#else\n#    error \"Unsupported architecture\"\n#endif', 'Line 49 `#error \"Unsupported architecture\"` 是架构检测的兜底分支。RISC-V 编译时没有匹配已有宏（__x86_64__/__ARM_EABI__/__aarch64__/__i386__/__SH4__），直接触发编译中止。修复：在 #else 前插入 `#elif defined(__riscv)`，使用 `__riscv_xlen` 区分 RV64/RV32；新增 ARCH_RISCV64/ARCH_RISCV32 定义块，设置 ELF 机器号 243、AUDIT_ARCH_RISCV64、无 red zone 及合适 loader 地址；RV32 额外开启 NO_MISALIGNED_ACCESS 避免对齐陷阱开销。SYSTRAP_NUM 保持默认 SYSARG_NUM（RISC-V 通过 a7 传 syscall 号）。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('0705283ba17c856da7ceccd09001c6aa', '0', NULL, '2026-07-27 11:01:20', NULL, '2026-07-27 11:01:20', NULL, '01df88b254c9685e4e2e630c69542e86', 'source_code', 'c', 'x86_64', 'risc-v', '#include <stdio.h>\n#include <stdlib.h>\n#include \"arch.h\"\n\n#ifdef __x86_64__\n  #define ARCH_NAME \"x86_64\"\n#elif defined(__aarch64__)\n  #define ARCH_NAME \"aarch64\"\n#else\n  #define ARCH_NAME \"unknown\"\n#endif\n\nint main(int argc, char **argv) {\n    printf(\"Hello from %s\\n\", ARCH_NAME);\n\n#if defined(__x86_64__) || defined(__i386__)\n    unsigned long flags;\n    asm volatile(\"pushf; pop %0\" : \"=r\"(flags));\n    printf(\"x86 flags: %lx\\n\", flags);\n#endif\n\n    return 0;\n}', '#include <stdio.h>\n#include <stdlib.h>\n#include \"arch.h\"\n\n#ifdef __x86_64__\n  #define ARCH_NAME \"x86_64\"\n#elif defined(__aarch64__)\n  #define ARCH_NAME \"aarch64\"\n#elif defined(__riscv)\n  #define ARCH_NAME \"riscv\"\n#else\n  #define ARCH_NAME \"unknown\"\n#endif\n\nint main(int argc, char **argv) {\n    printf(\"Hello from %s\\n\", ARCH_NAME);\n\n#if defined(__riscv)\n    unsigned long cycle;\n    asm volatile(\"rdcycle %0\" : \"=r\"(cycle));\n    printf(\"RISC-V cycle: %lx\\n\", cycle);\n#endif\n\n    return 0;\n}', '第17行 #if defined(__x86_64__) || defined(__i386__) 包裹了x86专有汇编pushf/pop读取EFLAGS，RISC-V无EFLAGS且不支持该指令。适配方案：在else分支添加__riscv检测，用rdcycle读取硬件周期计数器作为等效诊断信息，同时补充ARCH_NAME的RISC-V定义。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('0b398a68942af90c1eba852e0e536fa5', '0', NULL, '2026-07-09 13:45:52', NULL, '2026-07-09 13:45:52', NULL, 'c84a09afdce9a324b17d747c233f025b', 'source_code', 'c', 'x86_64', 'risc-v', '#define BRANCH(stack_pointer, destination) do {			\\\n	asm volatile (						\\\n		\"// Restore initial stack pointer.	\\n\\t\"	\\\n		\"movq %0, %%rsp				\\n\\t\"	\\\n		\"					\\n\\t\"	\\\n		\"// Clear state flags.			\\n\\t\"	\\\n		\"pushq $0				\\n\\t\"	\\\n		\"popfq					\\n\\t\"	\\\n		\"					\\n\\t\"	\\\n		\"// Clear rtld_fini.			\\n\\t\"	\\\n		\"movq $0, %%rdx				\\n\\t\"	\\\n		\"					\\n\\t\"	\\\n		\"// Start the program.			\\n\\t\"	\\\n		\"jmpq *%%rax				\\n\"	\\\n		: /* no output */				\\\n		: \"irm\" (stack_pointer), \"a\" (destination)	\\\n		: \"memory\", \"cc\", \"rsp\", \"rdx\");		\\\n	__builtin_unreachable();				\\\n	} while (0)', '#define BRANCH(stack_pointer, destination) do {			\\\n	asm volatile (						\\\n		\"// Restore initial stack pointer.	\\n\\t\"	\\\n		\"mv sp, %0				\\n\\t\"	\\\n		\"					\\n\\t\"	\\\n		\"// Clear rtld_fini.			\\n\\t\"	\\\n		\"mv a0, zero				\\n\\t\"	\\\n		\"					\\n\\t\"	\\\n		\"// Start the program.			\\n\\t\"	\\\n		\"jr %1					\\n\"	\\\n		: /* no output */				\\\n		: \"r\" (stack_pointer), \"r\" (destination)	\\\n		: \"memory\", \"sp\", \"a0\");			\\\n	__builtin_unreachable();				\\\n	} while (0)', 'x86_64 BRANCH 宏使用 movq/pushq/popfq/jmpq 及 rsp/rdx/rax 寄存器，与 RISC-V 不兼容。RISC-V 适配：mv sp 设置栈指针；RISC-V 无 EFLAGS，无需清标志操作；rtld_fini 寄存器从 rdx 改为 a0（RISC-V ELF ABI 约定）；jr 指令间接跳转。约束条件从 \"a\"(rax) 改为通用 \"r\" 寄存器。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('0ce771a23f7d866126c3f32ff9f48b53', '0', NULL, '2026-07-27 10:12:00', NULL, '2026-07-27 10:12:00', NULL, 'c6ff6c035da9736ca86f235e989a8df6', 'source_code', 'c', 'x86_64', 'risc-v', '#    ifndef PTRACE_EVENT_SECCOMP2\n#        if PTRACE_EVENT_SECCOMP == 7\n#            define PTRACE_EVENT_SECCOMP2	8\n#        elif PTRACE_EVENT_SECCOMP == 8\n#            define PTRACE_EVENT_SECCOMP2	7\n#        else\n#            error \"unknown PTRACE_EVENT_SECCOMP value\"\n#        endif\n#    endif', '#    ifndef PTRACE_EVENT_SECCOMP2\n#        if PTRACE_EVENT_SECCOMP == 7\n#            define PTRACE_EVENT_SECCOMP2	8\n#        elif PTRACE_EVENT_SECCOMP == 8\n#            define PTRACE_EVENT_SECCOMP2	7\n#        else\n#            error \"unknown PTRACE_EVENT_SECCOMP value\"\n#        endif\n#    endif', 'PTRACE_EVENT_SECCOMP2 fallback logic is architecture-independent. On RISC-V PTRACE_EVENT_SECCOMP==7 (standard), so SECCOMP2 resolves to 8. The code is already correct and requires no changes for RISC-V compatibility.');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('0f5becf161a8489789aeedf907768d1e', '0', NULL, '2026-07-14 11:04:10', NULL, '2026-07-14 11:04:10', NULL, '8ecbc53f72b96e01428af3521a4737c1', 'source_code', 'c', 'x86_64/arm64', 'risc-v', '#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_X86) && !defined(ARCH_SH4)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif\n\n/* Architecture specific definitions. */\n#if defined(ARCH_X86_64)\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-x86_64.h\"\n    #define SYSNUMS_HEADER2 \"syscall/sysnums-i386.h\"\n    #define SYSNUMS_HEADER3 \"syscall/sysnums-x32.h\"\n    #define SYSNUMS_ABI1 sysnums_x86_64\n    #define SYSNUMS_ABI2 sysnums_i386\n    #define SYSNUMS_ABI3 sysnums_x32\n    #undef  SYSTRAP_NUM\n    #define SYSTRAP_NUM SYSARG_RESULT\n    #define SYSTRAP_SIZE 2\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_X86_64, .nb_abis = 2, .abis = { ABI_DEFAULT, ABI_3 } }, { .value = AUDIT_ARCH_I386, .nb_abis = 1, .abis = { ABI_2 } } }\n    #define HOST_ELF_MACHINE {62, 3, 6, 0}\n    #define RED_ZONE_SIZE 128\n    #define OFFSETOF_STAT_UID_32 24\n    #define OFFSETOF_STAT_GID_32 28\n    #define LOADER_ADDRESS 0x600000000000\n    #define HAS_LOADER_32BIT true\n    #define EXEC_PIC_ADDRESS   0x500000000000\n    #define INTERP_PIC_ADDRESS 0x6f0000000000\n    #define EXEC_PIC_ADDRESS_32   0x0f000000\n    #define INTERP_PIC_ADDRESS_32 0xaf000000\n#elif defined(ARCH_ARM_EABI)\n...\n#elif defined(ARCH_ARM64)\n...\n#elif defined(ARCH_X86)\n...\n#elif defined(ARCH_SH4)\n...\n#else\n#    error \"Unsupported architecture\"\n#endif', '#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_X86) && !defined(ARCH_SH4) && !defined(ARCH_ARM64) && !defined(ARCH_RISCV64) && !defined(ARCH_RISCV32)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    elif defined(__riscv)\n#        if __riscv_xlen == 64\n#            define ARCH_RISCV64 1\n#        elif __riscv_xlen == 32\n#            define ARCH_RISCV32 1\n#        else\n#            error \"Unsupported RISC-V XLEN\"\n#        endif\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif\n\n/* Architecture specific definitions. */\n#if defined(ARCH_X86_64)\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-x86_64.h\"\n    #define SYSNUMS_HEADER2 \"syscall/sysnums-i386.h\"\n    #define SYSNUMS_HEADER3 \"syscall/sysnums-x32.h\"\n    #define SYSNUMS_ABI1 sysnums_x86_64\n    #define SYSNUMS_ABI2 sysnums_i386\n    #define SYSNUMS_ABI3 sysnums_x32\n    #undef  SYSTRAP_NUM\n    #define SYSTRAP_NUM SYSARG_RESULT\n    #define SYSTRAP_SIZE 2\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_X86_64, .nb_abis = 2, .abis = { ABI_DEFAULT, ABI_3 } }, { .value = AUDIT_ARCH_I386, .nb_abis = 1, .abis = { ABI_2 } } }\n    #define HOST_ELF_MACHINE {62, 3, 6, 0}\n    #define RED_ZONE_SIZE 128\n    #define OFFSETOF_STAT_UID_32 24\n    #define OFFSETOF_STAT_GID_32 28\n    #define LOADER_ADDRESS 0x600000000000\n    #define HAS_LOADER_32BIT true\n    #define EXEC_PIC_ADDRESS   0x500000000000\n    #define INTERP_PIC_ADDRESS 0x6f0000000000\n    #define EXEC_PIC_ADDRESS_32   0x0f000000\n    #define INTERP_PIC_ADDRESS_32 0xaf000000\n#elif defined(ARCH_ARM_EABI)\n...\n#elif defined(ARCH_ARM64)\n...\n#elif defined(ARCH_RISCV64)\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-riscv64.h\"\n    #define SYSNUMS_ABI1    sysnums_riscv64\n    #define SYSTRAP_SIZE 4\n    #ifndef AUDIT_ARCH_RISCV64\n        #define AUDIT_ARCH_RISCV64 (243 | __AUDIT_ARCH_64BIT | __AUDIT_ARCH_LE)\n    #endif\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_RISCV64, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n    #define HOST_ELF_MACHINE {243, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define LOADER_ADDRESS     0x4000000000\n    #define EXEC_PIC_ADDRESS   0x5000000000\n    #define INTERP_PIC_ADDRESS 0x5f00000000\n#elif defined(ARCH_RISCV32)\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-riscv32.h\"\n    #define SYSNUMS_ABI1    sysnums_riscv32\n    #define SYSTRAP_SIZE 4\n    #ifndef AUDIT_ARCH_RISCV32\n        #define AUDIT_ARCH_RISCV32 (243 | __AUDIT_ARCH_LE)\n    #endif\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_RISCV32, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n    #define HOST_ELF_MACHINE {243, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define NO_MISALIGNED_ACCESS 1\n    #define LOADER_ADDRESS     0x40000000\n    #define EXEC_PIC_ADDRESS   0x50000000\n    #define INTERP_PIC_ADDRESS 0x5f000000\n#elif defined(ARCH_X86)\n...\n#elif defined(ARCH_SH4)\n...\n#else\n#    error \"Unsupported architecture\"\n#endif', 'Line 43 `#define ARCH_X86_64 1` 受 `#if defined(__x86_64__)` 保护，单行不会影响 RISC-V。但架构检测块缺少 RISC-V 分支，`__riscv` 无法匹配，编译时触发 `#error`。最佳实践：在 `#elif defined(__SH4__)` 后插入 `#elif defined(__riscv)`，通过 `__riscv_xlen` 区分 RV64/RV32；`#if !defined(...)` 守卫中补充新宏；在第二块条件编译的 ARCH_ARM64 后新增 ARCH_RISCV64 和 ARCH_RISCV32 小节，配置 ELF 机器 243、seccomp AUDIT_ARCH_RISCV64、无 red zone、loader 地址 0x4000000000；RV32 启用 NO_MISALIGNED_ACCESS。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('10c4b5f1a1057cac61161da021bbe00e', '0', NULL, '2026-07-27 10:11:30', NULL, '2026-07-27 10:11:30', NULL, 'c6ff6c035da9736ca86f235e989a8df6', 'source_code', 'c', 'x86_64', 'risc-v', '#    ifndef PTRACE_EVENT_CLONE\n#        define PTRACE_EVENT_CLONE	3', '#    ifndef PTRACE_EVENT_CLONE\n#        define PTRACE_EVENT_CLONE	3', 'PTRACE_EVENT_CLONE (3) is a generic Linux ptrace event constant from kernel\'s include/uapi/linux/ptrace.h, shared across all architectures including RISC-V. The value is architecture-independent and already correct. No compatibility issue exists.');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('1363c94b042e318cc2e09ebe4f7af2de', '0', NULL, '2026-07-09 13:45:11', NULL, '2026-07-09 13:45:11', NULL, 'c84a09afdce9a324b17d747c233f025b', 'source_code', 'c', 'x86_64', 'risc-v', '#include <sys/queue.h> /* STAILQ_*, */\n#include <unistd.h>    /* getpid(2), close(2), */\n#include <unistd.h>    /* getcwd(2), */\n#include <windows.h>\n\n#include \"cli/cli.h\"', '#include <sys/queue.h> /* STAILQ_*, */\n#include <unistd.h>    /* getpid(2), close(2), */\n#include <unistd.h>    /* getcwd(2), */\n\n#include \"cli/cli.h\"', '#include <windows.h> 是 Windows 专有头文件，在 Linux/RISC-V 上不存在，编译失败。该文件为 PRoot CLI 模块的纯 Linux 源码，未使用任何 Windows API，直接删除即可。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('142ec02fd2e7986fa40f7c3d1628d575', '0', NULL, '2026-07-27 10:15:31', NULL, '2026-07-27 10:15:31', NULL, 'c6ff6c035da9736ca86f235e989a8df6', 'source_code', 'c', 'x86_64', 'risc-v', '#if defined(ARCH_X86_64)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-x86_64.h\"\n    #define SYSNUMS_HEADER2 \"syscall/sysnums-i386.h\"\n    #define SYSNUMS_HEADER3 \"syscall/sysnums-x32.h\"\n\n    #define SYSNUMS_ABI1 sysnums_x86_64\n    #define SYSNUMS_ABI2 sysnums_i386\n    #define SYSNUMS_ABI3 sysnums_x32\n\n    #undef  SYSTRAP_NUM\n    #define SYSTRAP_NUM SYSARG_RESULT\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS {									\\\n		{ .value = AUDIT_ARCH_X86_64, .nb_abis = 2, .abis = { ABI_DEFAULT, ABI_3 } },	\\\n		{ .value = AUDIT_ARCH_I386,   .nb_abis = 1, .abis = { ABI_2 } }, 		\\\n	}\n\n    #define HOST_ELF_MACHINE {62, 3, 6, 0}\n    #define RED_ZONE_SIZE 128\n    #define OFFSETOF_STAT_UID_32 24\n    #define OFFSETOF_STAT_GID_32 28\n\n    #define LOADER_ADDRESS 0x600000000000\n    #define HAS_LOADER_32BIT true\n\n    #define EXEC_PIC_ADDRESS   0x500000000000\n    #define INTERP_PIC_ADDRESS 0x6f0000000000\n    #define EXEC_PIC_ADDRESS_32   0x0f000000\n    #define INTERP_PIC_ADDRESS_32 0xaf000000\n\n#elif defined(ARCH_ARM_EABI)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-arm.h\"\n    #define SYSNUMS_ABI1    sysnums_arm\n\n    #define SYSTRAP_SIZE 4\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_ARM, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define user_regs_struct user_regs\n    #define HOST_ELF_MACHINE {40, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define EM_ARM 40\n\n    #define LOADER_ADDRESS 0x10000000\n\n    #define EXEC_PIC_ADDRESS   0x0f000000\n    #define INTERP_PIC_ADDRESS 0x1f000000\n\n#elif defined(ARCH_ARM64)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-arm64.h\"\n    #define SYSNUMS_ABI1    sysnums_arm64\n\n    #define SYSTRAP_SIZE 4\n\n    #ifndef AUDIT_ARCH_AARCH64\n        #define AUDIT_ARCH_AARCH64 (EM_AARCH64 | __AUDIT_ARCH_64BIT | __AUDIT_ARCH_LE)\n    #endif\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_AARCH64, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {183, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n\n    #define LOADER_ADDRESS     0x2000000000\n    #define EXEC_PIC_ADDRESS   0x3000000000\n    #define INTERP_PIC_ADDRESS 0x3f00000000\n\n#elif defined(ARCH_X86)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-i386.h\"\n    #define SYSNUMS_ABI1    sysnums_i386\n\n    #undef  SYSTRAP_NUM\n    #define SYSTRAP_NUM SYSARG_RESULT\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_I386, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {3, 6, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n\n    #define LOADER_ADDRESS 0xa0000000\n    #define LOADER_ARCH_CFLAGS -mregparm=3\n\n    #define EXEC_PIC_ADDRESS   0x0f000000\n    #define INTERP_PIC_ADDRESS 0xaf000000\n\n#elif defined(ARCH_SH4)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-sh4.h\"\n    #define SYSNUMS_ABI1    sysnums_sh4\n\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS { }\n\n    #define user_regs_struct pt_regs\n    #define HOST_ELF_MACHINE {42, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define NO_MISALIGNED_ACCESS 1\n\n#else\n\n    #error \"Unsupported architecture\"\n\n#endif', '#if defined(ARCH_X86_64)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-x86_64.h\"\n    #define SYSNUMS_HEADER2 \"syscall/sysnums-i386.h\"\n    #define SYSNUMS_HEADER3 \"syscall/sysnums-x32.h\"\n\n    #define SYSNUMS_ABI1 sysnums_x86_64\n    #define SYSNUMS_ABI2 sysnums_i386\n    #define SYSNUMS_ABI3 sysnums_x32\n\n    #undef  SYSTRAP_NUM\n    #define SYSTRAP_NUM SYSARG_RESULT\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS {									\\\n		{ .value = AUDIT_ARCH_X86_64, .nb_abis = 2, .abis = { ABI_DEFAULT, ABI_3 } },	\\\n		{ .value = AUDIT_ARCH_I386,   .nb_abis = 1, .abis = { ABI_2 } }, 		\\\n	}\n\n    #define HOST_ELF_MACHINE {62, 3, 6, 0}\n    #define RED_ZONE_SIZE 128\n    #define OFFSETOF_STAT_UID_32 24\n    #define OFFSETOF_STAT_GID_32 28\n\n    #define LOADER_ADDRESS 0x600000000000\n    #define HAS_LOADER_32BIT true\n\n    #define EXEC_PIC_ADDRESS   0x500000000000\n    #define INTERP_PIC_ADDRESS 0x6f0000000000\n    #define EXEC_PIC_ADDRESS_32   0x0f000000\n    #define INTERP_PIC_ADDRESS_32 0xaf000000\n\n#elif defined(ARCH_ARM_EABI)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-arm.h\"\n    #define SYSNUMS_ABI1    sysnums_arm\n\n    #define SYSTRAP_SIZE 4\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_ARM, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define user_regs_struct user_regs\n    #define HOST_ELF_MACHINE {40, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define EM_ARM 40\n\n    #define LOADER_ADDRESS 0x10000000\n\n    #define EXEC_PIC_ADDRESS   0x0f000000\n    #define INTERP_PIC_ADDRESS 0x1f000000\n\n#elif defined(ARCH_ARM64)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-arm64.h\"\n    #define SYSNUMS_ABI1    sysnums_arm64\n\n    #define SYSTRAP_SIZE 4\n\n    #ifndef AUDIT_ARCH_AARCH64\n        #define AUDIT_ARCH_AARCH64 (EM_AARCH64 | __AUDIT_ARCH_64BIT | __AUDIT_ARCH_LE)\n    #endif\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_AARCH64, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {183, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n\n    #define LOADER_ADDRESS     0x2000000000\n    #define EXEC_PIC_ADDRESS   0x3000000000\n    #define INTERP_PIC_ADDRESS 0x3f00000000\n\n#elif defined(ARCH_X86)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-i386.h\"\n    #define SYSNUMS_ABI1    sysnums_i386\n\n    #undef  SYSTRAP_NUM\n    #define SYSTRAP_NUM SYSARG_RESULT\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_I386, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {3, 6, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n\n    #define LOADER_ADDRESS 0xa0000000\n    #define LOADER_ARCH_CFLAGS -mregparm=3\n\n    #define EXEC_PIC_ADDRESS   0x0f000000\n    #define INTERP_PIC_ADDRESS 0xaf000000\n\n#elif defined(ARCH_SH4)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-sh4.h\"\n    #define SYSNUMS_ABI1    sysnums_sh4\n\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS { }\n\n    #define user_regs_struct pt_regs\n    #define HOST_ELF_MACHINE {42, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define NO_MISALIGNED_ACCESS 1\n\n#elif defined(ARCH_RISCV)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-riscv64.h\"\n    #define SYSNUMS_ABI1    sysnums_riscv64\n\n    #define SYSTRAP_SIZE 4\n\n    #ifndef AUDIT_ARCH_RISCV64\n        #define AUDIT_ARCH_RISCV64 (243 | __AUDIT_ARCH_64BIT | __AUDIT_ARCH_LE)\n    #endif\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_RISCV64, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {243, 0}\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define NO_MISALIGNED_ACCESS 1\n\n    #define LOADER_ADDRESS     0x2000000000\n    #define EXEC_PIC_ADDRESS   0x3000000000\n    #define INTERP_PIC_ADDRESS 0x3f00000000\n\n#else\n\n    #error \"Unsupported architecture\"\n\n#endif', 'arch.h line 66 (x86_64 SYSNUMS_ABI1) is inside the ARCH_X86_64 block with no ARCH_RISCV case in the #elif chain. Added ARCH_RISCV block: EM_RISCV=243, AUDIT_ARCH_RISCV64, ecall 4-byte trap, no red zone, single ABI (no 32-bit compat), misaligned access unsafe.');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('14bc7359f6aa65afd65a351631bfef7d', '0', NULL, '2026-07-27 11:00:50', NULL, '2026-07-27 11:00:50', NULL, '01df88b254c9685e4e2e630c69542e86', 'source_code', 'c', 'x86_64', 'risc-v', '#include <string.h>\n#include <stdlib.h>\n#include \"arch.h\"\n\nvoid *aligned_alloc_wrapper(size_t alignment, size_t size) {\n#if defined(__x86_64__) || defined(__aarch64__)\n    void *ptr;\n    int ret = posix_memalign(&ptr, alignment, size);\n    return ret == 0 ? ptr : NULL;\n#else\n    void *ptr;\n    int ret = posix_memalign(&ptr, alignment, size);\n    return ret == 0 ? ptr : NULL;\n#endif\n}\n\nvoid memory_barrier(void) {\n    mb();\n}\n\nsize_t get_cache_line_size(void) {\n    return CACHE_LINE_SIZE;\n}', '#include <string.h>\n#include <stdlib.h>\n#include \"arch.h\"\n\nvoid *aligned_alloc_wrapper(size_t alignment, size_t size) {\n    void *ptr;\n    int ret = posix_memalign(&ptr, alignment, size);\n    return ret == 0 ? ptr : NULL;\n}\n\nvoid memory_barrier(void) {\n    mb();\n}\n\nsize_t get_cache_line_size(void) {\n    return CACHE_LINE_SIZE;\n}', '第6行 #if defined(__x86_64__) || defined(__aarch64__) 将RISC-V排除在外，但两分支代码完全相同（均调用posix_memalign）。posix_memalign是POSIX标准接口，在RISC-V(glibc/musl/uclibc)上完全支持，无需架构分支。直接删除条件编译包裹，保留单一实现即可。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('14f95cd6281dc0b9675cab80476f9982', '0', NULL, '2026-07-27 11:01:50', NULL, '2026-07-27 11:01:50', NULL, '01df88b254c9685e4e2e630c69542e86', 'source_code', 'c', 'x86_64', 'risc-v', '#include <stdio.h>\n#include <stdlib.h>\n#include \"arch.h\"\n\n#ifdef __x86_64__\n  #define ARCH_NAME \"x86_64\"\n#elif defined(__aarch64__)\n  #define ARCH_NAME \"aarch64\"\n#else\n  #define ARCH_NAME \"unknown\"\n#endif\n\nint main(int argc, char **argv) {\n    printf(\"Hello from %s\\n\", ARCH_NAME);\n\n    return 0;\n}', '#include <stdio.h>\n#include <stdlib.h>\n#include \"arch.h\"\n\n#ifdef __x86_64__\n  #define ARCH_NAME \"x86_64\"\n#elif defined(__aarch64__)\n  #define ARCH_NAME \"aarch64\"\n#elif defined(__riscv)\n  #define ARCH_NAME \"riscv\"\n#else\n  #define ARCH_NAME \"unknown\"\n#endif\n\nint main(int argc, char **argv) {\n    printf(\"Hello from %s\\n\", ARCH_NAME);\n\n    return 0;\n}', '第5-11行条件编译链 #ifdef __x86_64__ / #elif defined(__aarch64__) / #else 未包含RISC-V检测，导致RISC-V平台ARCH_NAME被定义为\"unknown\"。适配方案：在aarch64分支后新增 #elif defined(__riscv) 分支，正确识别RISC-V架构名称。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('1d1251ca083961856efcbc87f88f0182', '0', NULL, '2026-07-09 13:41:50', NULL, '2026-07-09 13:41:50', NULL, 'c84a09afdce9a324b17d747c233f025b', 'source_code', 'c', 'x86_64', 'risc-v', '#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    elif defined(__riscv) && __riscv_xlen == 64\n#        define ARCH_RISCV64 1', '#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    elif defined(__riscv) && __riscv_xlen == 64\n#        define ARCH_RISCV64 1', '该行为 ARM64 (aarch64) 架构定义分支，与 RISC-V 无关。RISC-V 编译时通过 __riscv && __riscv_xlen == 64 分支匹配，不会进入此路径，无需修改。');
