INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('2a7a5e89f1a720ba774b9eea623775f8', '0', NULL, '2026-07-27 10:17:41', NULL, '2026-07-27 10:17:41', NULL, 'c6ff6c035da9736ca86f235e989a8df6', 'source_code', 'c', 'arm', 'risc-v', '#elif defined(ARCH_ARM_EABI)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-arm.h\"\n    #define SYSNUMS_ABI1    sysnums_arm\n\n    #define SYSTRAP_SIZE 4\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_ARM, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define user_regs_struct user_regs\n    #define HOST_ELF_MACHINE {40, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define EM_ARM 40\n\n    #define LOADER_ADDRESS 0x10000000\n\n    #define EXEC_PIC_ADDRESS   0x0f000000\n    #define INTERP_PIC_ADDRESS 0x1f000000\n\n#elif defined(ARCH_ARM64)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-arm64.h\"\n    #define SYSNUMS_ABI1    sysnums_arm64\n\n    #define SYSTRAP_SIZE 4\n\n    #ifndef AUDIT_ARCH_AARCH64\n        #define AUDIT_ARCH_AARCH64 (EM_AARCH64 | __AUDIT_ARCH_64BIT | __AUDIT_ARCH_LE)\n    #endif\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_AARCH64, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {183, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n\n    #define LOADER_ADDRESS     0x2000000000\n    #define EXEC_PIC_ADDRESS   0x3000000000\n    #define INTERP_PIC_ADDRESS 0x3f00000000\n\n#elif defined(ARCH_X86)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-i386.h\"\n    #define SYSNUMS_ABI1    sysnums_i386\n\n    #undef  SYSTRAP_NUM\n    #define SYSTRAP_NUM SYSARG_RESULT\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_I386, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {3, 6, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n\n    #define LOADER_ADDRESS 0xa0000000\n    #define LOADER_ARCH_CFLAGS -mregparm=3\n\n    #define EXEC_PIC_ADDRESS   0x0f000000\n    #define INTERP_PIC_ADDRESS 0xaf000000\n\n#elif defined(ARCH_SH4)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-sh4.h\"\n    #define SYSNUMS_ABI1    sysnums_sh4\n\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS { }\n\n    #define user_regs_struct pt_regs\n    #define HOST_ELF_MACHINE {42, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define NO_MISALIGNED_ACCESS 1\n\n#else\n\n    #error \"Unsupported architecture\"\n\n#endif', '#elif defined(ARCH_ARM_EABI)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-arm.h\"\n    #define SYSNUMS_ABI1    sysnums_arm\n\n    #define SYSTRAP_SIZE 4\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_ARM, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define user_regs_struct user_regs\n    #define HOST_ELF_MACHINE {40, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define EM_ARM 40\n\n    #define LOADER_ADDRESS 0x10000000\n\n    #define EXEC_PIC_ADDRESS   0x0f000000\n    #define INTERP_PIC_ADDRESS 0x1f000000\n\n#elif defined(ARCH_ARM64)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-arm64.h\"\n    #define SYSNUMS_ABI1    sysnums_arm64\n\n    #define SYSTRAP_SIZE 4\n\n    #ifndef AUDIT_ARCH_AARCH64\n        #define AUDIT_ARCH_AARCH64 (EM_AARCH64 | __AUDIT_ARCH_64BIT | __AUDIT_ARCH_LE)\n    #endif\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_AARCH64, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {183, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n\n    #define LOADER_ADDRESS     0x2000000000\n    #define EXEC_PIC_ADDRESS   0x3000000000\n    #define INTERP_PIC_ADDRESS 0x3f00000000\n\n#elif defined(ARCH_X86)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-i386.h\"\n    #define SYSNUMS_ABI1    sysnums_i386\n\n    #undef  SYSTRAP_NUM\n    #define SYSTRAP_NUM SYSARG_RESULT\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_I386, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {3, 6, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n\n    #define LOADER_ADDRESS 0xa0000000\n    #define LOADER_ARCH_CFLAGS -mregparm=3\n\n    #define EXEC_PIC_ADDRESS   0x0f000000\n    #define INTERP_PIC_ADDRESS 0xaf000000\n\n#elif defined(ARCH_SH4)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-sh4.h\"\n    #define SYSNUMS_ABI1    sysnums_sh4\n\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS { }\n\n    #define user_regs_struct pt_regs\n    #define HOST_ELF_MACHINE {42, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define NO_MISALIGNED_ACCESS 1\n\n#elif defined(ARCH_RISCV)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-riscv64.h\"\n    #define SYSNUMS_ABI1    sysnums_riscv64\n\n    #define SYSTRAP_SIZE 4\n\n    #ifndef AUDIT_ARCH_RISCV64\n        #define AUDIT_ARCH_RISCV64 (243 | __AUDIT_ARCH_64BIT | __AUDIT_ARCH_LE)\n    #endif\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_RISCV64, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {243, 0}\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define NO_MISALIGNED_ACCESS 1\n\n    #define LOADER_ADDRESS     0x2000000000\n    #define EXEC_PIC_ADDRESS   0x3000000000\n    #define INTERP_PIC_ADDRESS 0x3f00000000\n\n#else\n\n    #error \"Unsupported architecture\"\n\n#endif', 'arch.h line 95 (ARM EABI SYSNUMS_ABI1) is inside the ARCH_ARM_EABI block; the #elif chain has no ARCH_RISCV case. Added ARCH_RISCV block: EM_RISCV=243, AUDIT_ARCH_RISCV64, ecall 4-byte trap, no red zone, single ABI, misaligned access unsafe. RISC-V rv64eb (LP64) matches ARM64\'s single-ABI pattern.');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('2c10ac4431ce094356accdfb61c5f201', '0', NULL, '2026-07-14 12:54:21', NULL, '2026-07-14 12:54:21', NULL, 'b841e87e115b14f59294b60baa81ac64', 'source_code', 'c', 'arm', 'risc-v', '#include \"../src/arch.h\"\n\n#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_X86) && !defined(ARCH_SH4)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif', '#include \"../src/arch.h\"\n\n#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_X86) && !defined(ARCH_SH4) && !defined(ARCH_ARM64) && !defined(ARCH_RISCV64) && !defined(ARCH_RISCV32)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    elif defined(__riscv)\n#        if __riscv_xlen == 64\n#            define ARCH_RISCV64 1\n#        elif __riscv_xlen == 32\n#            define ARCH_RISCV32 1\n#        else\n#            error \"Unsupported RISC-V XLEN\"\n#        endif\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif', 'Line 47 `#error \"Only EABI is currently supported for ARM\"` 受 `#elif defined(__arm__)` 保护，仅 ARM 非 EABI 编译时触发，不影响 RISC-V。但该文件复制了 arch.h 的架构检测逻辑，整体缺少 RISC-V 分支，`__riscv` 无法匹配，编译触发 `#else` 的 `#error`。最佳实践：在 `#elif defined(__SH4__)` 后插入 `#elif defined(__riscv)`，依 __riscv_xlen 区分 RV64/RV32；同步在 `#if !defined(...)` 守卫中补充新宏。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('2c1263dbc2bf27250ca9ac1f69a3823b', '0', NULL, '2026-07-27 11:02:00', NULL, '2026-07-27 11:02:00', NULL, '01df88b254c9685e4e2e630c69542e86', 'source_code', 'c', 'x86_64', 'risc-v', '#include <stdio.h>\n#include <stdlib.h>\n#include \"arch.h\"\n\n#ifdef __x86_64__\n  #define ARCH_NAME \"x86_64\"\n#elif defined(__aarch64__)\n  #define ARCH_NAME \"aarch64\"\n#else\n  #define ARCH_NAME \"unknown\"\n#endif\n\nint main(int argc, char **argv) {\n    printf(\"Hello from %s\\n\", ARCH_NAME);\n\n    return 0;\n}', '#include <stdio.h>\n#include <stdlib.h>\n#include \"arch.h\"\n\n#ifdef __x86_64__\n  #define ARCH_NAME \"x86_64\"\n#elif defined(__aarch64__)\n  #define ARCH_NAME \"aarch64\"\n#elif defined(__riscv)\n  #define ARCH_NAME \"riscv\"\n#else\n  #define ARCH_NAME \"unknown\"\n#endif\n\nint main(int argc, char **argv) {\n    printf(\"Hello from %s\\n\", ARCH_NAME);\n\n    return 0;\n}', '第5-11行条件编译链 #ifdef __x86_64__ / #elif defined(__aarch64__) / #else 未包含RISC-V检测，RISC-V平台ARCH_NAME被定义为\"unknown\"。适配方案：在aarch64分支后新增 #elif defined(__riscv) 分支，确保RISC-V架构名称被正确识别。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('2d590da43bf5121b3fd2028bfd5350b2', '0', NULL, '2026-07-27 10:15:51', NULL, '2026-07-27 10:15:51', NULL, 'c6ff6c035da9736ca86f235e989a8df6', 'source_code', 'c', 'x86', 'risc-v', '#elif defined(ARCH_X86)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-i386.h\"\n    #define SYSNUMS_ABI1    sysnums_i386\n\n    #undef  SYSTRAP_NUM\n    #define SYSTRAP_NUM SYSARG_RESULT\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_I386, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {3, 6, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n\n    #define LOADER_ADDRESS 0xa0000000\n    #define LOADER_ARCH_CFLAGS -mregparm=3\n\n    #define EXEC_PIC_ADDRESS   0x0f000000\n    #define INTERP_PIC_ADDRESS 0xaf000000\n\n#elif defined(ARCH_SH4)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-sh4.h\"\n    #define SYSNUMS_ABI1    sysnums_sh4\n\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS { }\n\n    #define user_regs_struct pt_regs\n    #define HOST_ELF_MACHINE {42, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define NO_MISALIGNED_ACCESS 1\n\n#else\n\n    #error \"Unsupported architecture\"\n\n#endif', '#elif defined(ARCH_X86)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-i386.h\"\n    #define SYSNUMS_ABI1    sysnums_i386\n\n    #undef  SYSTRAP_NUM\n    #define SYSTRAP_NUM SYSARG_RESULT\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_I386, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {3, 6, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n\n    #define LOADER_ADDRESS 0xa0000000\n    #define LOADER_ARCH_CFLAGS -mregparm=3\n\n    #define EXEC_PIC_ADDRESS   0x0f000000\n    #define INTERP_PIC_ADDRESS 0xaf000000\n\n#elif defined(ARCH_SH4)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-sh4.h\"\n    #define SYSNUMS_ABI1    sysnums_sh4\n\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS { }\n\n    #define user_regs_struct pt_regs\n    #define HOST_ELF_MACHINE {42, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define NO_MISALIGNED_ACCESS 1\n\n#elif defined(ARCH_RISCV)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-riscv64.h\"\n    #define SYSNUMS_ABI1    sysnums_riscv64\n\n    #define SYSTRAP_SIZE 4\n\n    #ifndef AUDIT_ARCH_RISCV64\n        #define AUDIT_ARCH_RISCV64 (243 | __AUDIT_ARCH_64BIT | __AUDIT_ARCH_LE)\n    #endif\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_RISCV64, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {243, 0}\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define NO_MISALIGNED_ACCESS 1\n\n    #define LOADER_ADDRESS     0x2000000000\n    #define EXEC_PIC_ADDRESS   0x3000000000\n    #define INTERP_PIC_ADDRESS 0x3f00000000\n\n#else\n\n    #error \"Unsupported architecture\"\n\n#endif', 'arch.h line 152 defines LOADER_ARCH_CFLAGS=-mregparm=3 (x86-specific register arg passing) inside the ARCH_X86 block. The #elif chain has no ARCH_RISCV case. Added ARCH_RISCV block: EM_RISCV=243, AUDIT_ARCH_RISCV64, ecall 4-byte, no red zone, no -mregparm equivalent (RISC-V uses standard a0-a7 calling convention), misaligned access unsafe.');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('2e870704c7db4f6499b627ea867631ac', '0', NULL, '2026-07-27 11:03:00', NULL, '2026-07-27 11:03:00', NULL, '01df88b254c9685e4e2e630c69542e86', 'source_code', 'c', 'arm64', 'risc-v', '#ifndef ARCH_H\n#define ARCH_H\n\n#if defined(__x86_64__)\n  #define CACHE_LINE_SIZE 64\n  #define mb()  asm volatile(\"mfence\" ::: \"memory\")\n  #define rmb() asm volatile(\"lfence\" ::: \"memory\")\n  #define wmb() asm volatile(\"sfence\" ::: \"memory\")\n#elif defined(__aarch64__)\n  #define CACHE_LINE_SIZE 64\n  #define mb()  asm volatile(\"dmb ish\" ::: \"memory\")\n  #define rmb() asm volatile(\"dmb ishld\" ::: \"memory\")\n  #define wmb() asm volatile(\"dmb ishst\" ::: \"memory\")\n#else\n  #define CACHE_LINE_SIZE 64\n  #define mb()  /* TODO: RISC-V fence */\n  #define rmb() /* TODO: RISC-V fence */\n  #define wmb() /* TODO: RISC-V fence */\n#endif\n\n#endif', '#ifndef ARCH_H\n#define ARCH_H\n\n#if defined(__x86_64__)\n  #define CACHE_LINE_SIZE 64\n  #define mb()  asm volatile(\"mfence\" ::: \"memory\")\n  #define rmb() asm volatile(\"lfence\" ::: \"memory\")\n  #define wmb() asm volatile(\"sfence\" ::: \"memory\")\n#elif defined(__aarch64__)\n  #define CACHE_LINE_SIZE 64\n  #define mb()  asm volatile(\"dmb ish\" ::: \"memory\")\n  #define rmb() asm volatile(\"dmb ishld\" ::: \"memory\")\n  #define wmb() asm volatile(\"dmb ishst\" ::: \"memory\")\n#elif defined(__riscv)\n  #define CACHE_LINE_SIZE 64\n  #define mb()  asm volatile(\"fence iorw, iorw\" ::: \"memory\")\n  #define rmb() asm volatile(\"fence ir, ir\" ::: \"memory\")\n  #define wmb() asm volatile(\"fence ow, ow\" ::: \"memory\")\n#else\n  #define CACHE_LINE_SIZE 64\n  #define mb()  /* TODO: RISC-V fence */\n  #define rmb() /* TODO: RISC-V fence */\n  #define wmb() /* TODO: RISC-V fence */\n#endif\n\n#endif', '第9行 #elif defined(__aarch64__) 开始的条件编译链仅覆盖x86_64和aarch64，缺少__riscv分支，RISC-V落入#else导致内存屏障为空实现。适配方案：在aarch64后新增 #elif defined(__riscv) 分支，使用fence指令实现完整内存屏障语义，确保RISC-V平台的内存序正确性。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('30b69dcb4ed2afddaada507164092aef', '0', NULL, '2026-07-09 13:41:40', NULL, '2026-07-09 13:41:40', NULL, 'c84a09afdce9a324b17d747c233f025b', 'source_code', 'c', 'x86_64', 'risc-v', '#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    elif defined(__riscv) && __riscv_xlen == 64\n#        define ARCH_RISCV64 1\n#    else\n#        error \"Unsupported architecture\"\n#    endif', '#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    elif defined(__riscv) && __riscv_xlen == 64\n#        define ARCH_RISCV64 1\n#    else\n#        error \"Unsupported architecture\"\n#    endif', '该行为 x86_64 架构定义分支，与 RISC-V 无关。RISC-V 编译时通过 __riscv && __riscv_xlen == 64 分支匹配，不会进入此路径，无需修改。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('339226e3db164f9249cff2de9512dc11', '0', NULL, '2026-07-09 13:44:21', NULL, '2026-07-09 13:44:21', NULL, 'c84a09afdce9a324b17d747c233f025b', 'source_code', 'c', 'x86_64', 'risc-v', '#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    else\n#        error \"Unsupported architecture\"\n#    endif', '#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    elif defined(__riscv) && __riscv_xlen == 64\n#        define ARCH_RISCV64 1\n#    else\n#        error \"Unsupported architecture\"\n#    endif', '该行为 ARM（非 EABI）架构错误处理分支，仅当 __arm__ 定义时触发，与 RISC-V 无关。RISC-V 编译时通过新增的 __riscv && __riscv_xlen == 64 分支匹配，不会进入此路径，无需修改该行。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('369f51fa3adf890c9532e7536fa0821d', '0', NULL, '2026-07-27 10:11:00', NULL, '2026-07-27 10:11:00', NULL, 'c6ff6c035da9736ca86f235e989a8df6', 'source_code', 'c', 'x86_64', 'risc-v', '#    ifndef PTRACE_EVENT_VFORK_DONE\n#        define PTRACE_EVENT_VFORK_DONE	5', '#    ifndef PTRACE_EVENT_VFORK_DONE\n#        define PTRACE_EVENT_VFORK_DONE	5', 'PTRACE_EVENT_VFORK_DONE (5) is a generic Linux ptrace event constant from kernel\'s include/uapi/linux/ptrace.h, shared across all architectures including RISC-V. The value is architecture-independent and already correct. No compatibility issue exists.');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('3b5126f4b0a56278303fa19eca0a1803', '0', NULL, '2026-07-27 10:18:42', NULL, '2026-07-27 10:18:42', NULL, 'c6ff6c035da9736ca86f235e989a8df6', 'source_code', 'c', 'x86_64', 'risc-v', '#ifndef ARCHIVE_H\n#define ARCHIVE_H\n\n#include <sys/types.h>\n#include <sys/stat.h>\n#include <stdint.h>\n\n#include \"tracee/tracee.h\"\n\ntypedef struct {\n	struct archive *handle;\n	struct archive_entry_linkresolver *hardlink_resolver;\n\n	off_t offset;\n	int fd;\n} Archive;\n\nextern Archive *new_archive(TALLOC_CTX *context, const Tracee* tracee,\n				const char *output, size_t *prefix_length);\nextern int finalize_archive(Archive *archive);\nextern int archive(const Tracee* tracee, Archive *archive,\n		const char *path, const char *alternate_path, const struct stat *statl);\n\n#endif', '#ifndef ARCHIVE_H\n#define ARCHIVE_H\n\n#include <sys/types.h>\n#include <sys/stat.h>\n#include <stdint.h>\n\n#include \"tracee/tracee.h\"\n\ntypedef struct {\n	struct archive *handle;\n	struct archive_entry_linkresolver *hardlink_resolver;\n\n	off_t offset;\n	int fd;\n} Archive;\n\nextern Archive *new_archive(TALLOC_CTX *context, const Tracee* tracee,\n				const char *output, size_t *prefix_length);\nextern int finalize_archive(Archive *archive);\nextern int archive(const Tracee* tracee, Archive *archive,\n		const char *path, const char *alternate_path, const struct stat *statl);\n\n#endif', 'archive.h line 24 is a plain header guard (#define ARCHIVE_H) with no architecture-specific code. The file contains only standard C types (off_t, size_t, struct stat) and a forward declaration, all of which are architecture-independent. No RISC-V compatibility changes needed.');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('3fa4fbc9a67e9d7ae35c7b3555a13b24', '0', NULL, '2026-07-09 13:41:20', NULL, '2026-07-09 13:41:20', NULL, 'c84a09afdce9a324b17d747c233f025b', 'source_code', 'c', 'x86_64', 'risc-v', '#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    elif defined(__riscv) && __riscv_xlen == 64\n#        define ARCH_RISCV64 1', '#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    elif defined(__riscv) && __riscv_xlen == 64\n#        define ARCH_RISCV64 1', '该行为 SH4 架构定义，与 RISC-V 无关。RISC-V 编译时通过 __riscv && __riscv_xlen == 64 分支（已在 #elif 链中新增），不会进入 SH4 分支，无需修改。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('44e9db057a486a0e44301f1040c9b818', '0', NULL, '2026-07-09 13:42:20', NULL, '2026-07-09 13:42:20', NULL, 'c84a09afdce9a324b17d747c233f025b', 'source_code', 'c', 'x86_64', 'risc-v', '#include <sys/prctl.h>     /* prctl(2), PR_* */\n#include <linux/seccomp.h> /* SECCOMP_MODE_FILTER, */\n#include <linux/filter.h>  /* struct sock_*, */\n#include <linux/audit.h>   /* AUDIT_ARCH_*, */\n#include <stddef.h>        /* offsetof(3), */\n#include <windows.h>\n\nint main(void)\n{\n	const size_t arch_offset    = offsetof(struct seccomp_data, arch);\n	const size_t syscall_offset = offsetof(struct seccomp_data, nr);\n	struct sock_fprog program;\n\n	#define ARCH_NR AUDIT_ARCH_X86_64', '#include <sys/prctl.h>     /* prctl(2), PR_* */\n#include <linux/seccomp.h> /* SECCOMP_MODE_FILTER, */\n#include <linux/filter.h>  /* struct sock_*, */\n#include <linux/audit.h>   /* AUDIT_ARCH_*, */\n#include <stddef.h>        /* offsetof(3), */\n\n#ifndef AUDIT_ARCH_RISCV64\n#define AUDIT_ARCH_RISCV64 (243 | 0x80000000 | 0x40000000) /* EM_RISCV | 64BIT | LE */\n#endif\n\nint main(void)\n{\n	const size_t arch_offset    = offsetof(struct seccomp_data, arch);\n	const size_t syscall_offset = offsetof(struct seccomp_data, nr);\n	struct sock_fprog program;\n\n	#define ARCH_NR AUDIT_ARCH_RISCV64', '问题1：#include <windows.h> 是 Windows 专有头文件，在 Linux/RISC-V 上不存在，编译失败，直接删除。问题2：#define ARCH_NR AUDIT_ARCH_X86_64 硬编码 x86_64 审计架构值，在 RISC-V 上 seccomp 过滤器无法匹配正确的架构，会导致 seccomp 规则失效；已替换为 AUDIT_ARCH_RISCV64 并前置条件定义（兼容旧内核头文件）。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('45dca10dbda794cb2df2f17036ca5972', '0', NULL, '2026-07-14 12:54:31', NULL, '2026-07-14 12:54:31', NULL, 'b841e87e115b14f59294b60baa81ac64', 'source_code', 'c', 'x86_64/arm64', 'risc-v', '#include \"../src/arch.h\"\n\n#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_X86) && !defined(ARCH_SH4)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif', '#include \"../src/arch.h\"\n\n#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_X86) && !defined(ARCH_SH4) && !defined(ARCH_ARM64) && !defined(ARCH_RISCV64) && !defined(ARCH_RISCV32)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    elif defined(__riscv)\n#        if __riscv_xlen == 64\n#            define ARCH_RISCV64 1\n#        elif __riscv_xlen == 32\n#            define ARCH_RISCV32 1\n#        else\n#            error \"Unsupported RISC-V XLEN\"\n#        endif\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif', 'Line 49 `#elif defined(__i386__)` 受 `#elif` 保护，仅 x86 32 位编译时激活，不影响 RISC-V。但该文件复制了 arch.h 的架构检测逻辑，缺少 RISC-V 分支，RISC-V 编译触发 `#else` 的 `#error`。最佳实践：在 `#elif defined(__SH4__)` 后插入 `#elif defined(__riscv)`，依 __riscv_xlen 区分 RV64/RV32；同步在 `#if !defined(...)` 守卫中补充 ARCH_ARM64、ARCH_RISCV64、ARCH_RISCV32。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('48ee967d383b36db632df766dfd5e1e4', '0', NULL, '2026-07-14 12:55:01', NULL, '2026-07-14 12:55:01', NULL, 'b841e87e115b14f59294b60baa81ac64', 'source_code', 'c', 'arm', 'risc-v', '#include \"../src/arch.h\"\n\n#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_X86) && !defined(ARCH_SH4)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif', '#include \"../src/arch.h\"\n\n#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_X86) && !defined(ARCH_SH4) && !defined(ARCH_ARM64) && !defined(ARCH_RISCV64) && !defined(ARCH_RISCV32)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    elif defined(__riscv)\n#        if __riscv_xlen == 64\n#            define ARCH_RISCV64 1\n#        elif __riscv_xlen == 32\n#            define ARCH_RISCV32 1\n#        else\n#            error \"Unsupported RISC-V XLEN\"\n#        endif\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif', 'Line 43 `#elif defined(__ARM_EABI__)` 受 `#elif` 保护，仅 ARM EABI 编译时激活，不影响 RISC-V。但该文件复制了 arch.h 的架构检测逻辑，缺少 RISC-V 分支，RISC-V 编译触发 `#else` 的 `#error`。最佳实践：在 `#elif defined(__SH4__)` 后插入 `#elif defined(__riscv)`，依 __riscv_xlen 区分 RV64/RV32；同步在 `#if !defined(...)` 守卫中补充新宏。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('4aa61f5b56956816e41861b5160d771f', '0', NULL, '2026-07-09 13:44:41', NULL, '2026-07-09 13:44:41', NULL, 'c84a09afdce9a324b17d747c233f025b', 'source_code', 'c', 'x86_64', 'risc-v', '#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    elif defined(__riscv) && __riscv_xlen == 64\n#        define ARCH_RISCV64 1\n#    else\n#        error \"Unsupported architecture\"\n#    endif', '#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    elif defined(__riscv) && __riscv_xlen == 64\n#        define ARCH_RISCV64 1\n#    else\n#        error \"Unsupported architecture\"\n#    endif', '该行为 x86_64 架构检测分支，与 RISC-V 无关。RISC-V 编译时通过 __riscv && __riscv_xlen == 64 分支匹配，不会进入此路径，无需修改。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('4be482b3a7365d7f2d43385ea36393dc', '0', NULL, '2026-07-27 10:13:20', NULL, '2026-07-27 10:13:20', NULL, 'c6ff6c035da9736ca86f235e989a8df6', 'source_code', 'c', 'x86_64', 'risc-v', '#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_X86) && !defined(ARCH_SH4)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif', '#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_ARM64) && !defined(ARCH_X86) && !defined(ARCH_SH4) && !defined(ARCH_RISCV)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    elif defined(__riscv)\n#        if __riscv_xlen == 64\n#            define ARCH_RISCV 1\n#        else\n#            error \"Only 64-bit RISC-V is supported\"\n#        endif\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif', 'arch.h line 48 (ARM non-EABI error) is part of the arch auto-detection chain that lacks a __riscv case. RISC-V compilation triggers \'Unsupported architecture\' at line 55. Added __riscv detection: __riscv_xlen==64 sets ARCH_RISCV, rv32 errors out. Also added ARCH_ARM64 and ARCH_RISCV to the outer guard at line 41.');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('4dcfcf23352be25472974dceb60ccc09', '0', NULL, '2026-07-14 12:51:50', NULL, '2026-07-14 12:51:50', NULL, 'b841e87e115b14f59294b60baa81ac64', 'source_code', 'c', 'x86_32', 'risc-v', '/* According to the x86 ABI, all registers have undefined values at\n * program startup except:\n *\n * - the instruction pointer (rip)\n * - the stack pointer (rsp)\n * - the rtld_fini pointer (rdx)\n * - the system flags (eflags)\n */\n#define BRANCH(stack_pointer, destination) do {			\\\n	asm volatile (						\\\n		\"// Restore initial stack pointer.	\\n\\t\"	\\\n		\"movl %0, %%esp				\\n\\t\"	\\\n		\"                      			\\n\\t\"	\\\n		\"// Clear state flags.			\\n\\t\"	\\\n		\"pushl $0				\\n\\t\"	\\\n		\"popfl					\\n\\t\"	\\\n		\"                      			\\n\\t\"	\\\n		\"// Clear rtld_fini.			\\n\\t\"	\\\n		\"movl $0, %%edx				\\n\\t\"	\\\n		\"                      			\\n\\t\"	\\\n		\"// Start the program.			\\n\\t\"	\\\n		\"jmpl *%%eax				\\n\"	\\\n		: /* no output */				\\\n		: \"irm\" (stack_pointer), \"a\" (destination)	\\\n		: \"memory\", \"cc\", \"esp\", \"edx\");		\\\n	__builtin_unreachable();				\\\n	} while (0)', '/* According to the RISC-V ABI, all registers have undefined values\n * at program startup except:\n *\n * - the instruction pointer (pc)\n * - the stack pointer (sp)\n */\n#define BRANCH(stack_pointer, destination) do {			\\\n	asm volatile (						\\\n		\"// Restore initial stack pointer.	\\n\\t\"	\\\n		\"mv sp, %0				\\n\\t\"	\\\n		\"                      			\\n\\t\"	\\\n		\"// Start the program.			\\n\\t\"	\\\n		\"jalr zero, %1, 0			\\n\"	\\\n		: /* no output */				\\\n		: \"r\" (stack_pointer), \"r\" (destination)	\\\n		: \"memory\", \"sp\");				\\\n	__builtin_unreachable();				\\\n	} while (0)', 'BRANCH 宏含 x86 内联汇编（movl/pushl/popfl/jmpl 及 esp/edx/eax 寄存器），RISC-V 完全不兼容。RISC-V 无 EFLAGS，无需 popfl；无 rtld_fini 专用寄存器，无需清零 edx。适配：用 `mv sp, %0` 设栈指针，`jalr zero, %1, 0` 间接跳转（zero 丢弃 ra），约束改用通用 \"r\"，clobber 仅 \"memory\" 和 \"sp\"，删除 \"cc\" 和 \"edx\"。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('4dd76ef12f097c8edb79c3581a724d88', '0', NULL, '2026-07-27 10:18:11', NULL, '2026-07-27 10:18:11', NULL, 'c6ff6c035da9736ca86f235e989a8df6', 'source_code', 'c', 'x86', 'risc-v', '#elif defined(ARCH_X86)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-i386.h\"\n    #define SYSNUMS_ABI1    sysnums_i386\n\n    #undef  SYSTRAP_NUM\n    #define SYSTRAP_NUM SYSARG_RESULT\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_I386, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {3, 6, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n\n    #define LOADER_ADDRESS 0xa0000000\n    #define LOADER_ARCH_CFLAGS -mregparm=3\n\n    #define EXEC_PIC_ADDRESS   0x0f000000\n    #define INTERP_PIC_ADDRESS 0xaf000000\n\n#elif defined(ARCH_SH4)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-sh4.h\"\n    #define SYSNUMS_ABI1    sysnums_sh4\n\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS { }\n\n    #define user_regs_struct pt_regs\n    #define HOST_ELF_MACHINE {42, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define NO_MISALIGNED_ACCESS 1\n\n#else\n\n    #error \"Unsupported architecture\"\n\n#endif', '#elif defined(ARCH_X86)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-i386.h\"\n    #define SYSNUMS_ABI1    sysnums_i386\n\n    #undef  SYSTRAP_NUM\n    #define SYSTRAP_NUM SYSARG_RESULT\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_I386, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {3, 6, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n\n    #define LOADER_ADDRESS 0xa0000000\n    #define LOADER_ARCH_CFLAGS -mregparm=3\n\n    #define EXEC_PIC_ADDRESS   0x0f000000\n    #define INTERP_PIC_ADDRESS 0xaf000000\n\n#elif defined(ARCH_SH4)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-sh4.h\"\n    #define SYSNUMS_ABI1    sysnums_sh4\n\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS { }\n\n    #define user_regs_struct pt_regs\n    #define HOST_ELF_MACHINE {42, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define NO_MISALIGNED_ACCESS 1\n\n#elif defined(ARCH_RISCV)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-riscv64.h\"\n    #define SYSNUMS_ABI1    sysnums_riscv64\n\n    #define SYSTRAP_SIZE 4\n\n    #ifndef AUDIT_ARCH_RISCV64\n        #define AUDIT_ARCH_RISCV64 (243 | __AUDIT_ARCH_64BIT | __AUDIT_ARCH_LE)\n    #endif\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_RISCV64, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {243, 0}\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define NO_MISALIGNED_ACCESS 1\n\n    #define LOADER_ADDRESS     0x2000000000\n    #define EXEC_PIC_ADDRESS   0x3000000000\n    #define INTERP_PIC_ADDRESS 0x3f00000000\n\n#else\n\n    #error \"Unsupported architecture\"\n\n#endif', 'arch.h line 137 (i386 SYSNUMS_HEADER1) is inside the ARCH_X86 block; the #elif chain lacks an ARCH_RISCV case. Added ARCH_RISCV block: EM_RISCV=243, AUDIT_ARCH_RISCV64, ecall 4-byte, no red zone, no -mregparm (RISC-V uses standard calling convention), misaligned access unsafe.');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('4e8d72f0ba8efcfc5ae277161a5857a8', '0', NULL, '2026-07-27 10:18:01', NULL, '2026-07-27 10:18:01', NULL, 'c6ff6c035da9736ca86f235e989a8df6', 'source_code', 'c', 'x86', 'risc-v', '#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_X86) && !defined(ARCH_SH4)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif', '#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_ARM64) && !defined(ARCH_X86) && !defined(ARCH_SH4) && !defined(ARCH_RISCV)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    elif defined(__riscv)\n#        if __riscv_xlen == 64\n#            define ARCH_RISCV 1\n#        else\n#            error \"Only 64-bit RISC-V is supported\"\n#        endif\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif', 'arch.h line 50 (i386 detection) is in the auto-detection chain with no __riscv case. RISC-V falls through to #error. Added __riscv detection: __riscv_xlen==64 sets ARCH_RISCV; rv32 errors. Also added ARCH_ARM64 and ARCH_RISCV to the outer guard to prevent double-detection.');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('509dd4409a2ea60137a684c1bb4becae', '0', NULL, '2026-07-14 12:54:41', NULL, '2026-07-14 12:54:41', NULL, 'b841e87e115b14f59294b60baa81ac64', 'source_code', 'c', 'x86_64', 'risc-v', '#include \"../src/arch.h\"\n\n#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_X86) && !defined(ARCH_SH4)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif', '#include \"../src/arch.h\"\n\n#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_X86) && !defined(ARCH_SH4) && !defined(ARCH_ARM64) && !defined(ARCH_RISCV64) && !defined(ARCH_RISCV32)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    elif defined(__riscv)\n#        if __riscv_xlen == 64\n#            define ARCH_RISCV64 1\n#        elif __riscv_xlen == 32\n#            define ARCH_RISCV32 1\n#        else\n#            error \"Unsupported RISC-V XLEN\"\n#        endif\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif', 'Line 41 `#if defined(__x86_64__)` 是架构检测的第一个分支，仅 x86_64 编译时激活，不影响 RISC-V。但该文件复制了 arch.h 的检测逻辑，缺少 RISC-V 分支，RISC-V 编译触发 `#else` 的 `#error`。最佳实践：在 `#elif defined(__SH4__)` 后插入 `#elif defined(__riscv)`，依 __riscv_xlen 区分 RV64/RV32；同步在 `#if !defined(...)` 守卫中补充 ARCH_ARM64、ARCH_RISCV64、ARCH_RISCV32。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('52220a16e6783cc7b1baee6b16080f30', '0', NULL, '2026-07-27 10:10:40', NULL, '2026-07-27 10:10:40', NULL, 'c6ff6c035da9736ca86f235e989a8df6', 'source_code', 'c', 'x86_64', 'risc-v', '#    ifndef AT_REMOVEDIR\n#        define AT_REMOVEDIR		0x200', '#    ifndef AT_REMOVEDIR\n#        define AT_REMOVEDIR		0x200', 'AT_REMOVEDIR (0x200) is a generic Linux *at() flags constant from include/uapi/linux/fcntl.h, shared across all architectures including RISC-V. No compatibility issue exists; the value is architecture-independent and already correct for RISC-V.');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('53f0f42106aa11899f89e1ea7380343d', '0', NULL, '2026-07-27 10:19:22', NULL, '2026-07-27 10:19:22', NULL, 'c6ff6c035da9736ca86f235e989a8df6', 'source_code', 'c', 'arm64', 'risc-v', '/* According to the ARM64 EABI, all registers have undefined values at\n * program startup except:\n *\n * - the instruction pointer (pc)\n * - the stack pointer (sp)\n * - the rtld_fini pointer (x0)\n */\n#define BRANCH(stack_pointer, destination) do {			\\\n	asm volatile (						\\\n		\"// Restore initial stack pointer.	\\n\\t\"	\\\n		\"mov sp, %0				\\n\\t\"	\\\n		\"					\\n\\t\"	\\\n		\"// Clear rtld_fini.			\\n\\t\"	\\\n		\"mov x0, #0				\\n\\t\"	\\\n		\"					\\n\\t\"	\\\n		\"// Start the program.			\\n\\t\"	\\\n		\"br %1				\\n\"		\\\n		: /* no output */				\\\n		: \"r\" (stack_pointer), \"r\" (destination)	\\\n		: \"memory\", \"sp\", \"x0\");			\\\n	__builtin_unreachable();				\\\n	} while (0)\n\n#define PREPARE_ARGS_1(arg1_)				\\\n	register word_t arg1 asm(\"x0\") = arg1_;		\\\n\n#define PREPARE_ARGS_3(arg1_, arg2_, arg3_)		\\\n	PREPARE_ARGS_1(arg1_)				\\\n	register word_t arg2 asm(\"x1\") = arg2_;		\\\n	register word_t arg3 asm(\"x2\") = arg3_;		\\\n\n#define PREPARE_ARGS_4(arg1_, arg2_, arg3_, arg4_)	\\\n	PREPARE_ARGS_3(arg1_, arg2_, arg3_)		\\\n	register word_t arg4 asm(\"x3\") = arg4_;		\\\n\n#define PREPARE_ARGS_6(arg1_, arg2_, arg3_, arg4_, arg5_, arg6_)	\\\n	PREPARE_ARGS_4(arg1_, arg2_, arg3_, arg4_)			\\\n	register word_t arg5 asm(\"x4\") = arg5_;				\\\n	register word_t arg6 asm(\"x5\") = arg6_;\n\n#define OUTPUT_CONTRAINTS_1			\\\n	\"r\" (arg1)\n\n#define OUTPUT_CONTRAINTS_3			\\\n	OUTPUT_CONTRAINTS_1,			\\\n	\"r\" (arg2), \"r\" (arg3)\n\n#define OUTPUT_CONTRAINTS_4			\\\n	OUTPUT_CONTRAINTS_3,			\\\n	\"r\" (arg4)\n\n#define OUTPUT_CONTRAINTS_6				\\\n	OUTPUT_CONTRAINTS_4,				\\\n	\"r\" (arg5), \"r\" (arg6)\n\n#define SYSCALL(number_, nb_args, args...)				\\\n	({								\\\n		register word_t number asm(\"x8\") = number_;		\\\n		register word_t result asm(\"x0\");			\\\n		PREPARE_ARGS_##nb_args(args)				\\\n			asm volatile (					\\\n				\"svc #0x00000000		\\n\\t\"	\\\n				: \"=r\" (result)				\\\n				: \"r\" (number),				\\\n				OUTPUT_CONTRAINTS_##nb_args		\\\n				: \"memory\");				\\\n			result;						\\\n	})\n\n#define OPENAT	56\n#define CLOSE	57\n#define MMAP	222\n#define EXECVE	221\n#define EXIT	93\n#define PRCTL   167\n#define MPROTECT 226', '/* According to the RISC-V ELF psABI, all registers have undefined values\n * at program startup except:\n *\n * - the program counter (pc)\n * - the stack pointer (sp)\n * - the __rtld_fini pointer (a0 aka x10)\n */\n#define BRANCH(stack_pointer, destination) do {			\\\n	asm volatile (						\\\n		\"// Restore initial stack pointer.	\\n\\t\"	\\\n		\"mv sp, %0				\\n\\t\"	\\\n		\"					\\n\\t\"	\\\n		\"// Clear rtld_fini (a0).		\\n\\t\"	\\\n		\"li a0, 0				\\n\\t\"	\\\n		\"					\\n\\t\"	\\\n		\"// Start the program.			\\n\\t\"	\\\n		\"jr %1				\\n\"		\\\n		: /* no output */				\\\n		: \"r\" (stack_pointer), \"r\" (destination)	\\\n		: \"memory\", \"sp\", \"a0\");			\\\n	__builtin_unreachable();				\\\n	} while (0)\n\n#define PREPARE_ARGS_1(arg1_)				\\\n	register word_t arg1 asm(\"a0\") = arg1_;		\\\n\n#define PREPARE_ARGS_3(arg1_, arg2_, arg3_)		\\\n	PREPARE_ARGS_1(arg1_)				\\\n	register word_t arg2 asm(\"a1\") = arg2_;		\\\n	register word_t arg3 asm(\"a2\") = arg3_;		\\\n\n#define PREPARE_ARGS_4(arg1_, arg2_, arg3_, arg4_)	\\\n	PREPARE_ARGS_3(arg1_, arg2_, arg3_)		\\\n	register word_t arg4 asm(\"a3\") = arg4_;		\\\n\n#define PREPARE_ARGS_6(arg1_, arg2_, arg3_, arg4_, arg5_, arg6_)	\\\n	PREPARE_ARGS_4(arg1_, arg2_, arg3_, arg4_)			\\\n	register word_t arg5 asm(\"a4\") = arg5_;				\\\n	register word_t arg6 asm(\"a5\") = arg6_;\n\n#define OUTPUT_CONTRAINTS_1			\\\n	\"r\" (arg1)\n\n#define OUTPUT_CONTRAINTS_3			\\\n	OUTPUT_CONTRAINTS_1,			\\\n	\"r\" (arg2), \"r\" (arg3)\n\n#define OUTPUT_CONTRAINTS_4			\\\n	OUTPUT_CONTRAINTS_3,			\\\n	\"r\" (arg4)\n\n#define OUTPUT_CONTRAINTS_6				\\\n	OUTPUT_CONTRAINTS_4,				\\\n	\"r\" (arg5), \"r\" (arg6)\n\n#define SYSCALL(number_, nb_args, args...)				\\\n	({								\\\n		register word_t number asm(\"a7\") = number_;		\\\n		register word_t result asm(\"a0\");			\\\n		PREPARE_ARGS_##nb_args(args)				\\\n			asm volatile (					\\\n				\"ecall				\\n\\t\"	\\\n				: \"=r\" (result)				\\\n				: \"r\" (number),				\\\n				OUTPUT_CONTRAINTS_##nb_args		\\\n				: \"memory\");				\\\n			result;						\\\n	})\n\n#define OPENAT	56\n#define CLOSE	57\n#define MMAP	222\n#define EXECVE	221\n#define EXIT	93\n#define PRCTL   167\n#define MPROTECT 226', 'assembly-arm64.h line 95 defines EXECVE=221, which matches RISC-V\'s syscall number. However, all inline asm uses ARM64 instructions (svc, br, mov sp/x0) and registers (x0-x8). Created assembly-riscv64.h: ecall instead of svc, jr instead of br, mv/li instead of mov, RISC-V ABI registers (a0-a7/sp), and a7 for syscall number. Syscall numbers are identical between arm64 and riscv64.');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('5457a61025a04f994370e089202f28e1', '0', NULL, '2026-07-14 11:03:30', NULL, '2026-07-14 11:03:30', NULL, '8ecbc53f72b96e01428af3521a4737c1', 'source_code', 'c', 'x86_64/arm64', 'risc-v', '#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_X86) && !defined(ARCH_SH4)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif', '#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_X86) && !defined(ARCH_SH4) && !defined(ARCH_ARM64) && !defined(ARCH_RISCV64) && !defined(ARCH_RISCV32)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    elif defined(__riscv)\n#        if __riscv_xlen == 64\n#            define ARCH_RISCV64 1\n#        elif __riscv_xlen == 32\n#            define ARCH_RISCV32 1\n#        else\n#            error \"Unsupported RISC-V XLEN\"\n#        endif\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif', 'Line 53 `#define ARCH_SH4 1` 本身位于 `#elif defined(__SH4__)` 保护内，不会影响 RISC-V 编译，但周围架构检测逻辑缺少 RISC-V 分支。RISC-V 上 `__riscv` 预定义且 `__riscv_xlen` 为 64 或 32，会落入 `#else` 触发 `#error`。最佳实践：在 `#elif defined(__SH4__)` 后插入 `#elif defined(__riscv)` 分支，根据 `__riscv_xlen` 区分 RV64/RV32，同时在 `#if !defined(...)` 守卫中补充 `ARCH_RISCV64` 和 `ARCH_RISCV32` 以防止重复定义。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('54e63d8f32299ff1e7c4367c76af2f62', '0', NULL, '2026-07-27 10:19:42', NULL, '2026-07-27 10:19:42', NULL, 'c6ff6c035da9736ca86f235e989a8df6', 'source_code', 'c', 'arm64', 'risc-v', '/* According to the ARM64 EABI, all registers have undefined values at\n * program startup except:\n *\n * - the instruction pointer (pc)\n * - the stack pointer (sp)\n * - the rtld_fini pointer (x0)\n */\n#define BRANCH(stack_pointer, destination) do {			\\\n	asm volatile (						\\\n		\"// Restore initial stack pointer.	\\n\\t\"	\\\n		\"mov sp, %0				\\n\\t\"	\\\n		\"					\\n\\t\"	\\\n		\"// Clear rtld_fini.			\\n\\t\"	\\\n		\"mov x0, #0				\\n\\t\"	\\\n		\"					\\n\\t\"	\\\n		\"// Start the program.			\\n\\t\"	\\\n		\"br %1				\\n\"		\\\n		: /* no output */				\\\n		: \"r\" (stack_pointer), \"r\" (destination)	\\\n		: \"memory\", \"sp\", \"x0\");			\\\n	__builtin_unreachable();				\\\n	} while (0)', '/* According to the RISC-V ELF psABI, all registers have undefined values\n * at program startup except:\n *\n * - the program counter (pc)\n * - the stack pointer (sp)\n * - the __rtld_fini pointer (a0)\n */\n#define BRANCH(stack_pointer, destination) do {			\\\n	asm volatile (						\\\n		\"// Restore initial stack pointer.	\\n\\t\"	\\\n		\"mv sp, %0				\\n\\t\"	\\\n		\"					\\n\\t\"	\\\n		\"// Clear rtld_fini (a0).		\\n\\t\"	\\\n		\"li a0, 0				\\n\\t\"	\\\n		\"					\\n\\t\"	\\\n		\"// Start the program.			\\n\\t\"	\\\n		\"jr %1				\\n\"		\\\n		: /* no output */				\\\n		: \"r\" (stack_pointer), \"r\" (destination)	\\\n		: \"memory\", \"sp\", \"a0\");			\\\n	__builtin_unreachable();				\\\n	} while (0)', 'BRANCH macro uses ARM64-specific instructions: mov sp,mov x0,br. RISC-V equivalent: mv sp (restore stack), li a0 (clear rtld_fini per psABI), jr (jump register). RISC-V passes rtld_fini in a0 (x10) not x0. Clobbers updated to sp,a0. srcChip assumed arm64 based on filename assembly-arm64.h.');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('558cfa30edd63f49f74da4ad7f447077', '0', NULL, '2026-07-14 13:00:10', NULL, '2026-07-14 13:00:10', NULL, '13b718da57b6d7b58d3afb1c9e3fd4a2', 'source_code', 'c', 'x86_64/arm64', 'risc-v', '#ifndef NO_LIBC_HEADER\n#include <sys/ptrace.h>    /* linux.git:c0a3a20b  */\n#include <linux/audit.h>   /* AUDIT_ARCH_*,  */\n#endif', '#ifndef NO_LIBC_HEADER\n#include <sys/ptrace.h>    /* linux.git:c0a3a20b  */\n#include <linux/audit.h>   /* AUDIT_ARCH_*,  */\n#endif', 'Line 29 是 `#ifndef NO_LIBC_HEADER` 的 `#endif`，该条件编译块用于可选引入 <sys/ptrace.h> 和 <linux/audit.h> 两个 Linux 内核头文件。这两个头文件在 RISC-V Linux 上完全可用，该条件编译块与架构无关，RISC-V 上无需修改。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('57438a4e6ca373e91f7c5433242ae667', '0', NULL, '2026-07-14 11:03:50', NULL, '2026-07-14 11:03:50', NULL, '8ecbc53f72b96e01428af3521a4737c1', 'source_code', 'c', 'x86_64/arm64', 'risc-v', '#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_X86) && !defined(ARCH_SH4)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif\n\n/* Architecture specific definitions. */\n#if defined(ARCH_X86_64)\n...\n#elif defined(ARCH_ARM64)\n...\n#elif defined(ARCH_X86)\n...\n#elif defined(ARCH_SH4)\n...\n#else\n#    error \"Unsupported architecture\"\n#endif', '#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_X86) && !defined(ARCH_SH4) && !defined(ARCH_ARM64) && !defined(ARCH_RISCV64) && !defined(ARCH_RISCV32)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    elif defined(__riscv)\n#        if __riscv_xlen == 64\n#            define ARCH_RISCV64 1\n#        elif __riscv_xlen == 32\n#            define ARCH_RISCV32 1\n#        else\n#            error \"Unsupported RISC-V XLEN\"\n#        endif\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif\n\n/* Architecture specific definitions. */\n#if defined(ARCH_X86_64)\n...\n#elif defined(ARCH_ARM64)\n...\n#elif defined(ARCH_RISCV64)\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-riscv64.h\"\n    #define SYSNUMS_ABI1    sysnums_riscv64\n    #define SYSTRAP_SIZE 4\n    #ifndef AUDIT_ARCH_RISCV64\n        #define AUDIT_ARCH_RISCV64 (243 | __AUDIT_ARCH_64BIT | __AUDIT_ARCH_LE)\n    #endif\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_RISCV64, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n    #define HOST_ELF_MACHINE {243, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define LOADER_ADDRESS     0x4000000000\n    #define EXEC_PIC_ADDRESS   0x5000000000\n    #define INTERP_PIC_ADDRESS 0x5f00000000\n#elif defined(ARCH_RISCV32)\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-riscv32.h\"\n    #define SYSNUMS_ABI1    sysnums_riscv32\n    #define SYSTRAP_SIZE 4\n    #ifndef AUDIT_ARCH_RISCV32\n        #define AUDIT_ARCH_RISCV32 (243 | __AUDIT_ARCH_LE)\n    #endif\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_RISCV32, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n    #define HOST_ELF_MACHINE {243, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define NO_MISALIGNED_ACCESS 1\n    #define LOADER_ADDRESS     0x40000000\n    #define EXEC_PIC_ADDRESS   0x50000000\n    #define INTERP_PIC_ADDRESS 0x5f000000\n#elif defined(ARCH_X86)\n...\n#elif defined(ARCH_SH4)\n...\n#else\n#    error \"Unsupported architecture\"\n#endif', 'Line 51 `#define ARCH_X86 1` 位于 `#elif defined(__i386__)` 条件保护内，单行本身无 RISC-V 问题。但整个架构检测块缺少 RISC-V 分支，`__riscv` 预定义宏无法匹配，编译时落入 `#else` 的 `#error`。最佳实践：在 `#elif defined(__SH4__)` 后插入 `#elif defined(__riscv)`，根据 `__riscv_xlen` 设为 ARCH_RISCV64 或 ARCH_RISCV32；在 `#if !defined(...)` 守卫中补充新宏防止重复定义；在第二块条件编译中新增 ARCH_RISCV64/ARCH_RISCV32 小节，配置 ELF 机器号 243、seccomp 架构 AUDIT_ARCH_RISCV64、无 red zone、合适 loader 地址。RV32 额外启用 NO_MISALIGNED_ACCESS。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('579fb483d85ac593e9ae5ccd53fb5611', '0', NULL, '2026-07-14 11:06:01', NULL, '2026-07-14 11:06:01', NULL, '8ecbc53f72b96e01428af3521a4737c1', 'source_code', 'c', 'x86_32', 'risc-v', '/* According to the x86 ABI, all registers have undefined values at\n * program startup except:\n *\n * - the instruction pointer (rip)\n * - the stack pointer (rsp)\n * - the rtld_fini pointer (rdx)\n * - the system flags (eflags)\n */\n#define BRANCH(stack_pointer, destination) do {			\\\n	asm volatile (						\\\n		\"// Restore initial stack pointer.	\\n\\t\"	\\\n		\"movl %0, %%esp				\\n\\t\"	\\\n		\"                      			\\n\\t\"	\\\n		\"// Clear state flags.			\\n\\t\"	\\\n		\"pushl $0				\\n\\t\"	\\\n		\"popfl					\\n\\t\"	\\\n		\"                      			\\n\\t\"	\\\n		\"// Clear rtld_fini.			\\n\\t\"	\\\n		\"movl $0, %%edx				\\n\\t\"	\\\n		\"                      			\\n\\t\"	\\\n		\"// Start the program.			\\n\\t\"	\\\n		\"jmpl *%%eax				\\n\"	\\\n		: /* no output */				\\\n		: \"irm\" (stack_pointer), \"a\" (destination)	\\\n		: \"memory\", \"cc\", \"esp\", \"edx\");		\\\n	__builtin_unreachable();				\\\n	} while (0)', '/* According to the RISC-V ABI, all registers have undefined values\n * at program startup except:\n *\n * - the instruction pointer (pc)\n * - the stack pointer (sp)\n */\n#define BRANCH(stack_pointer, destination) do {			\\\n	asm volatile (						\\\n		\"// Restore initial stack pointer.	\\n\\t\"	\\\n		\"mv sp, %0				\\n\\t\"	\\\n		\"                      			\\n\\t\"	\\\n		\"// Start the program.			\\n\\t\"	\\\n		\"jalr zero, %1, 0			\\n\"	\\\n		: /* no output */				\\\n		: \"r\" (stack_pointer), \"r\" (destination)	\\\n		: \"memory\", \"sp\");				\\\n	__builtin_unreachable();				\\\n	} while (0)', 'BRANCH 宏使用 x86 内联汇编：movl/pushl/popfl/jmpl 指令及 esp/edx/eax 寄存器，RISC-V 完全不支持。RISC-V 无 EFLAGS 寄存器，无需 popfl；无专用 rtld_fini 寄存器，无需清零。适配：用 `mv sp, %0` 设置栈指针，`jalr zero, %1, 0` 间接跳转（zero 寄存器丢弃返回地址），约束使用通用寄存器 \"r\" 而非 x86 专用 \"a\"/\"irm\"，clobber 仅声明 \"memory\" 和 \"sp\"。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('59d3cf0d931c4c0b792377d4994bb50b', '0', NULL, '2026-07-14 12:50:30', NULL, '2026-07-14 12:50:30', NULL, 'b841e87e115b14f59294b60baa81ac64', 'source_code', 'c', 'x86_64/arm64', 'risc-v', '#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_X86) && !defined(ARCH_SH4)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif', '#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_X86) && !defined(ARCH_SH4) && !defined(ARCH_ARM64) && !defined(ARCH_RISCV64) && !defined(ARCH_RISCV32)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    elif defined(__riscv)\n#        if __riscv_xlen == 64\n#            define ARCH_RISCV64 1\n#        elif __riscv_xlen == 32\n#            define ARCH_RISCV32 1\n#        else\n#            error \"Unsupported RISC-V XLEN\"\n#        endif\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif', 'Line 49 `#error \"Only EABI is currently supported for ARM\"` 受 `#elif defined(__arm__)` 保护，仅 ARM 非 EABI 编译时触发，不影响 RISC-V。但架构检测块整体缺少 RISC-V 分支，`__riscv` 无法匹配，编译会落到 `#else` 的 `#error \"Unsupported architecture\"`。最佳实践：在 `#elif defined(__SH4__)` 后插入 `#elif defined(__riscv)` 分支，依 `__riscv_xlen` 定义为 ARCH_RISCV64 或 ARCH_RISCV32；同步在 `#if !defined(...)` 守卫中补充 `ARCH_ARM64`、`ARCH_RISCV64`、`ARCH_RISCV32`。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('5a646f4e448c8da0d437f1aa02c0c681', '0', NULL, '2026-07-27 10:15:01', NULL, '2026-07-27 10:15:01', NULL, 'c6ff6c035da9736ca86f235e989a8df6', 'source_code', 'c', 'arm64', 'risc-v', '#elif defined(ARCH_ARM64)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-arm64.h\"\n    #define SYSNUMS_ABI1    sysnums_arm64\n\n    #define SYSTRAP_SIZE 4\n\n    #ifndef AUDIT_ARCH_AARCH64\n        #define AUDIT_ARCH_AARCH64 (EM_AARCH64 | __AUDIT_ARCH_64BIT | __AUDIT_ARCH_LE)\n    #endif\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_AARCH64, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {183, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n\n    #define LOADER_ADDRESS     0x2000000000\n    #define EXEC_PIC_ADDRESS   0x3000000000\n    #define INTERP_PIC_ADDRESS 0x3f00000000\n\n#elif defined(ARCH_X86)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-i386.h\"\n    #define SYSNUMS_ABI1    sysnums_i386\n\n    #undef  SYSTRAP_NUM\n    #define SYSTRAP_NUM SYSARG_RESULT\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_I386, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {3, 6, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n\n    #define LOADER_ADDRESS 0xa0000000\n    #define LOADER_ARCH_CFLAGS -mregparm=3\n\n    #define EXEC_PIC_ADDRESS   0x0f000000\n    #define INTERP_PIC_ADDRESS 0xaf000000\n\n#elif defined(ARCH_SH4)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-sh4.h\"\n    #define SYSNUMS_ABI1    sysnums_sh4\n\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS { }\n\n    #define user_regs_struct pt_regs\n    #define HOST_ELF_MACHINE {42, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define NO_MISALIGNED_ACCESS 1\n\n#else\n\n    #error \"Unsupported architecture\"\n\n#endif', '#elif defined(ARCH_ARM64)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-arm64.h\"\n    #define SYSNUMS_ABI1    sysnums_arm64\n\n    #define SYSTRAP_SIZE 4\n\n    #ifndef AUDIT_ARCH_AARCH64\n        #define AUDIT_ARCH_AARCH64 (EM_AARCH64 | __AUDIT_ARCH_64BIT | __AUDIT_ARCH_LE)\n    #endif\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_AARCH64, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {183, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n\n    #define LOADER_ADDRESS     0x2000000000\n    #define EXEC_PIC_ADDRESS   0x3000000000\n    #define INTERP_PIC_ADDRESS 0x3f00000000\n\n#elif defined(ARCH_X86)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-i386.h\"\n    #define SYSNUMS_ABI1    sysnums_i386\n\n    #undef  SYSTRAP_NUM\n    #define SYSTRAP_NUM SYSARG_RESULT\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_I386, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {3, 6, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n\n    #define LOADER_ADDRESS 0xa0000000\n    #define LOADER_ARCH_CFLAGS -mregparm=3\n\n    #define EXEC_PIC_ADDRESS   0x0f000000\n    #define INTERP_PIC_ADDRESS 0xaf000000\n\n#elif defined(ARCH_SH4)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-sh4.h\"\n    #define SYSNUMS_ABI1    sysnums_sh4\n\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS { }\n\n    #define user_regs_struct pt_regs\n    #define HOST_ELF_MACHINE {42, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define NO_MISALIGNED_ACCESS 1\n\n#elif defined(ARCH_RISCV)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-riscv64.h\"\n    #define SYSNUMS_ABI1    sysnums_riscv64\n\n    #define SYSTRAP_SIZE 4\n\n    #ifndef AUDIT_ARCH_RISCV64\n        #define AUDIT_ARCH_RISCV64 (243 | __AUDIT_ARCH_64BIT | __AUDIT_ARCH_LE)\n    #endif\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_RISCV64, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {243, 0}\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define NO_MISALIGNED_ACCESS 1\n\n    #define LOADER_ADDRESS     0x2000000000\n    #define EXEC_PIC_ADDRESS   0x3000000000\n    #define INTERP_PIC_ADDRESS 0x3f00000000\n\n#else\n\n    #error \"Unsupported architecture\"\n\n#endif', 'arch.h line 116 (ARM64 SYSNUMS_ABI1) is in the ARCH_ARM64 block; the #elif chain has no ARCH_RISCV case. Added ARCH_RISCV block: EM_RISCV=243, AUDIT_ARCH_RISCV64, ecall 4-byte trap, no red zone, misaligned access unsafe. RISC-V closely mirrors ARM64 in structure (single 64-bit ABI, no compat mode).');
