n\n    #define LOADER_ADDRESS     0x2000000000\n    #define EXEC_PIC_ADDRESS   0x3000000000\n    #define INTERP_PIC_ADDRESS 0x3f00000000\n\n#elif defined(ARCH_X86)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-i386.h\"\n    #define SYSNUMS_ABI1    sysnums_i386\n\n    #undef  SYSTRAP_NUM\n    #define SYSTRAP_NUM SYSARG_RESULT\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_I386, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {3, 6, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n\n    #define LOADER_ADDRESS 0xa0000000\n    #define LOADER_ARCH_CFLAGS -mregparm=3\n\n    #define EXEC_PIC_ADDRESS   0x0f000000\n    #define INTERP_PIC_ADDRESS 0xaf000000\n\n#elif defined(ARCH_SH4)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-sh4.h\"\n    #define SYSNUMS_ABI1    sysnums_sh4\n\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS { }\n\n    #define user_regs_struct pt_regs\n    #define HOST_ELF_MACHINE {42, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define NO_MISALIGNED_ACCESS 1\n\n#elif defined(ARCH_RISCV)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-riscv64.h\"\n    #define SYSNUMS_ABI1    sysnums_riscv64\n\n    #define SYSTRAP_SIZE 4\n\n    #ifndef AUDIT_ARCH_RISCV64\n        #define AUDIT_ARCH_RISCV64 (243 | __AUDIT_ARCH_64BIT | __AUDIT_ARCH_LE)\n    #endif\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_RISCV64, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {243, 0}\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define NO_MISALIGNED_ACCESS 1\n\n    #define LOADER_ADDRESS     0x2000000000\n    #define EXEC_PIC_ADDRESS   0x3000000000\n    #define INTERP_PIC_ADDRESS 0x3f00000000\n\n#else\n\n    #error \"Unsupported architecture\"\n\n#endif', 'arch.h line 62 (SYSNUMS_HEADER2 for i386 compat) is inside the ARCH_X86_64 block; the #elif chain lacks any ARCH_RISCV case. Added ARCH_RISCV block: EM_RISCV=243, AUDIT_ARCH_RISCV64 defined as (243|__AUDIT_ARCH_64BIT|__AUDIT_ARCH_LE), ecall 4-byte trap, no red zone, no 32-bit compat mode, misaligned access unsafe.');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('67c12534f818a5861530511599065834', '0', NULL, '2026-07-09 13:46:22', NULL, '2026-07-09 13:46:22', NULL, 'c84a09afdce9a324b17d747c233f025b', 'source_code', 'c', 'x86_64', 'risc-v', '#include <sys/stat.h>     /* open(2), */\n#include <sys/types.h>    /* open(2), */\n#include <unistd.h>       /* write(3), close(3), */\n#include <windows.h>\n\n#include \"execve/auxv.h\"', '#include <sys/stat.h>     /* open(2), */\n#include <sys/types.h>    /* open(2), */\n#include <unistd.h>       /* write(3), close(3), */\n\n#include \"execve/auxv.h\"', '#include <windows.h> 是 Windows 专有头文件，在 Linux/RISC-V 上不存在，编译失败。该文件为 PRoot execve 模块的纯 Linux 源码，未使用任何 Windows API，直接删除即可。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('6cdd58b7189130173e2986f14af67379', '0', NULL, '2026-07-14 12:51:10', NULL, '2026-07-14 12:51:10', NULL, 'b841e87e115b14f59294b60baa81ac64', 'source_code', 'c', 'x86_64/arm64', 'risc-v', '#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_X86) && !defined(ARCH_SH4)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif', '#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_X86) && !defined(ARCH_SH4) && !defined(ARCH_ARM64) && !defined(ARCH_RISCV64) && !defined(ARCH_RISCV32)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    elif defined(__riscv)\n#        if __riscv_xlen == 64\n#            define ARCH_RISCV64 1\n#        elif __riscv_xlen == 32\n#            define ARCH_RISCV32 1\n#        else\n#            error \"Unsupported RISC-V XLEN\"\n#        endif\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif', 'Line 43 `#define ARCH_X86_64 1` 受 `#if defined(__x86_64__)` 保护，仅 x86_64 编译时激活，不影响 RISC-V。但架构检测块整体缺少 RISC-V 分支，`__riscv` 无匹配项，编译触发 `#else` 的 `#error`。最佳实践：在 `#elif defined(__SH4__)` 后插入 `#elif defined(__riscv)`，依 __riscv_xlen 区分 RV64/RV32；同步在 `#if !defined(...)` 守卫中补充 ARCH_ARM64、ARCH_RISCV64、ARCH_RISCV32。第二块条件编译需对应新增 RISC-V 架构段。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('6d03d636ed6a7bda3064212bfd6ed85f', '0', NULL, '2026-07-14 12:54:11', NULL, '2026-07-14 12:54:11', NULL, 'b841e87e115b14f59294b60baa81ac64', 'source_code', 'c', 'x86_64/arm64', 'risc-v', '#include \"../src/arch.h\"\n\n#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_X86) && !defined(ARCH_SH4)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif', '#include \"../src/arch.h\"\n\n#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_X86) && !defined(ARCH_SH4) && !defined(ARCH_ARM64) && !defined(ARCH_RISCV64) && !defined(ARCH_RISCV32)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    elif defined(__riscv)\n#        if __riscv_xlen == 64\n#            define ARCH_RISCV64 1\n#        elif __riscv_xlen == 32\n#            define ARCH_RISCV32 1\n#        else\n#            error \"Unsupported RISC-V XLEN\"\n#        endif\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif', 'Line 51 `#elif defined(__SH4__)` 是架构检测分支的倒数第二个条件，缺少 RISC-V 分支，`__riscv` 无匹配项，编译触发 `#else` 的 `#error`。该文件复制了 arch.h 的架构检测逻辑，问题相同。适配：在 `#elif defined(__SH4__)` 后插入 `#elif defined(__riscv)`，依 __riscv_xlen 区分 RV64/RV32；同步在 `#if !defined(...)` 守卫中补充新宏。后续 #elif/if defined 块也需对应新增 RISC-V 寄存器偏移表。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('72a2f7c578d92ddfce1c786343c5f0cd', '0', NULL, '2026-07-27 10:18:31', NULL, '2026-07-27 10:18:31', NULL, 'c6ff6c035da9736ca86f235e989a8df6', 'source_code', 'c', 'arm64', 'risc-v', '#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_X86) && !defined(ARCH_SH4)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif', '#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_ARM64) && !defined(ARCH_X86) && !defined(ARCH_SH4) && !defined(ARCH_RISCV)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    elif defined(__riscv)\n#        if __riscv_xlen == 64\n#            define ARCH_RISCV 1\n#        else\n#            error \"Only 64-bit RISC-V is supported\"\n#        endif\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif', 'arch.h line 46 (aarch64 detection branch) is in the auto-detection chain that lacks a __riscv case. RISC-V hits #error at line 55. Added __riscv detection: __riscv_xlen==64 sets ARCH_RISCV; rv32 errors. Also added ARCH_ARM64 and ARCH_RISCV to the outer guard at line 41 to prevent re-detection.');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('7ba29c87d5bc68f209d43b3188cea101', '0', NULL, '2026-07-14 12:51:40', NULL, '2026-07-14 12:51:40', NULL, 'b841e87e115b14f59294b60baa81ac64', 'source_code', 'c', 'x86_64/arm64', 'risc-v', '#include <errno.h>     /* errno(3), */\n\n#include \"cli/cli.h\"', '#include <errno.h>     /* errno(3), */\n\n#include \"cli/cli.h\"', 'Line 32 是 `#include <errno.h>` 和 `#include \"cli/cli.h\"` 之间的空行，用于分隔系统标准头文件与项目头文件。该文件为 CLI 选项处理逻辑，仅包含标准 C 库和项目头文件，无任何架构相关代码，RISC-V 上无需修改。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('7cdda8d28d77ba9db6bb208842de629b', '0', NULL, '2026-07-27 10:20:22', NULL, '2026-07-27 10:20:22', NULL, 'c6ff6c035da9736ca86f235e989a8df6', 'source_code', 'c', 'x86_64', 'risc-v', '#if defined(ARCH_X86_64)\n\n#define USER32_NB_REGS   17\n#define USER32_NB_FPREGS 27\n\nextern word_t convert_user_offset(word_t offset);\nextern void convert_user_regs_struct(bool reverse, uint64_t *user_regs64,\n				uint32_t user_regs32[USER32_NB_REGS]);\n\n#else\n\n#define USER32_NB_REGS   0\n#define USER32_NB_FPREGS 0\n\nstatic inline word_t convert_user_offset(word_t offset UNUSED)\n{\n	assert(0);\n}\n\nstatic inline void convert_user_regs_struct(bool reverse UNUSED,\n					uint64_t *user_regs64 UNUSED,\n					uint32_t user_regs32[USER32_NB_REGS] UNUSED)\n{\n	assert(0);\n}\n\n#endif', '#if defined(ARCH_X86_64)\n\n#define USER32_NB_REGS   17\n#define USER32_NB_FPREGS 27\n\nextern word_t convert_user_offset(word_t offset);\nextern void convert_user_regs_struct(bool reverse, uint64_t *user_regs64,\n				uint32_t user_regs32[USER32_NB_REGS]);\n\n#elif defined(ARCH_RISCV)\n\n#define USER32_NB_REGS   0\n#define USER32_NB_FPREGS 0\n\nstatic inline word_t convert_user_offset(word_t offset UNUSED)\n{\n	assert(0);\n}\n\nstatic inline void convert_user_regs_struct(bool reverse UNUSED,\n					uint64_t *user_regs64 UNUSED,\n					uint32_t user_regs32[USER32_NB_REGS] UNUSED)\n{\n	assert(0);\n}\n\n#else\n\n#define USER32_NB_REGS   0\n#define USER32_NB_FPREGS 0\n\nstatic inline word_t convert_user_offset(word_t offset UNUSED)\n{\n	assert(0);\n}\n\nstatic inline void convert_user_regs_struct(bool reverse UNUSED,\n					uint64_t *user_regs64 UNUSED,\n					uint32_t user_regs32[USER32_NB_REGS] UNUSED)\n{\n	assert(0);\n}\n\n#endif', 'user.h line 30 uses #if defined(ARCH_X86_64) with an #else fallback. RISC-V correctly falls into the #else stub (asserts on 32-bit compat calls). Added explicit #elif defined(ARCH_RISCV) for symmetry and clarity, with identical stub behavior since RISC-V rv64 has no 32-bit user_regs compat mode. No functional change needed.');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('7e906aef00776cf3ee821ab73909d1b7', '0', NULL, '2026-07-27 10:11:40', NULL, '2026-07-27 10:11:40', NULL, 'c6ff6c035da9736ca86f235e989a8df6', 'source_code', 'c', 'x86_64', 'risc-v', '#    ifndef PTRACE_EVENT_EXEC\n#        define PTRACE_EVENT_EXEC	4', '#    ifndef PTRACE_EVENT_EXEC\n#        define PTRACE_EVENT_EXEC	4', 'PTRACE_EVENT_EXEC (4) is a generic Linux ptrace event constant from kernel\'s include/uapi/linux/ptrace.h, shared across all architectures including RISC-V. The value is architecture-independent and already correct. No compatibility issue exists.');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('7f1c556405c29c9d07710d923fc5a582', '0', NULL, '2026-07-14 11:04:31', NULL, '2026-07-14 11:04:31', NULL, '8ecbc53f72b96e01428af3521a4737c1', 'source_code', 'c', 'x86_64/arm64', 'risc-v', '#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_X86) && !defined(ARCH_SH4)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif', '#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_X86) && !defined(ARCH_SH4) && !defined(ARCH_ARM64) && !defined(ARCH_RISCV64) && !defined(ARCH_RISCV32)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    elif defined(__riscv)\n#        if __riscv_xlen == 64\n#            define ARCH_RISCV64 1\n#        elif __riscv_xlen == 32\n#            define ARCH_RISCV32 1\n#        else\n#            error \"Unsupported RISC-V XLEN\"\n#        endif\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif', 'Line 45 `#define ARCH_ARM_EABI 1` 被 `#elif defined(__ARM_EABI__)` 保护，单行不影响 RISC-V。但架构检测块缺少 RISC-V 分支，`__riscv` 无匹配项，编译触发 `#error`。最佳实践：在 `#elif defined(__SH4__)` 后插入 `#elif defined(__riscv)`，依 `__riscv_xlen` 定义 ARCH_RISCV64 或 ARCH_RISCV32；`#if !defined(...)` 守卫中补充新宏防止重复定义。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('81e1f28546e8f8e1893cd3edda9a3bf5', '0', NULL, '2026-07-09 13:41:10', NULL, '2026-07-09 13:41:10', NULL, 'c84a09afdce9a324b17d747c233f025b', 'source_code', 'c', 'x86_64', 'risc-v', '#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_X86) && !defined(ARCH_SH4)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif', '#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_X86) && !defined(ARCH_SH4)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    elif defined(__riscv) && __riscv_xlen == 64\n#        define ARCH_RISCV64 1\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif', 'Line 49 (#error \'Only EABI...\') 是 ARM 专属编译错误，位于 __arm__ 分支下，RISC-V 编译时不会进入此分支，无兼容性问题。但上下文块中缺少 RISC-V 检测分支会导致 RISC-V 编译失败，已在 __SH4__ 后新增 __riscv && __riscv_xlen == 64 检测以正确识别 RISC-V 64 位架构。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('8252aae863a64e1cf3f000ee938d9a7a', '0', NULL, '2026-07-09 13:41:30', NULL, '2026-07-09 13:41:30', NULL, 'c84a09afdce9a324b17d747c233f025b', 'source_code', 'c', 'x86_64', 'risc-v', '#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    elif defined(__riscv) && __riscv_xlen == 64\n#        define ARCH_RISCV64 1', '#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    elif defined(__riscv) && __riscv_xlen == 64\n#        define ARCH_RISCV64 1', '该行为 x86 (i386) 架构定义分支，与 RISC-V 无关。RISC-V 编译时通过 __riscv && __riscv_xlen == 64 分支匹配，不会进入此路径，无需修改。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('840d126f6c8b33a1dbd6bfbe25d8ef35', '0', NULL, '2026-07-27 11:03:10', NULL, '2026-07-27 11:03:10', NULL, '01df88b254c9685e4e2e630c69542e86', 'source_code', 'c', 'x86_64', 'risc-v', 'static inline u64 read_cycle_counter(void) {\n#if defined(__x86_64__)\n    unsigned int lo, hi;\n    asm volatile(\"rdtsc\" : \"=a\"(lo), \"=d\"(hi));\n    return ((u64)hi << 32) | lo;\n#elif defined(__aarch64__)\n    u64 val;\n    asm volatile(\"mrs %0, cntvct_el0\" : \"=r\"(val));\n    return val;\n#else\n    return 0; // RISC-V: \\xe9\\x9c\\x80\\xe4\\xbd\\xbf\\xe7\\x94\\xa8 rdcycle\n#endif\n}', 'static inline u64 read_cycle_counter(void) {\n#if defined(__x86_64__)\n    unsigned int lo, hi;\n    asm volatile(\"rdtsc\" : \"=a\"(lo), \"=d\"(hi));\n    return ((u64)hi << 32) | lo;\n#elif defined(__aarch64__)\n    u64 val;\n    asm volatile(\"mrs %0, cntvct_el0\" : \"=r\"(val));\n    return val;\n#elif defined(__riscv)\n    u64 val;\n    asm volatile(\"rdcycle %0\" : \"=r\"(val));\n    return val;\n#else\n    return 0;\n#endif\n}', '第39-40行#else分支返回0（仅有TODO注释），read_cycle_counter()在RISC-V上无实际功能。适配方案：新增#elif defined(__riscv)分支，使用RISC-V rdcycle伪指令读取硬件周期计数器，语义上等价于x86的rdtsc和ARM64的cntvct_el0。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('84fd54cab758395181425ecac7b1df0a', '0', NULL, '2026-07-14 12:50:50', NULL, '2026-07-14 12:50:50', NULL, 'b841e87e115b14f59294b60baa81ac64', 'source_code', 'c', 'x86_64/arm64', 'risc-v', '#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_X86) && !defined(ARCH_SH4)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif', '#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_X86) && !defined(ARCH_SH4) && !defined(ARCH_ARM64) && !defined(ARCH_RISCV64) && !defined(ARCH_RISCV32)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    elif defined(__riscv)\n#        if __riscv_xlen == 64\n#            define ARCH_RISCV64 1\n#        elif __riscv_xlen == 32\n#            define ARCH_RISCV32 1\n#        else\n#            error \"Unsupported RISC-V XLEN\"\n#        endif\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif', 'Line 51 `#define ARCH_X86 1` 位于 `#elif defined(__i386__)` 保护内，仅 x86 32 位编译时激活，不影响 RISC-V。但架构检测块整体缺 RISC-V 分支，`__riscv` 无匹配项，编译触发 `#else` 的 `#error`。最佳实践：在 `#elif defined(__SH4__)` 后插入 `#elif defined(__riscv)`，依 __riscv_xlen 定义为 ARCH_RISCV64 或 ARCH_RISCV32；同步在 `#if !defined(...)` 守卫中补充新宏。第二块条件编译需对应新增 RISC-V 架构段。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('8864ac5b0d8c4fb4be8725dfdaac407b', '0', NULL, '2026-07-14 11:04:21', NULL, '2026-07-14 11:04:21', NULL, '8ecbc53f72b96e01428af3521a4737c1', 'source_code', 'c', 'x86_64/arm64', 'risc-v', '#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_X86) && !defined(ARCH_SH4)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif', '#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_X86) && !defined(ARCH_SH4) && !defined(ARCH_ARM64) && !defined(ARCH_RISCV64) && !defined(ARCH_RISCV32)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    elif defined(__riscv)\n#        if __riscv_xlen == 64\n#            define ARCH_RISCV64 1\n#        elif __riscv_xlen == 32\n#            define ARCH_RISCV32 1\n#        else\n#            error \"Unsupported RISC-V XLEN\"\n#        endif\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif', 'Line 47 `#define ARCH_ARM64 1` 被 `#elif defined(__aarch64__)` 保护，单行无 RISC-V 问题。但架构检测块整体缺少 RISC-V 分支，`__riscv` 无法匹配任何 `#elif`，编译时触发 `#else` 的 `#error`。最佳实践：在 `#elif defined(__SH4__)` 后插入 `#elif defined(__riscv)`，依 `__riscv_xlen` 定义 ARCH_RISCV64 或 ARCH_RISCV32；同步在 `#if !defined(...)` 守卫中补充 `ARCH_ARM64`、`ARCH_RISCV64`、`ARCH_RISCV32` 防止重复定义。第二块条件编译需对应新增 RISC-V 架构段。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('8d01c8c6a2807cd85881629e5df12310', '0', NULL, '2026-07-14 12:52:01', NULL, '2026-07-14 12:52:01', NULL, 'b841e87e115b14f59294b60baa81ac64', 'source_code', 'c', 'x86_64/arm64', 'risc-v', '#include <talloc.h>   /* talloc_*, */\n\n#include \"arch.h\"', '#include <talloc.h>   /* talloc_*, */\n\n#include \"arch.h\"', 'Line 32 是 `#include <talloc.h>` 与 `#include \"arch.h\"` 之间的空行，用于分隔系统头文件与项目头文件。该文件为数组操作逻辑，通过抽象接口（sizeof_word、peek_reg、poke_reg、read_data 等）访问架构相关内容，aoxp.c 本身不含架构相关代码，RISC-V 上无需修改。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('9333a1883edbc784bfcee87f3e6ce54f', '0', NULL, '2026-07-09 13:43:41', NULL, '2026-07-09 13:43:41', NULL, 'c84a09afdce9a324b17d747c233f025b', 'source_code', 'c', 'x86_64', 'risc-v', '/* According to the x86 ABI, all registers have undefined values at\n * program startup except:\n *\n * - the instruction pointer (rip)\n * - the stack pointer (rsp)\n * - the rtld_fini pointer (rdx)\n * - the system flags (eflags)\n */\n#define BRANCH(stack_pointer, destination) do {			\\\n	asm volatile (						\\\n		\"// Restore initial stack pointer.	\\n\\t\"	\\\n		\"movl %0, %%esp				\\n\\t\"	\\\n		\"                      			\\n\\t\"	\\\n		\"// Clear state flags.			\\n\\t\"	\\\n		\"pushl $0				\\n\\t\"	\\\n		\"popfl					\\n\\t\"	\\\n		\"                      			\\n\\t\"	\\\n		\"// Clear rtld_fini.			\\n\\t\"	\\\n		\"movl $0, %%edx				\\n\\t\"	\\\n		\"                      			\\n\\t\"	\\\n		\"// Start the program.			\\n\\t\"	\\\n		\"jmpl *%%eax				\\n\"	\\\n		: /* no output */				\\\n		: \"irm\" (stack_pointer), \"a\" (destination)	\\\n		: \"memory\", \"cc\", \"esp\", \"edx\");		\\\n	__builtin_unreachable();				\\\n	} while (0)', '/* According to the RISC-V ABI (LP64), all registers have undefined\n * values at program startup except:\n *\n * - the instruction pointer (pc)\n * - the stack pointer (sp)\n * - the rtld_fini pointer (a0)\n */\n#define BRANCH(stack_pointer, destination) do {			\\\n	asm volatile (						\\\n		\"// Restore initial stack pointer.	\\n\\t\"	\\\n		\"mv sp, %0				\\n\\t\"	\\\n		\"                      			\\n\\t\"	\\\n		\"// Clear rtld_fini.			\\n\\t\"	\\\n		\"mv a0, zero				\\n\\t\"	\\\n		\"                      			\\n\\t\"	\\\n		\"// Start the program.			\\n\\t\"	\\\n		\"jr %1					\\n\"	\\\n		: /* no output */				\\\n		: \"r\" (stack_pointer), \"r\" (destination)	\\\n		: \"memory\", \"sp\", \"a0\");			\\\n	__builtin_unreachable();				\\\n	} while (0)\n\n#define PREPARE_ARGS_1(arg1_)				\\\n	register word_t arg1 asm(\"a0\") = arg1_;\n\n#define PREPARE_ARGS_3(arg1_, arg2_, arg3_)		\\\n	PREPARE_ARGS_1(arg1_)				\\\n	register word_t arg2 asm(\"a1\") = arg2_;		\\\n	register word_t arg3 asm(\"a2\") = arg3_;\n\n#define PREPARE_ARGS_4(arg1_, arg2_, arg3_, arg4_)	\\\n	PREPARE_ARGS_3(arg1_, arg2_, arg3_)		\\\n	register word_t arg4 asm(\"a3\") = arg4_;\n\n#define PREPARE_ARGS_6(arg1_, arg2_, arg3_, arg4_, arg5_, arg6_)	\\\n	PREPARE_ARGS_4(arg1_, arg2_, arg3_, arg4_)			\\\n	register word_t arg5 asm(\"a4\") = arg5_;				\\\n	register word_t arg6 asm(\"a5\") = arg6_;\n\n#define OUTPUT_CONTRAINTS_1			\\\n	\"r\" (arg1)\n\n#define OUTPUT_CONTRAINTS_3			\\\n	OUTPUT_CONTRAINTS_1,			\\\n	\"r\" (arg2), \"r\" (arg3)\n\n#define OUTPUT_CONTRAINTS_4			\\\n	OUTPUT_CONTRAINTS_3,			\\\n	\"r\" (arg4)\n\n#define OUTPUT_CONTRAINTS_6				\\\n	OUTPUT_CONTRAINTS_4,				\\\n	\"r\" (arg5), \"r\" (arg6)\n\n#define SYSCALL(number_, nb_args, args...)				\\\n	({/								\\\n		register word_t number asm(\"a7\") = number_;		\\\n		register word_t result asm(\"a0\");			\\\n		PREPARE_ARGS_##nb_args(args)				\\\n			asm volatile (					\\\n				\"ecall				\\n\\t\"	\\\n				: \"=r\" (result)				\\\n				: \"r\" (number),				\\\n				OUTPUT_CONTRAINTS_##nb_args		\\\n				: \"memory\");				\\\n			result;						\\\n	})\n\n#define OPENAT	56\n#define CLOSE	57\n#define MMAP	222\n#define EXECVE	221\n#define EXIT	93\n#define PRCTL	167\n#define MPROTECT 226', 'assembly-x86.h 包含 x86 32位内联汇编（movl/pushfl/popfl/jmpl 及 esp/edx/eax 寄存器），无法在 RISC-V 上编译和执行。重写为 RISC-V RV64 内联汇编：BRANCH 使用 mv sp/jr 设置栈并跳转、mv a0,zero 清 rtld_fini；SYSCALL 使用 RISC-V 约定（a7=系统号、a0-a5=参数、ecall 指令）；系统调用号改为 RISC-V Linux 通用 ABI 值。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('95a21573f42cfde940bb9818bfae9cb3', '0', NULL, '2026-07-27 10:16:51', NULL, '2026-07-27 10:16:51', NULL, 'c6ff6c035da9736ca86f235e989a8df6', 'source_code', 'c', 'arm64', 'risc-v', '#elif defined(ARCH_ARM64)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-arm64.h\"\n    #define SYSNUMS_ABI1    sysnums_arm64\n\n    #define SYSTRAP_SIZE 4\n\n    #ifndef AUDIT_ARCH_AARCH64\n        #define AUDIT_ARCH_AARCH64 (EM_AARCH64 | __AUDIT_ARCH_64BIT | __AUDIT_ARCH_LE)\n    #endif\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_AARCH64, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {183, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n\n    #define LOADER_ADDRESS     0x2000000000\n    #define EXEC_PIC_ADDRESS   0x3000000000\n    #define INTERP_PIC_ADDRESS 0x3f00000000\n\n#elif defined(ARCH_X86)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-i386.h\"\n    #define SYSNUMS_ABI1    sysnums_i386\n\n    #undef  SYSTRAP_NUM\n    #define SYSTRAP_NUM SYSARG_RESULT\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_I386, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {3, 6, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n\n    #define LOADER_ADDRESS 0xa0000000\n    #define LOADER_ARCH_CFLAGS -mregparm=3\n\n    #define EXEC_PIC_ADDRESS   0x0f000000\n    #define INTERP_PIC_ADDRESS 0xaf000000\n\n#elif defined(ARCH_SH4)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-sh4.h\"\n    #define SYSNUMS_ABI1    sysnums_sh4\n\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS { }\n\n    #define user_regs_struct pt_regs\n    #define HOST_ELF_MACHINE {42, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define NO_MISALIGNED_ACCESS 1\n\n#else\n\n    #error \"Unsupported architecture\"\n\n#endif', '#elif defined(ARCH_ARM64)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-arm64.h\"\n    #define SYSNUMS_ABI1    sysnums_arm64\n\n    #define SYSTRAP_SIZE 4\n\n    #ifndef AUDIT_ARCH_AARCH64\n        #define AUDIT_ARCH_AARCH64 (EM_AARCH64 | __AUDIT_ARCH_64BIT | __AUDIT_ARCH_LE)\n    #endif\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_AARCH64, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {183, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n\n    #define LOADER_ADDRESS     0x2000000000\n    #define EXEC_PIC_ADDRESS   0x3000000000\n    #define INTERP_PIC_ADDRESS 0x3f00000000\n\n#elif defined(ARCH_X86)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-i386.h\"\n    #define SYSNUMS_ABI1    sysnums_i386\n\n    #undef  SYSTRAP_NUM\n    #define SYSTRAP_NUM SYSARG_RESULT\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_I386, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {3, 6, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n\n    #define LOADER_ADDRESS 0xa0000000\n    #define LOADER_ARCH_CFLAGS -mregparm=3\n\n    #define EXEC_PIC_ADDRESS   0x0f000000\n    #define INTERP_PIC_ADDRESS 0xaf000000\n\n#elif defined(ARCH_SH4)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-sh4.h\"\n    #define SYSNUMS_ABI1    sysnums_sh4\n\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS { }\n\n    #define user_regs_struct pt_regs\n    #define HOST_ELF_MACHINE {42, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define NO_MISALIGNED_ACCESS 1\n\n#elif defined(ARCH_RISCV)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-riscv64.h\"\n    #define SYSNUMS_ABI1    sysnums_riscv64\n\n    #define SYSTRAP_SIZE 4\n\n    #ifndef AUDIT_ARCH_RISCV64\n        #define AUDIT_ARCH_RISCV64 (243 | __AUDIT_ARCH_64BIT | __AUDIT_ARCH_LE)\n    #endif\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_RISCV64, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {243, 0}\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define NO_MISALIGNED_ACCESS 1\n\n    #define LOADER_ADDRESS     0x2000000000\n    #define EXEC_PIC_ADDRESS   0x3000000000\n    #define INTERP_PIC_ADDRESS 0x3f00000000\n\n#else\n\n    #error \"Unsupported architecture\"\n\n#endif', 'arch.h line 115 (ARM64 SYSNUMS_HEADER1) is inside the ARCH_ARM64 block; the #elif chain lacks any ARCH_RISCV case. Added ARCH_RISCV block: EM_RISCV=243, AUDIT_ARCH_RISCV64, ecall 4-byte trap, no red zone, single ABI (mirrors ARM64 structure), misaligned access unsafe. Also requires __riscv detection in auto-detection block.');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('9be064222e946e1cabd74e93de545b98', '0', NULL, '2026-07-09 13:40:50', NULL, '2026-07-09 13:40:50', NULL, 'c84a09afdce9a324b17d747c233f025b', 'source_code', 'c', 'x86_64', 'risc-v', '#ifndef NO_LIBC_HEADER\n#include <linux/audit.h> /* AUDIT_ARCH_*,  */\n#include <sys/ptrace.h>  /* linux.git:c0a3a20b  */\n#include <windows.h>\n#endif\n...\n#elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif', '#ifndef NO_LIBC_HEADER\n#include <linux/audit.h> /* AUDIT_ARCH_*,  */\n#include <sys/ptrace.h>  /* linux.git:c0a3a20b  */\n#endif\n...\n#elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    elif defined(__riscv) && __riscv_xlen == 64\n#        define ARCH_RISCV64 1\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif\n...\n#elif defined(ARCH_RISCV64)\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-riscv64.h\"\n    #define SYSNUMS_ABI1    sysnums_riscv64\n    #define SYSTRAP_SIZE 4\n    #ifndef EM_RISCV\n    #define EM_RISCV 243\n    #endif\n    #ifndef AUDIT_ARCH_RISCV64\n    #ifndef __AUDIT_ARCH_64BIT\n    #define __AUDIT_ARCH_64BIT 0x80000000\n    #endif\n    #ifndef __AUDIT_ARCH_LE\n    #define __AUDIT_ARCH_LE 0x40000000\n    #endif\n    #define AUDIT_ARCH_RISCV64 (EM_RISCV | __AUDIT_ARCH_64BIT | __AUDIT_ARCH_LE)\n    #endif\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_RISCV64, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n    #define user_regs_struct user_regs_struct\n    #define HOST_ELF_MACHINE {243, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define NO_MISALIGNED_ACCESS 0\n    #define LOADER_ADDRESS     0x2000000000\n    #define EXEC_PIC_ADDRESS   0x3000000000\n    #define INTERP_PIC_ADDRESS 0x3f00000000\n#endif', '问题1（行29）：#include <windows.h> 是 Windows 专有头文件，在 Linux/RISC-V 上不存在，编译直接失败，直接删除即可。问题2（行55）：架构检测缺少 RISC-V 分支，导致 #error \'Unsupported architecture\'。新增 ARCH_RISCV64 检测（__riscv && __riscv_xlen == 64）及完整架构配置块：定义 EM_RISCV=243、AUDIT_ARCH_RISCV64、seccomp/seccomp filter 支持、ELF 机器码 243、无 RED_ZONE、地址空间参照 ARM64 布局。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('9ccf233eace5fe2ba046b3e34d1d2593', '0', NULL, '2026-07-27 11:02:50', NULL, '2026-07-27 11:02:50', NULL, '01df88b254c9685e4e2e630c69542e86', 'source_code', 'c', 'arm64', 'risc-v', '#ifndef ARCH_H\n#define ARCH_H\n\n#if defined(__x86_64__)\n  #define CACHE_LINE_SIZE 64\n  #define mb()  asm volatile(\"mfence\" ::: \"memory\")\n  #define rmb() asm volatile(\"lfence\" ::: \"memory\")\n  #define wmb() asm volatile(\"sfence\" ::: \"memory\")\n#elif defined(__aarch64__)\n  #define CACHE_LINE_SIZE 64\n  #define mb()  asm volatile(\"dmb ish\" ::: \"memory\")\n  #define rmb() asm volatile(\"dmb ishld\" ::: \"memory\")\n  #define wmb() asm volatile(\"dmb ishst\" ::: \"memory\")\n#else\n  #define CACHE_LINE_SIZE 64\n  #define mb()  /* TODO: RISC-V fence */\n  #define rmb() /* TODO: RISC-V fence */\n  #define wmb() /* TODO: RISC-V fence */\n#endif\n\n#endif', '#ifndef ARCH_H\n#define ARCH_H\n\n#if defined(__x86_64__)\n  #define CACHE_LINE_SIZE 64\n  #define mb()  asm volatile(\"mfence\" ::: \"memory\")\n  #define rmb() asm volatile(\"lfence\" ::: \"memory\")\n  #define wmb() asm volatile(\"sfence\" ::: \"memory\")\n#elif defined(__aarch64__)\n  #define CACHE_LINE_SIZE 64\n  #define mb()  asm volatile(\"dmb ish\" ::: \"memory\")\n  #define rmb() asm volatile(\"dmb ishld\" ::: \"memory\")\n  #define wmb() asm volatile(\"dmb ishst\" ::: \"memory\")\n#elif defined(__riscv)\n  #define CACHE_LINE_SIZE 64\n  #define mb()  asm volatile(\"fence iorw, iorw\" ::: \"memory\")\n  #define rmb() asm volatile(\"fence ir, ir\" ::: \"memory\")\n  #define wmb() asm volatile(\"fence ow, ow\" ::: \"memory\")\n#else\n  #define CACHE_LINE_SIZE 64\n  #define mb()  /* TODO: RISC-V fence */\n  #define rmb() /* TODO: RISC-V fence */\n  #define wmb() /* TODO: RISC-V fence */\n#endif\n\n#endif', '第14-19行#else分支的rmb()为空实现（仅有TODO注释），RISC-V弱内存模型下缺少读屏障fence指令会导致读序错误。适配方案：新增#elif defined(__riscv)分支，rmb()实现为fence ir,ir，确保load和device-input操作按序完成，语义上等价于ARM64的dmb ishld和x86的lfence。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('9e7f48c6d6176457c4814f9e4dcb0bf5', '0', NULL, '2026-07-27 10:17:51', NULL, '2026-07-27 10:17:51', NULL, 'c6ff6c035da9736ca86f235e989a8df6', 'source_code', 'c', 'x86_64', 'risc-v', '#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_X86) && !defined(ARCH_SH4)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif', '#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_ARM64) && !defined(ARCH_X86) && !defined(ARCH_SH4) && !defined(ARCH_RISCV)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    elif defined(__riscv)\n#        if __riscv_xlen == 64\n#            define ARCH_RISCV 1\n#        else\n#            error \"Only 64-bit RISC-V is supported\"\n#        endif\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif', 'arch.h line 43 (ARCH_X86_64 detection) is in the auto-detection chain that lacks a __riscv case. Added __riscv detection: __riscv_xlen==64 sets ARCH_RISCV, rv32 errors out. Also added ARCH_ARM64 and ARCH_RISCV to the outer guard to prevent re-detection when pre-defined via -D.');
