0\n    #define INTERP_PIC_ADDRESS 0x1f000000\n\n#elif defined(ARCH_ARM64)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-arm64.h\"\n    #define SYSNUMS_ABI1    sysnums_arm64\n\n    #define SYSTRAP_SIZE 4\n\n    #ifndef AUDIT_ARCH_AARCH64\n        #define AUDIT_ARCH_AARCH64 (EM_AARCH64 | __AUDIT_ARCH_64BIT | __AUDIT_ARCH_LE)\n    #endif\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_AARCH64, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {183, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n\n    #define LOADER_ADDRESS     0x2000000000\n    #define EXEC_PIC_ADDRESS   0x3000000000\n    #define INTERP_PIC_ADDRESS 0x3f00000000\n\n#elif defined(ARCH_X86)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-i386.h\"\n    #define SYSNUMS_ABI1    sysnums_i386\n\n    #undef  SYSTRAP_NUM\n    #define SYSTRAP_NUM SYSARG_RESULT\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_I386, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {3, 6, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n\n    #define LOADER_ADDRESS 0xa0000000\n    #define LOADER_ARCH_CFLAGS -mregparm=3\n\n    #define EXEC_PIC_ADDRESS   0x0f000000\n    #define INTERP_PIC_ADDRESS 0xaf000000\n\n#elif defined(ARCH_SH4)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-sh4.h\"\n    #define SYSNUMS_ABI1    sysnums_sh4\n\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS { }\n\n    #define user_regs_struct pt_regs\n    #define HOST_ELF_MACHINE {42, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define NO_MISALIGNED_ACCESS 1\n\n#else\n\n    #error \"Unsupported architecture\"\n\n#endif', '#if defined(ARCH_X86_64)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-x86_64.h\"\n    #define SYSNUMS_HEADER2 \"syscall/sysnums-i386.h\"\n    #define SYSNUMS_HEADER3 \"syscall/sysnums-x32.h\"\n\n    #define SYSNUMS_ABI1 sysnums_x86_64\n    #define SYSNUMS_ABI2 sysnums_i386\n    #define SYSNUMS_ABI3 sysnums_x32\n\n    #undef  SYSTRAP_NUM\n    #define SYSTRAP_NUM SYSARG_RESULT\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS {									\\\n		{ .value = AUDIT_ARCH_X86_64, .nb_abis = 2, .abis = { ABI_DEFAULT, ABI_3 } },	\\\n		{ .value = AUDIT_ARCH_I386,   .nb_abis = 1, .abis = { ABI_2 } }, 		\\\n	}\n\n    #define HOST_ELF_MACHINE {62, 3, 6, 0}\n    #define RED_ZONE_SIZE 128\n    #define OFFSETOF_STAT_UID_32 24\n    #define OFFSETOF_STAT_GID_32 28\n\n    #define LOADER_ADDRESS 0x600000000000\n    #define HAS_LOADER_32BIT true\n\n    #define EXEC_PIC_ADDRESS   0x500000000000\n    #define INTERP_PIC_ADDRESS 0x6f0000000000\n    #define EXEC_PIC_ADDRESS_32   0x0f000000\n    #define INTERP_PIC_ADDRESS_32 0xaf000000\n\n#elif defined(ARCH_ARM_EABI)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-arm.h\"\n    #define SYSNUMS_ABI1    sysnums_arm\n\n    #define SYSTRAP_SIZE 4\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_ARM, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define user_regs_struct user_regs\n    #define HOST_ELF_MACHINE {40, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define EM_ARM 40\n\n    #define LOADER_ADDRESS 0x10000000\n\n    #define EXEC_PIC_ADDRESS   0x0f000000\n    #define INTERP_PIC_ADDRESS 0x1f000000\n\n#elif defined(ARCH_ARM64)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-arm64.h\"\n    #define SYSNUMS_ABI1    sysnums_arm64\n\n    #define SYSTRAP_SIZE 4\n\n    #ifndef AUDIT_ARCH_AARCH64\n        #define AUDIT_ARCH_AARCH64 (EM_AARCH64 | __AUDIT_ARCH_64BIT | __AUDIT_ARCH_LE)\n    #endif\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_AARCH64, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {183, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n\n    #define LOADER_ADDRESS     0x2000000000\n    #define EXEC_PIC_ADDRESS   0x3000000000\n    #define INTERP_PIC_ADDRESS 0x3f00000000\n\n#elif defined(ARCH_X86)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-i386.h\"\n    #define SYSNUMS_ABI1    sysnums_i386\n\n    #undef  SYSTRAP_NUM\n    #define SYSTRAP_NUM SYSARG_RESULT\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_I386, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {3, 6, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n\n    #define LOADER_ADDRESS 0xa0000000\n    #define LOADER_ARCH_CFLAGS -mregparm=3\n\n    #define EXEC_PIC_ADDRESS   0x0f000000\n    #define INTERP_PIC_ADDRESS 0xaf000000\n\n#elif defined(ARCH_SH4)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-sh4.h\"\n    #define SYSNUMS_ABI1    sysnums_sh4\n\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS { }\n\n    #define user_regs_struct pt_regs\n    #define HOST_ELF_MACHINE {42, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define NO_MISALIGNED_ACCESS 1\n\n#elif defined(ARCH_RISCV)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-riscv64.h\"\n    #define SYSNUMS_ABI1    sysnums_riscv64\n\n    #define SYSTRAP_SIZE 4\n\n    #ifndef AUDIT_ARCH_RISCV64\n        #define AUDIT_ARCH_RISCV64 (243 | __AUDIT_ARCH_64BIT | __AUDIT_ARCH_LE)\n    #endif\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_RISCV64, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {243, 0}\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define NO_MISALIGNED_ACCESS 1\n\n    #define LOADER_ADDRESS     0x2000000000\n    #define EXEC_PIC_ADDRESS   0x3000000000\n    #define INTERP_PIC_ADDRESS 0x3f00000000\n\n#else\n\n    #error \"Unsupported architecture\"\n\n#endif', 'arch.h line 63 (SYSNUMS_HEADER3 for x32) is inside the ARCH_X86_64 block. The #elif chain has no ARCH_RISCV case. Added ARCH_RISCV block: EM_RISCV=243, AUDIT_ARCH_RISCV64, ecall 4-byte trap, no red zone, no 32-bit multi-ABI support (single ABI), misaligned access unsafe.');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('a44451b5f450dbd8c981012305ea5989', '0', NULL, '2026-07-27 10:13:00', NULL, '2026-07-27 10:13:00', NULL, 'c6ff6c035da9736ca86f235e989a8df6', 'source_code', 'c', 'x86_64', 'risc-v', '#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_X86) && !defined(ARCH_SH4)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif', '#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_ARM64) && !defined(ARCH_X86) && !defined(ARCH_SH4) && !defined(ARCH_RISCV)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    elif defined(__riscv)\n#        if __riscv_xlen == 64\n#            define ARCH_RISCV 1\n#        else\n#            error \"Only 64-bit RISC-V is supported\"\n#        endif\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif', 'arch.h line 138 (ARCH_X86 block) is part of a chain of #elif blocks and auto-detection logic at line 41 that has no RISC-V case. Added __riscv detection: __riscv_xlen==64 triggers ARCH_RISCV; also added ARCH_RISCV and ARCH_ARM64 to the guard at line 41 to prevent re-detection. Without this, RISC-V falls through to #error.');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('a6ae9c76d04bac05f8709c5e335fdb50', '0', NULL, '2026-07-14 12:50:10', NULL, '2026-07-14 12:50:10', NULL, 'b841e87e115b14f59294b60baa81ac64', 'source_code', 'c', 'x86_64/arm64', 'risc-v', '#ifndef NO_LIBC_HEADER\n#include <sys/ptrace.h>    /* linux.git:c0a3a20b  */\n#include <linux/audit.h>   /* AUDIT_ARCH_*,  */\n#endif', '#ifndef NO_LIBC_HEADER\n#include <sys/ptrace.h>    /* linux.git:c0a3a20b  */\n#include <linux/audit.h>   /* AUDIT_ARCH_*,  */\n#endif', 'Line 29 是 `#ifndef NO_LIBC_HEADER` 的 `#endif` 闭合指令，用于可选引入 <sys/ptrace.h> 和 <linux/audit.h> 两个标准 Linux 内核头文件。这两个头文件在 RISC-V Linux 上完全可用，该条件编译块与架构无关，无需修改。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('ae64bef1e396ef145ef966d9b1a5e5a4', '0', NULL, '2026-07-14 12:50:40', NULL, '2026-07-14 12:50:40', NULL, 'b841e87e115b14f59294b60baa81ac64', 'source_code', 'c', 'x86_64/arm64', 'risc-v', '#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_X86) && !defined(ARCH_SH4)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif', '#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_X86) && !defined(ARCH_SH4) && !defined(ARCH_ARM64) && !defined(ARCH_RISCV64) && !defined(ARCH_RISCV32)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    elif defined(__riscv)\n#        if __riscv_xlen == 64\n#            define ARCH_RISCV64 1\n#        elif __riscv_xlen == 32\n#            define ARCH_RISCV32 1\n#        else\n#            error \"Unsupported RISC-V XLEN\"\n#        endif\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif', 'Line 53 `#define ARCH_SH4 1` 位于 `#elif defined(__SH4__)` 保护内，仅 SH4 编译时激活，不影响 RISC-V。但架构检测块整体缺少 RISC-V 分支，`__riscv` 无匹配项，编译触底到 `#else` 的 `#error`。最佳实践：在 `#elif defined(__SH4__)` 后插入 `#elif defined(__riscv)`，依 __riscv_xlen 区分 RV64/RV32；在 `#if !defined(...)` 守卫中补充 ARCH_RISCV64 和 ARCH_RISCV32 防重复定义。第二块条件编译需对应新增 RISC-V 架构段。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('af2b84378db699befcd31691187a517b', '0', NULL, '2026-07-14 12:53:51', NULL, '2026-07-14 12:53:51', NULL, 'b841e87e115b14f59294b60baa81ac64', 'source_code', 'c', 'x86_64', 'risc-v', '#include <stddef.h>        /* offsetof(3), */', '#include <stddef.h>        /* offsetof(3), */', 'Line 6 是 `#include <stddef.h>` 后的空行，本身无架构问题。但该文件整体是 seccomp BPF 过滤器编译测试，内部硬编码 `AUDIT_ARCH_X86_64` 和 `#define ARCH_NR AUDIT_ARCH_X86_64`，在 RISC-V 上无法通过编译。这是一个 autotools 风格的编译检查文件（隐藏文件 .check_seccomp_filter.c），应在 RISC-V 构建时使用对应的 `AUDIT_ARCH_RISCV64` 替换 x86_64 架构常量。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('b10b3859501275e1599aa6437a097769', '0', NULL, '2026-07-14 12:51:20', NULL, '2026-07-14 12:51:20', NULL, 'b841e87e115b14f59294b60baa81ac64', 'source_code', 'c', 'x86_64/arm64', 'risc-v', '#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_X86) && !defined(ARCH_SH4)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif', '#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_X86) && !defined(ARCH_SH4) && !defined(ARCH_ARM64) && !defined(ARCH_RISCV64) && !defined(ARCH_RISCV32)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    elif defined(__riscv)\n#        if __riscv_xlen == 64\n#            define ARCH_RISCV64 1\n#        elif __riscv_xlen == 32\n#            define ARCH_RISCV32 1\n#        else\n#            error \"Unsupported RISC-V XLEN\"\n#        endif\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif', 'Line 47 `#define ARCH_ARM64 1` 受 `#elif defined(__aarch64__)` 保护，仅 ARM64 编译时激活，不影响 RISC-V。但架构检测块整体缺少 RISC-V 分支，`__riscv` 无匹配项，编译触发 `#else` 的 `#error`。最佳实践：在 `#elif defined(__SH4__)` 后插入 `#elif defined(__riscv)`，依 __riscv_xlen 区分 RV64/RV32；同步在 `#if !defined(...)` 守卫中补充新宏。第二块条件编译需对应新增 RISC-V 架构段。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('b4c16b22124e0afc5ce61c0d8241d7bd', '0', NULL, '2026-07-09 13:44:31', NULL, '2026-07-09 13:44:31', NULL, 'c84a09afdce9a324b17d747c233f025b', 'source_code', 'c', 'x86_64', 'risc-v', '#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    elif defined(__riscv) && __riscv_xlen == 64\n#        define ARCH_RISCV64 1\n#    else\n#        error \"Unsupported architecture\"', '#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    elif defined(__riscv) && __riscv_xlen == 64\n#        define ARCH_RISCV64 1\n#    else\n#        error \"Unsupported architecture\"', '该行为 x86 (i386) 架构检测分支，与 RISC-V 无关。RISC-V 编译时通过 __riscv && __riscv_xlen == 64 分支匹配，不会进入此路径，无需修改。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('b6de172d7b3a57d368623692fdb0a1d1', '0', NULL, '2026-07-27 10:11:10', NULL, '2026-07-27 10:11:10', NULL, 'c6ff6c035da9736ca86f235e989a8df6', 'source_code', 'c', 'x86_64', 'risc-v', '#    ifndef PTRACE_EVENT_VFORK\n#        define PTRACE_EVENT_VFORK	2', '#    ifndef PTRACE_EVENT_VFORK\n#        define PTRACE_EVENT_VFORK	2', 'PTRACE_EVENT_VFORK (2) is a generic Linux ptrace event constant from kernel\'s include/uapi/linux/ptrace.h, shared across all architectures including RISC-V. The value is architecture-independent and already correct. No compatibility issue exists.');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('b82585cb647e3d50a7d6051a838f6e0e', '0', NULL, '2026-07-14 12:52:11', NULL, '2026-07-14 12:52:11', NULL, 'b841e87e115b14f59294b60baa81ac64', 'source_code', 'c', 'x86_64', 'risc-v', '/* According to the x86_64 ABI, all registers have undefined values at\n * program startup except:\n *\n * - the instruction pointer (rip)\n * - the stack pointer (rsp)\n * - the rtld_fini pointer (rdx)\n * - the system flags (rflags)\n */\n#define BRANCH(stack_pointer, destination) do {			\\\n	asm volatile (						\\\n		\"// Restore initial stack pointer.	\\n\\t\"	\\\n		\"movq %0, %%rsp				\\n\\t\"	\\\n		\"					\\n\\t\"	\\\n		\"// Clear state flags.			\\n\\t\"	\\\n		\"pushq $0				\\n\\t\"	\\\n		\"popfq					\\n\\t\"	\\\n		\"					\\n\\t\"	\\\n		\"// Clear rtld_fini.			\\n\\t\"	\\\n		\"movq $0, %%rdx				\\n\\t\"	\\\n		\"					\\n\\t\"	\\\n		\"// Start the program.			\\n\\t\"	\\\n		\"jmpq *%%rax				\\n\"	\\\n		: /* no output */				\\\n		: \"irm\" (stack_pointer), \"a\" (destination)	\\\n		: \"memory\", \"cc\", \"rsp\", \"rdx\");		\\\n	__builtin_unreachable();				\\\n	} while (0)', '/* According to the RISC-V ABI, all registers have undefined values\n * at program startup except:\n *\n * - the instruction pointer (pc)\n * - the stack pointer (sp)\n */\n#define BRANCH(stack_pointer, destination) do {			\\\n	asm volatile (						\\\n		\"// Restore initial stack pointer.	\\n\\t\"	\\\n		\"mv sp, %0				\\n\\t\"	\\\n		\"					\\n\\t\"	\\\n		\"// Start the program.			\\n\\t\"	\\\n		\"jalr zero, %1, 0			\\n\"	\\\n		: /* no output */				\\\n		: \"r\" (stack_pointer), \"r\" (destination)	\\\n		: \"memory\", \"sp\");				\\\n	__builtin_unreachable();				\\\n	} while (0)', 'BRANCH 宏含 x86_64 内联汇编（movq/pushq/popfq/jmpq 及 rsp/rdx/rax 寄存器），RISC-V 完全不兼容。RISC-V 无 rflags，无需 pushq $0/popfq；无 rtld_fini 专用寄存器，无需清零 rdx。适配：用 `mv sp, %0` 设栈指针，`jalr zero, %1, 0` 间接跳转（zero 丢弃 ra），约束改用通用 \"r\"，clobber 仅 \"memory\" 和 \"sp\"，删除 \"cc\" 和 \"rdx\"。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('b915a0b025bb72d39dae2b79be787ff2', '0', NULL, '2026-07-27 10:17:21', NULL, '2026-07-27 10:17:21', NULL, 'c6ff6c035da9736ca86f235e989a8df6', 'source_code', 'c', 'x86_64', 'risc-v', '#if defined(ARCH_X86_64)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-x86_64.h\"\n    #define SYSNUMS_HEADER2 \"syscall/sysnums-i386.h\"\n    #define SYSNUMS_HEADER3 \"syscall/sysnums-x32.h\"\n\n    #define SYSNUMS_ABI1 sysnums_x86_64\n    #define SYSNUMS_ABI2 sysnums_i386\n    #define SYSNUMS_ABI3 sysnums_x32\n\n    #undef  SYSTRAP_NUM\n    #define SYSTRAP_NUM SYSARG_RESULT\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS {									\\\n		{ .value = AUDIT_ARCH_X86_64, .nb_abis = 2, .abis = { ABI_DEFAULT, ABI_3 } },	\\\n		{ .value = AUDIT_ARCH_I386,   .nb_abis = 1, .abis = { ABI_2 } }, 		\\\n	}\n\n    #define HOST_ELF_MACHINE {62, 3, 6, 0}\n    #define RED_ZONE_SIZE 128\n    #define OFFSETOF_STAT_UID_32 24\n    #define OFFSETOF_STAT_GID_32 28\n\n    #define LOADER_ADDRESS 0x600000000000\n    #define HAS_LOADER_32BIT true\n\n    #define EXEC_PIC_ADDRESS   0x500000000000\n    #define INTERP_PIC_ADDRESS 0x6f0000000000\n    #define EXEC_PIC_ADDRESS_32   0x0f000000\n    #define INTERP_PIC_ADDRESS_32 0xaf000000\n\n#elif defined(ARCH_ARM_EABI)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-arm.h\"\n    #define SYSNUMS_ABI1    sysnums_arm\n\n    #define SYSTRAP_SIZE 4\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_ARM, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define user_regs_struct user_regs\n    #define HOST_ELF_MACHINE {40, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define EM_ARM 40\n\n    #define LOADER_ADDRESS 0x10000000\n\n    #define EXEC_PIC_ADDRESS   0x0f000000\n    #define INTERP_PIC_ADDRESS 0x1f000000\n\n#elif defined(ARCH_ARM64)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-arm64.h\"\n    #define SYSNUMS_ABI1    sysnums_arm64\n\n    #define SYSTRAP_SIZE 4\n\n    #ifndef AUDIT_ARCH_AARCH64\n        #define AUDIT_ARCH_AARCH64 (EM_AARCH64 | __AUDIT_ARCH_64BIT | __AUDIT_ARCH_LE)\n    #endif\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_AARCH64, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {183, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n\n    #define LOADER_ADDRESS     0x2000000000\n    #define EXEC_PIC_ADDRESS   0x3000000000\n    #define INTERP_PIC_ADDRESS 0x3f00000000\n\n#elif defined(ARCH_X86)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-i386.h\"\n    #define SYSNUMS_ABI1    sysnums_i386\n\n    #undef  SYSTRAP_NUM\n    #define SYSTRAP_NUM SYSARG_RESULT\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_I386, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {3, 6, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n\n    #define LOADER_ADDRESS 0xa0000000\n    #define LOADER_ARCH_CFLAGS -mregparm=3\n\n    #define EXEC_PIC_ADDRESS   0x0f000000\n    #define INTERP_PIC_ADDRESS 0xaf000000\n\n#elif defined(ARCH_SH4)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-sh4.h\"\n    #define SYSNUMS_ABI1    sysnums_sh4\n\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS { }\n\n    #define user_regs_struct pt_regs\n    #define HOST_ELF_MACHINE {42, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define NO_MISALIGNED_ACCESS 1\n\n#else\n\n    #error \"Unsupported architecture\"\n\n#endif', '#if defined(ARCH_X86_64)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-x86_64.h\"\n    #define SYSNUMS_HEADER2 \"syscall/sysnums-i386.h\"\n    #define SYSNUMS_HEADER3 \"syscall/sysnums-x32.h\"\n\n    #define SYSNUMS_ABI1 sysnums_x86_64\n    #define SYSNUMS_ABI2 sysnums_i386\n    #define SYSNUMS_ABI3 sysnums_x32\n\n    #undef  SYSTRAP_NUM\n    #define SYSTRAP_NUM SYSARG_RESULT\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS {									\\\n		{ .value = AUDIT_ARCH_X86_64, .nb_abis = 2, .abis = { ABI_DEFAULT, ABI_3 } },	\\\n		{ .value = AUDIT_ARCH_I386,   .nb_abis = 1, .abis = { ABI_2 } }, 		\\\n	}\n\n    #define HOST_ELF_MACHINE {62, 3, 6, 0}\n    #define RED_ZONE_SIZE 128\n    #define OFFSETOF_STAT_UID_32 24\n    #define OFFSETOF_STAT_GID_32 28\n\n    #define LOADER_ADDRESS 0x600000000000\n    #define HAS_LOADER_32BIT true\n\n    #define EXEC_PIC_ADDRESS   0x500000000000\n    #define INTERP_PIC_ADDRESS 0x6f0000000000\n    #define EXEC_PIC_ADDRESS_32   0x0f000000\n    #define INTERP_PIC_ADDRESS_32 0xaf000000\n\n#elif defined(ARCH_ARM_EABI)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-arm.h\"\n    #define SYSNUMS_ABI1    sysnums_arm\n\n    #define SYSTRAP_SIZE 4\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_ARM, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define user_regs_struct user_regs\n    #define HOST_ELF_MACHINE {40, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define EM_ARM 40\n\n    #define LOADER_ADDRESS 0x10000000\n\n    #define EXEC_PIC_ADDRESS   0x0f000000\n    #define INTERP_PIC_ADDRESS 0x1f000000\n\n#elif defined(ARCH_ARM64)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-arm64.h\"\n    #define SYSNUMS_ABI1    sysnums_arm64\n\n    #define SYSTRAP_SIZE 4\n\n    #ifndef AUDIT_ARCH_AARCH64\n        #define AUDIT_ARCH_AARCH64 (EM_AARCH64 | __AUDIT_ARCH_64BIT | __AUDIT_ARCH_LE)\n    #endif\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_AARCH64, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {183, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n\n    #define LOADER_ADDRESS     0x2000000000\n    #define EXEC_PIC_ADDRESS   0x3000000000\n    #define INTERP_PIC_ADDRESS 0x3f00000000\n\n#elif defined(ARCH_X86)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-i386.h\"\n    #define SYSNUMS_ABI1    sysnums_i386\n\n    #undef  SYSTRAP_NUM\n    #define SYSTRAP_NUM SYSARG_RESULT\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_I386, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {3, 6, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n\n    #define LOADER_ADDRESS 0xa0000000\n    #define LOADER_ARCH_CFLAGS -mregparm=3\n\n    #define EXEC_PIC_ADDRESS   0x0f000000\n    #define INTERP_PIC_ADDRESS 0xaf000000\n\n#elif defined(ARCH_SH4)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-sh4.h\"\n    #define SYSNUMS_ABI1    sysnums_sh4\n\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS { }\n\n    #define user_regs_struct pt_regs\n    #define HOST_ELF_MACHINE {42, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define NO_MISALIGNED_ACCESS 1\n\n#elif defined(ARCH_RISCV)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-riscv64.h\"\n    #define SYSNUMS_ABI1    sysnums_riscv64\n\n    #define SYSTRAP_SIZE 4\n\n    #ifndef AUDIT_ARCH_RISCV64\n        #define AUDIT_ARCH_RISCV64 (243 | __AUDIT_ARCH_64BIT | __AUDIT_ARCH_LE)\n    #endif\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_RISCV64, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {243, 0}\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define NO_MISALIGNED_ACCESS 1\n\n    #define LOADER_ADDRESS     0x2000000000\n    #define EXEC_PIC_ADDRESS   0x3000000000\n    #define INTERP_PIC_ADDRESS 0x3f00000000\n\n#else\n\n    #error \"Unsupported architecture\"\n\n#endif', 'arch.h line 67 (x86_64 SYSNUMS_ABI2 for i386 compat) is inside the ARCH_X86_64 multi-ABI block. The #elif chain has no ARCH_RISCV case. Added ARCH_RISCV block: RISC-V rv64 has a single ABI (no SYSNUMS_ABI2/3), EM_RISCV=243, AUDIT_ARCH_RISCV64, ecall 4-byte, no red zone, misaligned access unsafe.');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('bae876b69237176697a42b8ed0cf09f0', '0', NULL, '2026-07-09 13:44:51', NULL, '2026-07-09 13:44:51', NULL, 'c84a09afdce9a324b17d747c233f025b', 'source_code', 'c', 'x86_64', 'risc-v', '#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    elif defined(__riscv) && __riscv_xlen == 64\n#        define ARCH_RISCV64 1', '#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    elif defined(__riscv) && __riscv_xlen == 64\n#        define ARCH_RISCV64 1', '该行为 ARM64 (aarch64) 架构检测分支，与 RISC-V 无关。RISC-V 编译时通过 __riscv && __riscv_xlen == 64 分支匹配，不会进入此路径，无需修改。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('bc70a7cd9522bc86586ab032e5256a63', '0', NULL, '2026-07-09 13:45:32', NULL, '2026-07-09 13:45:32', NULL, 'c84a09afdce9a324b17d747c233f025b', 'source_code', 'c', 'arm64', 'risc-v', '#define BRANCH(stack_pointer, destination) do {			\\\n	asm volatile (						\\\n		\"// Restore initial stack pointer.	\\n\\t\"	\\\n		\"mov sp, %0				\\n\\t\"	\\\n		\"					\\n\\t\"	\\\n		\"// Clear rtld_fini.			\\n\\t\"	\\\n		\"mov x0, #0				\\n\\t\"	\\\n		\"					\\n\\t\"	\\\n		\"// Start the program.			\\n\\t\"	\\\n		\"br %1				\\n\"		\\\n		: /* no output */				\\\n		: \"r\" (stack_pointer), \"r\" (destination)	\\\n		: \"memory\", \"sp\", \"x0\");			\\\n	__builtin_unreachable();				\\\n	} while (0)', '#define BRANCH(stack_pointer, destination) do {			\\\n	asm volatile (						\\\n		\"// Restore initial stack pointer.	\\n\\t\"	\\\n		\"mv sp, %0				\\n\\t\"	\\\n		\"					\\n\\t\"	\\\n		\"// Clear rtld_fini.			\\n\\t\"	\\\n		\"mv a0, zero				\\n\\t\"	\\\n		\"					\\n\\t\"	\\\n		\"// Start the program.			\\n\\t\"	\\\n		\"jr %1					\\n\"	\\\n		: /* no output */				\\\n		: \"r\" (stack_pointer), \"r\" (destination)	\\\n		: \"memory\", \"sp\", \"a0\");			\\\n	__builtin_unreachable();				\\\n	} while (0)', '该文件为 ARM64 专用内联汇编，不直接影响 RISC-V，但 RISC-V 移植需创建等价的 assembly-riscv64.h。ARM64 的 mov sp/br 对应 RISC-V 的 mv sp/jr；rtld_fini 寄存器从 ARM64 的 x0 改为 RISC-V 的 a0；RISC-V 无 EFLAGS，无需清标志位操作。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('bcde0b9731cedc6630d6ef9bb5f4c5e1', '0', NULL, '2026-07-27 10:20:02', NULL, '2026-07-27 10:20:02', NULL, 'c6ff6c035da9736ca86f235e989a8df6', 'source_code', 'c', 'x86_64', 'risc-v', '#define PORTMAP_SIZE 4096  /* must be a power of 2 */\n#define PORTMAP_DEFAULT_VALUE 0  /* default value that indicates an unused entry */\n#define PORTMAP_VERBOSITY 1', '#define PORTMAP_SIZE 4096  /* must be a power of 2 */\n#define PORTMAP_DEFAULT_VALUE 0  /* default value that indicates an unused entry */\n#define PORTMAP_VERBOSITY 1', 'portmap.h line 12 defines PORTMAP_VERBOSITY as a constant integer. The entire file uses only standard uint16_t types and plain C functions. No architecture-specific code, macros, assembly, or platform-dependent interfaces exist. Already fully portable for RISC-V.');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('be3a5d993a321b41a454fc2502bb5800', '0', NULL, '2026-07-27 11:01:40', NULL, '2026-07-27 11:01:40', NULL, '01df88b254c9685e4e2e630c69542e86', 'source_code', 'c', 'x86_64', 'risc-v', '#include <stdio.h>\n#include <stdlib.h>\n#include \"arch.h\"\n\n#ifdef __x86_64__\n  #define ARCH_NAME \"x86_64\"\n#elif defined(__aarch64__)\n  #define ARCH_NAME \"aarch64\"\n#else\n  #define ARCH_NAME \"unknown\"\n#endif\n\nint main(int argc, char **argv) {\n    printf(\"Hello from %s\\n\", ARCH_NAME);\n\n    return 0;\n}', '#include <stdio.h>\n#include <stdlib.h>\n#include \"arch.h\"\n\n#ifdef __x86_64__\n  #define ARCH_NAME \"x86_64\"\n#elif defined(__aarch64__)\n  #define ARCH_NAME \"aarch64\"\n#elif defined(__riscv)\n  #define ARCH_NAME \"riscv\"\n#else\n  #define ARCH_NAME \"unknown\"\n#endif\n\nint main(int argc, char **argv) {\n    printf(\"Hello from %s\\n\", ARCH_NAME);\n\n    return 0;\n}', '第8行 #elif defined(__aarch64__) 条件链缺少 __riscv 检测分支，导致 RISC-V 编译时 ARCH_NAME 被定义为 \"unknown\"。适配方案：在 #elif defined(__aarch64__) 之后新增 #elif defined(__riscv) 分支，将 ARCH_NAME 正确设为 \"riscv\"。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('be614ecc4370e7db5552ea8ef4f3c743', '0', NULL, '2026-07-14 11:06:21', NULL, '2026-07-14 11:06:21', NULL, '8ecbc53f72b96e01428af3521a4737c1', 'source_code', 'c', 'x86_64/arm64', 'risc-v', '#include <talloc.h>   /* talloc_*, */', '#include <talloc.h>   /* talloc_*, */', 'Line 32 是 `#include <talloc.h>` 之后的一个空行，用于分隔系统头文件与项目头文件。文件整体为数组操作逻辑（read/write/find/resize xpointer），使用 `arch.h`、`tracee/abi.h` 和 `tracee/mem.h` 等抽象接口（如 sizeof_word、peek_reg、poke_reg），这些接口已有架构无关封装，该文件本身不含架构相关代码。无需修改。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('c044a79d0e9a51c762eb91965be8fa07', '0', NULL, '2026-07-09 13:44:11', NULL, '2026-07-09 13:44:11', NULL, 'c84a09afdce9a324b17d747c233f025b', 'source_code', 'c', 'arm64', 'risc-v', '#include \"../src/arch.h\"\n\n#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_X86) && !defined(ARCH_SH4)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif\n...\n#elif defined(ARCH_ARM64)\n    #undef  USER_REGS_OFFSET\n    #define USER_REGS_OFFSET(reg_name) offsetof(struct user_regs_struct, reg_name)\n    static off_t reg_offset[] = {\n        [SYSARG_NUM]    = USER_REGS_OFFSET(regs[8]),\n        [SYSARG_1]      = USER_REGS_OFFSET(regs[0]),\n        [SYSARG_2]      = USER_REGS_OFFSET(regs[1]),\n        [SYSARG_3]      = USER_REGS_OFFSET(regs[2]),\n        [SYSARG_4]      = USER_REGS_OFFSET(regs[3]),\n        [SYSARG_5]      = USER_REGS_OFFSET(regs[4]),\n        [SYSARG_6]      = USER_REGS_OFFSET(regs[5]),\n        [SYSARG_RESULT] = USER_REGS_OFFSET(regs[0]),\n        [STACK_POINTER] = USER_REGS_OFFSET(sp),\n        [INSTR_POINTER] = USER_REGS_OFFSET(pc),\n    };\n#elif defined(ARCH_X86)\n    ...\n#else\n    #error \"Unsupported architecture\"\n#endif', '#include \"../src/arch.h\"\n\n#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_X86) && !defined(ARCH_SH4) && !defined(ARCH_RISCV64)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    elif defined(__riscv) && __riscv_xlen == 64\n#        define ARCH_RISCV64 1\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif\n...\n#elif defined(ARCH_ARM64)\n    #undef  USER_REGS_OFFSET\n    #define USER_REGS_OFFSET(reg_name) offsetof(struct user_regs_struct, reg_name)\n    static off_t reg_offset[] = {\n        [SYSARG_NUM]    = USER_REGS_OFFSET(regs[8]),\n        [SYSARG_1]      = USER_REGS_OFFSET(regs[0]),\n        [SYSARG_2]      = USER_REGS_OFFSET(regs[1]),\n        [SYSARG_3]      = USER_REGS_OFFSET(regs[2]),\n        [SYSARG_4]      = USER_REGS_OFFSET(regs[3]),\n        [SYSARG_5]      = USER_REGS_OFFSET(regs[4]),\n        [SYSARG_6]      = USER_REGS_OFFSET(regs[5]),\n        [SYSARG_RESULT] = USER_REGS_OFFSET(regs[0]),\n        [STACK_POINTER] = USER_REGS_OFFSET(sp),\n        [INSTR_POINTER] = USER_REGS_OFFSET(pc),\n    };\n#elif defined(ARCH_RISCV64)\n    #undef  USER_REGS_OFFSET\n    #define USER_REGS_OFFSET(reg_name) offsetof(struct user_regs_struct, reg_name)\n    static off_t reg_offset[] = {\n        [SYSARG_NUM]    = USER_REGS_OFFSET(a7),\n        [SYSARG_1]      = USER_REGS_OFFSET(a0),\n        [SYSARG_2]      = USER_REGS_OFFSET(a1),\n        [SYSARG_3]      = USER_REGS_OFFSET(a2),\n        [SYSARG_4]      = USER_REGS_OFFSET(a3),\n        [SYSARG_5]      = USER_REGS_OFFSET(a4),\n        [SYSARG_6]      = USER_REGS_OFFSET(a5),\n        [SYSARG_RESULT] = USER_REGS_OFFSET(a0),\n        [STACK_POINTER] = USER_REGS_OFFSET(sp),\n        [INSTR_POINTER] = USER_REGS_OFFSET(pc),\n    };\n#elif defined(ARCH_X86)\n    ...\n#else\n    #error \"Unsupported architecture\"\n#endif', '架构检测块（行40-56）和 reg_offset 定义块（行83-184）均缺少 RISC-V 支持。检测块新增 __riscv && __riscv_xlen == 64 分支；reg_offset 块新增 ARCH_RISCV64 分支：RISC-V syscall 使用 a7(x17) 传系统号、a0-a5(x10-x15) 传参数、sp(x2) 为栈指针、pc 为指令指针，与 ARM64 模式类似，使用 USER_REGS_OFFSET 通过 offsetof 获取寄存器偏移。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('c13113c1e50131a25f1aa3b4429165f1', '0', NULL, '2026-07-27 10:19:52', NULL, '2026-07-27 10:19:52', NULL, 'c6ff6c035da9736ca86f235e989a8df6', 'source_code', 'c', 'x86_64', 'risc-v', '#ifndef VERSION\n#define VERSION \"2.3.0\"\n#endif\n\n#define CARE_MAX_SIZE 1024\n\nstatic char const *default_concealed_paths[] = {\n	\"$HOME\",\n	\"/tmp\",\n	NULL,\n};', '#ifndef VERSION\n#define VERSION \"2.3.0\"\n#endif\n\n#define CARE_MAX_SIZE 1024\n\nstatic char const *default_concealed_paths[] = {\n	\"$HOME\",\n	\"/tmp\",\n	NULL,\n};', 'care.h line 9 defines a version string literal VERSION \"2.3.0\". This is entirely architecture-independent C code with no inline assembly, arch macros, register access, or platform-specific types. No RISC-V compatible issues exist; the code is already fully portable.');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('c205d5946c394a241dba19b3361d898a', '0', NULL, '2026-07-27 10:12:30', NULL, '2026-07-27 10:12:30', NULL, 'c6ff6c035da9736ca86f235e989a8df6', 'source_code', 'c', 'x86_64', 'risc-v', '#elif defined(ARCH_SH4)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-sh4.h\"\n    #define SYSNUMS_ABI1    sysnums_sh4\n\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS { }\n\n    #define user_regs_struct pt_regs\n    #define HOST_ELF_MACHINE {42, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define NO_MISALIGNED_ACCESS 1\n\n#else\n\n    #error \"Unsupported architecture\"\n\n#endif', '#elif defined(ARCH_SH4)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-sh4.h\"\n    #define SYSNUMS_ABI1    sysnums_sh4\n\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS { }\n\n    #define user_regs_struct pt_regs\n    #define HOST_ELF_MACHINE {42, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define NO_MISALIGNED_ACCESS 1\n\n#elif defined(ARCH_RISCV)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-riscv64.h\"\n    #define SYSNUMS_ABI1    sysnums_riscv64\n\n    #define SYSTRAP_SIZE 4\n\n    #ifndef AUDIT_ARCH_RISCV64\n        #define AUDIT_ARCH_RISCV64 (243 | __AUDIT_ARCH_64BIT | __AUDIT_ARCH_LE)\n    #endif\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_RISCV64, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {243, 0}\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define NO_MISALIGNED_ACCESS 1\n\n    #define LOADER_ADDRESS     0x2000000000\n    #define EXEC_PIC_ADDRESS   0x3000000000\n    #define INTERP_PIC_ADDRESS 0x3f00000000\n\n#else\n\n    #error \"Unsupported architecture\"\n\n#endif', 'arch.h lacks any RISC-V architecture block. Line 160 (SYSNUMS_ABI1 for SH4) is in a series of arch-specific #elif blocks — without an ARCH_RISCV case, RISC-V falls through to #error. Added ARCH_RISCV block with EM_RISCV=243, AUDIT_ARCH_RISCV64, and riscv64 syscall header. ecall is 4 bytes (SYSTRAP_SIZE=4), no red zone, and misaligned access is unsupported.');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('c27d79a3883ab093965d32da7096a07f', '0', NULL, '2026-07-14 12:59:52', NULL, '2026-07-14 12:59:52', NULL, 'b841e87e115b14f59294b60baa81ac64', 'source_code', 'c', 'arm64', 'risc-v', '/* According to the ARM64 EABI, all registers have undefined values at\n * program startup except:\n *\n * - the instruction pointer (pc)\n * - the stack pointer (sp)\n * - the rtld_fini pointer (x0)\n */\n#define BRANCH(stack_pointer, destination) do {			\\\n	asm volatile (						\\\n		\"// Restore initial stack pointer.	\\n\\t\"	\\\n		\"mov sp, %0				\\n\\t\"	\\\n		\"					\\n\\t\"	\\\n		\"// Clear rtld_fini.			\\n\\t\"	\\\n		\"mov x0, #0				\\n\\t\"	\\\n		\"					\\n\\t\"	\\\n		\"// Start the program.			\\n\\t\"	\\\n		\"br %1				\\n\"	\\\n		: /* no output */				\\\n		: \"r\" (stack_pointer), \"r\" (destination)	\\\n		: \"memory\", \"sp\", \"x0\");			\\\n	__builtin_unreachable();				\\\n	} while (0)', '/* According to the RISC-V ABI, all registers have undefined values\n * at program startup except:\n *\n * - the instruction pointer (pc)\n * - the stack pointer (sp)\n */\n#define BRANCH(stack_pointer, destination) do {			\\\n	asm volatile (						\\\n		\"// Restore initial stack pointer.	\\n\\t\"	\\\n		\"mv sp, %0				\\n\\t\"	\\\n		\"					\\n\\t\"	\\\n		\"// Start the program.			\\n\\t\"	\\\n		\"jr %1					\\n\"	\\\n		: /* no output */				\\\n		: \"r\" (stack_pointer), \"r\" (destination)	\\\n		: \"memory\", \"sp\");				\\\n	__builtin_unreachable();				\\\n	} while (0)', 'BRANCH 宏使用 ARM64 汇编：mov sp/mov x0/br 指令。RISC-V 无 ARM64 的 rtld_fini 专用寄存器 x0，无需清零；无 `br` 指令。适配：用 `mv sp, %0` 设栈指针（与 ARM64 的 mov sp 等价），`jr %1`（jalr zero, %1, 0 的伪指令）替代 `br %1` 间接跳转，删除 rtld_fini 清零及 \"x0\" clobber。约束 \"r\" 与 clobber \"sp\" 与 ARM64 一致无需改动。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('c9cabc5b82aaab58ffc93dac6dfb90a1', '0', NULL, '2026-07-27 10:18:21', NULL, '2026-07-27 10:18:21', NULL, 'c6ff6c035da9736ca86f235e989a8df6', 'source_code', 'c', 'x86_64', 'risc-v', '#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_X86) && !defined(ARCH_SH4)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif', '#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_ARM64) && !defined(ARCH_X86) && !defined(ARCH_SH4) && !defined(ARCH_RISCV)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    elif defined(__riscv)\n#        if __riscv_xlen == 64\n#            define ARCH_RISCV 1\n#        else\n#            error \"Only 64-bit RISC-V is supported\"\n#        endif\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif', 'arch.h line 42 starts the x86_64 detection branch in the auto-detection chain. The chain lacks any __riscv case, causing RISC-V to hit #error. Added __riscv detection: __riscv_xlen==64 sets ARCH_RISCV; rv32 errors out. Also added ARCH_ARM64 and ARCH_RISCV to the guard at line 41.');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('caf57ec6456d4eb598918fe21bc389a9', '0', NULL, '2026-07-09 13:42:00', NULL, '2026-07-09 13:42:00', NULL, 'c84a09afdce9a324b17d747c233f025b', 'source_code', 'c', 'x86_64', 'risc-v', '#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    elif defined(__riscv) && __riscv_xlen == 64\n#        define ARCH_RISCV64 1', '#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    elif defined(__riscv) && __riscv_xlen == 64\n#        define ARCH_RISCV64 1', '该行为 ARM EABI 架构定义分支，与 RISC-V 无关。RISC-V 编译时通过 __riscv && __riscv_xlen == 64 分支匹配，不会进入此路径，无需修改。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('cb9a375ca2f768f21e65a7fac3219574', '0', NULL, '2026-07-14 11:05:21', NULL, '2026-07-14 11:05:21', NULL, '8ecbc53f72b96e01428af3521a4737c1', 'source_code', 'c', 'x86_64/arm64', 'risc-v', '#include <errno.h>     /* errno(3), */', '#include <errno.h>     /* errno(3), */', 'Line 32 是系统头文件 #include <errno.h> 之后的一个空行，代码完全由标准 C 库和项目头文件组成，不包含任何架构相关的宏、汇编、SIMD、寄存器访问、ptrace 或 syscall 调用。该文件整体是 CLI 选项处理逻辑，与 CPU 架构无关，在 RISC-V 上无需修改。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('cc8038cb1a4b74e30b7e77243dd14527', '0', NULL, '2026-07-14 12:54:51', NULL, '2026-07-14 12:54:51', NULL, 'b841e87e115b14f59294b60baa81ac64', 'source_code', 'c', 'arm64', 'risc-v', '#include \"../src/arch.h\"\n\n#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_X86) && !defined(ARCH_SH4)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif', '#include \"../src/arch.h\"\n\n#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_X86) && !defined(ARCH_SH4) && !defined(ARCH_ARM64) && !defined(ARCH_RISCV64) && !defined(ARCH_RISCV32)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    elif defined(__riscv)\n#        if __riscv_xlen == 64\n#            define ARCH_RISCV64 1\n#        elif __riscv_xlen == 32\n#            define ARCH_RISCV32 1\n#        else\n#            error \"Unsupported RISC-V XLEN\"\n#        endif\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif', 'Line 45 `#elif defined(__aarch64__)` 受 `#elif` 保护，仅 ARM64 编译时激活，不影响 RISC-V。但该文件复制了 arch.h 的架构检测逻辑，缺少 RISC-V 分支，RISC-V 编译触发 `#else` 的 `#error`。最佳实践：在 `#elif defined(__SH4__)` 后插入 `#elif defined(__riscv)`，依 __riscv_xlen 区分 RV64/RV32；同步在 `#if !defined(...)` 守卫中补充新宏。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('cf2bd2f00637c943fcec0c8d25305128', '0', NULL, '2026-07-14 11:01:40', NULL, '2026-07-14 11:01:40', NULL, '8ecbc53f72b96e01428af3521a4737c1', 'source_code', 'c', 'x86_64/arm64', 'risc-v', '#define SYSTRAP_NUM SYSARG_NUM\n#define STACK_ALIGNMENT 16\n\n#define OFFSETOF_STATX_UID 20\n#define OFFSETOF_STATX_GID 24\n\n#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_X86) && !defined(ARCH_SH4)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif\n\n#if defined(ARCH_X86_64)\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-x86_64.h\"\n    #define SYSNUMS_HEADER2 \"syscall/sysnums-i386.h\"\n    #define SYSNUMS_HEADER3 \"syscall/sysnums-x32.h\"\n    #define SYSNUMS_ABI1 sysnums_x86_64\n    #define SYSNUMS_ABI2 sysnums_i386\n    #define SYSNUMS_ABI3 sysnums_x32\n    #undef  SYSTRAP_NUM\n    #define SYSTRAP_NUM SYSARG_RESULT\n    #define SYSTRAP_SIZE 2\n    #define SECCOMP_ARCHS {{\\n		{ .value = AUDIT_ARCH_X86_64, .nb_abis = 2, .abis = { ABI_DEFAULT, ABI_3 } },\\\n		{ .value = AUDIT_ARCH_I386,   .nb_abis = 1, .abis = { ABI_2 } }, 		\\\n	}}\n    #define HOST_ELF_MACHINE {62, 3, 6, 0}\n    #define RED_ZONE_SIZE 128\n    #define OFFSETOF_STAT_UID_32 24\n    #define OFFSETOF_STAT_GID_32 28\n    #define LOADER_ADDRESS 0x600000000000\n    #define HAS_LOADER_32BIT true\n    #define EXEC_PIC_ADDRESS   0x500000000000\n    #define INTERP_PIC_ADDRESS 0x6f0000000000\n    #define EXEC_PIC_ADDRESS_32   0x0f000000\n    #define INTERP_PIC_ADDRESS_32 0xaf000000\n#elif defined(ARCH_ARM_EABI)\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-arm.h\"\n    #define SYSNUMS_ABI1    sysnums_arm\n    #define SYSTRAP_SIZE 4\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_ARM, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n    #define user_regs_struct user_regs\n    #define HOST_ELF_MACHINE {40, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define EM_ARM 40\n    #define LOADER_ADDRESS 0x10000000\n    #define EXEC_PIC_ADDRESS   0x0f000000\n    #define INTERP_PIC_ADDRESS 0x1f000000\n#elif defined(ARCH_ARM64)\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-arm64.h\"\n    #define SYSNUMS_ABI1    sysnums_arm64\n    #define SYSTRAP_SIZE 4\n    #ifndef AUDIT_ARCH_AARCH64\n        #define AUDIT_ARCH_AARCH64 (EM_AARCH64 | __AUDIT_ARCH_64BIT | __AUDIT_ARCH_LE)\n    #endif\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_AARCH64, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n    #define HOST_ELF_MACHINE {183, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define LOADER_ADDRESS     0x2000000000\n    #define EXEC_PIC_ADDRESS   0x3000000000\n    #define INTERP_PIC_ADDRESS 0x3f00000000\n#elif defined(ARCH_X86)\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-i386.h\"\n    #define SYSNUMS_ABI1    sysnums_i386\n    #undef  SYSTRAP_NUM\n    #define SYSTRAP_NUM SYSARG_RESULT\n    #define SYSTRAP_SIZE 2\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_I386, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n    #define HOST_ELF_MACHINE {3, 6, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define LOADER_ADDRESS 0xa0000000\n    #define LOADER_ARCH_CFLAGS -mregparm=3\n    #define EXEC_PIC_ADDRESS   0x0f000000\n    #define INTERP_PIC_ADDRESS 0xaf000000\n#elif defined(ARCH_SH4)\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-sh4.h\"\n    #define SYSNUMS_ABI1    sysnums_sh4\n    #define SYSTRAP_SIZE 2\n    #define SECCOMP_ARCHS { }\n    #define user_regs_struct pt_regs\n    #define HOST_ELF_MACHINE {42, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define NO_MISALIGNED_ACCESS 1\n#else\n    #error \"Unsupported architecture\"\n#endif', '#define SYSTRAP_NUM SYSARG_NUM\n#define STACK_ALIGNMENT 16\n\n#define OFFSETOF_STATX_UID 20\n#define OFFSETOF_STATX_GID 24\n\n#if !defined(ARCH_X86_64) && !defined(ARCH_ARM_EABI) && !defined(ARCH_X86) && !defined(ARCH_SH4) && !defined(ARCH_ARM64) && !defined(ARCH_RISCV64) && !defined(ARCH_RISCV32)\n#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    elif defined(__riscv)\n#        if __riscv_xlen == 64\n#            define ARCH_RISCV64 1\n#        elif __riscv_xlen == 32\n#            define ARCH_RISCV32 1\n#        else\n#            error \"Unsupported RISC-V XLEN\"\n#        endif\n#    else\n#        error \"Unsupported architecture\"\n#    endif\n#endif\n\n#if defined(ARCH_X86_64)\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-x86_64.h\"\n    #define SYSNUMS_HEADER2 \"syscall/sysnums-i386.h\"\n    #define SYSNUMS_HEADER3 \"syscall/sysnums-x32.h\"\n    #define SYSNUMS_ABI1 sysnums_x86_64\n    #define SYSNUMS_ABI2 sysnums_i386\n    #define SYSNUMS_ABI3 sysnums_x32\n    #undef  SYSTRAP_NUM\n    #define SYSTRAP_NUM SYSARG_RESULT\n    #define SYSTRAP_SIZE 2\n    #define SECCOMP_ARCHS {{\\n		{ .value = AUDIT_ARCH_X86_64, .nb_abis = 2, .abis = { ABI_DEFAULT, ABI_3 } },\\\n		{ .value = AUDIT_ARCH_I386,   .nb_abis = 1, .abis = { ABI_2 } }, 		\\\n	}}\n    #define HOST_ELF_MACHINE {62, 3, 6, 0}\n    #define RED_ZONE_SIZE 128\n    #define OFFSETOF_STAT_UID_32 24\n    #define OFFSETOF_STAT_GID_32 28\n    #define LOADER_ADDRESS 0x600000000000\n    #define HAS_LOADER_32BIT true\n    #define EXEC_PIC_ADDRESS   0x500000000000\n    #define INTERP_PIC_ADDRESS 0x6f0000000000\n    #define EXEC_PIC_ADDRESS_32   0x0f000000\n    #define INTERP_PIC_ADDRESS_32 0xaf000000\n#elif defined(ARCH_ARM_EABI)\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-arm.h\"\n    #define SYSNUMS_ABI1    sysnums_arm\n    #define SYSTRAP_SIZE 4\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_ARM, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n    #define user_regs_struct user_regs\n    #define HOST_ELF_MACHINE {40, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define EM_ARM 40\n    #define LOADER_ADDRESS 0x10000000\n    #define EXEC_PIC_ADDRESS   0x0f000000\n    #define INTERP_PIC_ADDRESS 0x1f000000\n#elif defined(ARCH_ARM64)\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-arm64.h\"\n    #define SYSNUMS_ABI1    sysnums_arm64\n    #define SYSTRAP_SIZE 4\n    #ifndef AUDIT_ARCH_AARCH64\n        #define AUDIT_ARCH_AARCH64 (EM_AARCH64 | __AUDIT_ARCH_64BIT | __AUDIT_ARCH_LE)\n    #endif\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_AARCH64, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n    #define HOST_ELF_MACHINE {183, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define LOADER_ADDRESS     0x2000000000\n    #define EXEC_PIC_ADDRESS   0x3000000000\n    #define INTERP_PIC_ADDRESS 0x3f00000000\n#elif defined(ARCH_RISCV64)\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-riscv64.h\"\n    #define SYSNUMS_ABI1    sysnums_riscv64\n    #define SYSTRAP_SIZE 4\n    #ifndef AUDIT_ARCH_RISCV64\n        #define AUDIT_ARCH_RISCV64 (243 | __AUDIT_ARCH_64BIT | __AUDIT_ARCH_LE)\n    #endif\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_RISCV64, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n    #define HOST_ELF_MACHINE {243, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define LOADER_ADDRESS     0x4000000000\n    #define EXEC_PIC_ADDRESS   0x5000000000\n    #define INTERP_PIC_ADDRESS 0x5f00000000\n#elif defined(ARCH_RISCV32)\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-riscv32.h\"\n    #define SYSNUMS_ABI1    sysnums_riscv32\n    #define SYSTRAP_SIZE 4\n    #ifndef AUDIT_ARCH_RISCV32\n        #define AUDIT_ARCH_RISCV32 (243 | __AUDIT_ARCH_LE)\n    #endif\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_RISCV32, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n    #define HOST_ELF_MACHINE {243, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define NO_MISALIGNED_ACCESS 1\n    #define LOADER_ADDRESS     0x40000000\n    #define EXEC_PIC_ADDRESS   0x50000000\n    #define INTERP_PIC_ADDRESS 0x5f000000\n#elif defined(ARCH_X86)\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-i386.h\"\n    #define SYSNUMS_ABI1    sysnums_i386\n    #undef  SYSTRAP_NUM\n    #define SYSTRAP_NUM SYSARG_RESULT\n    #define SYSTRAP_SIZE 2\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_I386, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n    #define HOST_ELF_MACHINE {3, 6, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define LOADER_ADDRESS 0xa0000000\n    #define LOADER_ARCH_CFLAGS -mregparm=3\n    #define EXEC_PIC_ADDRESS   0x0f000000\n    #define INTERP_PIC_ADDRESS 0xaf000000\n#elif defined(ARCH_SH4)\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-sh4.h\"\n    #define SYSNUMS_ABI1    sysnums_sh4\n    #define SYSTRAP_SIZE 2\n    #define SECCOMP_ARCHS { }\n    #define user_regs_struct pt_regs\n    #define HOST_ELF_MACHINE {42, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define NO_MISALIGNED_ACCESS 1\n#else\n    #error \"Unsupported architecture\"\n#endif', 'proot/src/arch.h 缺少 RISC-V 架构支持。原始代码在 #else 分支直接 #error \'Unsupported architecture\'，导致 RISC-V 平台编译失败。适配思路：(1) 在架构检测宏分支中增加 __riscv 判断，根据 __riscv_xlen 区分 RV64/RV32；(2) 新增 ARCH_RISCV64/ARCH_RISCV32 架构定义块，设置 syscall 头文件路径、seccomp 架构 AUDIT_ARCH_RISCV64 (EM_RISCV=243)、ELF 机器号 243、无 red zone、loader 地址空间等参数；(3) RV32 额外设置 NO_MISALIGNED_ACCESS。SYSTRAP_NUM 保持默认的 SYSARG_NUM（RISC-V 通过 a7 寄存器传递系统调用号，与默认一致）。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('cff0f57076d292e1a06586ec39121be4', '0', NULL, '2026-07-27 10:10:30', NULL, '2026-07-27 10:10:30', NULL, 'c6ff6c035da9736ca86f235e989a8df6', 'source_code', 'c', 'x86_64', 'risc-v', '#    ifndef PTRACE_EVENT_SECCOMP2\n#        if PTRACE_EVENT_SECCOMP == 7\n#            define PTRACE_EVENT_SECCOMP2	8\n#        elif PTRACE_EVENT_SECCOMP == 8\n#            define PTRACE_EVENT_SECCOMP2	7\n#        else\n#            error \"unknown PTRACE_EVENT_SECCOMP value\"\n#        endif\n#    endif', '#    ifndef PTRACE_EVENT_SECCOMP2\n#        if PTRACE_EVENT_SECCOMP == 7\n#            define PTRACE_EVENT_SECCOMP2	8\n#        elif PTRACE_EVENT_SECCOMP == 8\n#            define PTRACE_EVENT_SECCOMP2	7\n#        else\n#            error \"unknown PTRACE_EVENT_SECCOMP value\"\n#        endif\n#    endif', 'PTRACE_EVENT_SECCOMP2 fallback value is architecture-independent logic that detects runtime PTRACE_EVENT_SECCOMP value. On RISC-V, PTRACE_EVENT_SECCOMP==7 as on x86_64, so SECCOMP2 correctly resolves to 8. No RISC-V compatibility issue exists; this code is already architecture-agnostic.');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('d32a2b085d9d155a7a18f5b84bb81da3', '0', NULL, '2026-07-27 11:02:40', NULL, '2026-07-27 11:02:40', NULL, '01df88b254c9685e4e2e630c69542e86', 'source_code', 'c', 'x86_64', 'risc-v', '#ifndef ARCH_H\n#define ARCH_H\n\n#if defined(__x86_64__)\n  #define CACHE_LINE_SIZE 64\n  #define mb()  asm volatile(\"mfence\" ::: \"memory\")\n  #define rmb() asm volatile(\"lfence\" ::: \"memory\")\n  #define wmb() asm volatile(\"sfence\" ::: \"memory\")\n#elif defined(__aarch64__)\n  #define CACHE_LINE_SIZE 64\n  #define mb()  asm volatile(\"dmb ish\" ::: \"memory\")\n  #define rmb() asm volatile(\"dmb ishld\" ::: \"memory\")\n  #define wmb() asm volatile(\"dmb ishst\" ::: \"memory\")\n#else\n  #define CACHE_LINE_SIZE 64\n  #define mb()  /* TODO: RISC-V fence */\n  #define rmb() /* TODO: RISC-V fence */\n  #define wmb() /* TODO: RISC-V fence */\n#endif\n\n#endif', '#ifndef ARCH_H\n#define ARCH_H\n\n#if defined(__x86_64__)\n  #define CACHE_LINE_SIZE 64\n  #define mb()  asm volatile(\"mfence\" ::: \"memory\")\n  #define rmb() asm volatile(\"lfence\" ::: \"memory\")\n  #define wmb() asm volatile(\"sfence\" ::: \"memory\")\n#elif defined(__aarch64__)\n  #define CACHE_LINE_SIZE 64\n  #define mb()  asm volatile(\"dmb ish\" ::: \"memory\")\n  #define rmb() asm volatile(\"dmb ishld\" ::: \"memory\")\n  #define wmb() asm volatile(\"dmb ishst\" ::: \"memory\")\n#elif defined(__riscv)\n  #define CACHE_LINE_SIZE 64\n  #define mb()  asm volatile(\"fence iorw, iorw\" ::: \"memory\")\n  #define rmb() asm volatile(\"fence ir, ir\" ::: \"memory\")\n  #define wmb() asm volatile(\"fence ow, ow\" ::: \"memory\")\n#else\n  #define CACHE_LINE_SIZE 64\n  #define mb()\n  #define rmb()\n  #define wmb()\n#endif\n\n#endif', '第4行 #if defined(__x86_64__) 开始的条件编译链仅覆盖x86_64和aarch64，RISC-V落入#else分支导致mb()/rmb()/wmb()为空实现（仅有TODO注释），在RISC-V弱内存模型下会引发内存序错误。适配方案：新增 #elif defined(__riscv) 分支，使用RISC-V fence指令提供完整的内存屏障语义。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('d39f990fdff6a1d851feeca2e7a913fb', '0', NULL, '2026-07-27 10:16:31', NULL, '2026-07-27 10:16:31', NULL, 'c6ff6c035da9736ca86f235e989a8df6', 'source_code', 'c', 'x86_64', 'risc-v', '#if defined(ARCH_X86_64)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-x86_64.h\"\n    #define SYSNUMS_HEADER2 \"syscall/sysnums-i386.h\"\n    #define SYSNUMS_HEADER3 \"syscall/sysnums-x32.h\"\n\n    #define SYSNUMS_ABI1 sysnums_x86_64\n    #define SYSNUMS_ABI2 sysnums_i386\n    #define SYSNUMS_ABI3 sysnums_x32\n\n    #undef  SYSTRAP_NUM\n    #define SYSTRAP_NUM SYSARG_RESULT\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS {									\\\n		{ .value = AUDIT_ARCH_X86_64, .nb_abis = 2, .abis = { ABI_DEFAULT, ABI_3 } },	\\\n		{ .value = AUDIT_ARCH_I386,   .nb_abis = 1, .abis = { ABI_2 } }, 		\\\n	}\n\n    #define HOST_ELF_MACHINE {62, 3, 6, 0}\n    #define RED_ZONE_SIZE 128\n    #define OFFSETOF_STAT_UID_32 24\n    #define OFFSETOF_STAT_GID_32 28\n\n    #define LOADER_ADDRESS 0x600000000000\n    #define HAS_LOADER_32BIT true\n\n    #define EXEC_PIC_ADDRESS   0x500000000000\n    #define INTERP_PIC_ADDRESS 0x6f0000000000\n    #define EXEC_PIC_ADDRESS_32   0x0f000000\n    #define INTERP_PIC_ADDRESS_32 0xaf000000\n\n#elif defined(ARCH_ARM_EABI)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-arm.h\"\n    #define SYSNUMS_ABI1    sysnums_arm\n\n    #define SYSTRAP_SIZE 4\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_ARM, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define user_regs_struct user_regs\n    #define HOST_ELF_MACHINE {40, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define EM_ARM 40\n\n    #define LOADER_ADDRESS 0x10000000\n\n    #define EXEC_PIC_ADDRESS   0x0f000000\n    #define INTERP_PIC_ADDRESS 0x1f000000\n\n#elif defined(ARCH_ARM64)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-arm64.h\"\n    #define SYSNUMS_ABI1    sysnums_arm64\n\n    #define SYSTRAP_SIZE 4\n\n    #ifndef AUDIT_ARCH_AARCH64\n        #define AUDIT_ARCH_AARCH64 (EM_AARCH64 | __AUDIT_ARCH_64BIT | __AUDIT_ARCH_LE)\n    #endif\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_AARCH64, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {183, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n\n    #define LOADER_ADDRESS     0x2000000000\n    #define EXEC_PIC_ADDRESS   0x3000000000\n    #define INTERP_PIC_ADDRESS 0x3f00000000\n\n#elif defined(ARCH_X86)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-i386.h\"\n    #define SYSNUMS_ABI1    sysnums_i386\n\n    #undef  SYSTRAP_NUM\n    #define SYSTRAP_NUM SYSARG_RESULT\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_I386, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {3, 6, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n\n    #define LOADER_ADDRESS 0xa0000000\n    #define LOADER_ARCH_CFLAGS -mregparm=3\n\n    #define EXEC_PIC_ADDRESS   0x0f000000\n    #define INTERP_PIC_ADDRESS 0xaf000000\n\n#elif defined(ARCH_SH4)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-sh4.h\"\n    #define SYSNUMS_ABI1    sysnums_sh4\n\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS { }\n\n    #define user_regs_struct pt_regs\n    #define HOST_ELF_MACHINE {42, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define NO_MISALIGNED_ACCESS 1\n\n#else\n\n    #error \"Unsupported architecture\"\n\n#endif', '#if defined(ARCH_X86_64)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-x86_64.h\"\n    #define SYSNUMS_HEADER2 \"syscall/sysnums-i386.h\"\n    #define SYSNUMS_HEADER3 \"syscall/sysnums-x32.h\"\n\n    #define SYSNUMS_ABI1 sysnums_x86_64\n    #define SYSNUMS_ABI2 sysnums_i386\n    #define SYSNUMS_ABI3 sysnums_x32\n\n    #undef  SYSTRAP_NUM\n    #define SYSTRAP_NUM SYSARG_RESULT\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS {									\\\n		{ .value = AUDIT_ARCH_X86_64, .nb_abis = 2, .abis = { ABI_DEFAULT, ABI_3 } },	\\\n		{ .value = AUDIT_ARCH_I386,   .nb_abis = 1, .abis = { ABI_2 } }, 		\\\n	}\n\n    #define HOST_ELF_MACHINE {62, 3, 6, 0}\n    #define RED_ZONE_SIZE 128\n    #define OFFSETOF_STAT_UID_32 24\n    #define OFFSETOF_STAT_GID_32 28\n\n    #define LOADER_ADDRESS 0x600000000000\n    #define HAS_LOADER_32BIT true\n\n    #define EXEC_PIC_ADDRESS   0x500000000000\n    #define INTERP_PIC_ADDRESS 0x6f0000000000\n    #define EXEC_PIC_ADDRESS_32   0x0f000000\n    #define INTERP_PIC_ADDRESS_32 0xaf000000\n\n#elif defined(ARCH_ARM_EABI)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-arm.h\"\n    #define SYSNUMS_ABI1    sysnums_arm\n\n    #define SYSTRAP_SIZE 4\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_ARM, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define user_regs_struct user_regs\n    #define HOST_ELF_MACHINE {40, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define EM_ARM 40\n\n    #define LOADER_ADDRESS 0x10000000\n\n    #define EXEC_PIC_ADDRESS   0x0f000000\n    #define INTERP_PIC_ADDRESS 0x1f000000\n\n#elif defined(ARCH_ARM64)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-arm64.h\"\n    #define SYSNUMS_ABI1    sysnums_arm64\n\n    #define SYSTRAP_SIZE 4\n\n    #ifndef AUDIT_ARCH_AARCH64\n        #define AUDIT_ARCH_AARCH64 (EM_AARCH64 | __AUDIT_ARCH_64BIT | __AUDIT_ARCH_LE)\n    #endif\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_AARCH64, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {183, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n\n    #define LOADER_ADDRESS     0x2000000000\n    #define EXEC_PIC_ADDRESS   0x3000000000\n    #define INTERP_PIC_ADDRESS 0x3f00000000\n\n#elif defined(ARCH_X86)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-i386.h\"\n    #define SYSNUMS_ABI1    sysnums_i386\n\n    #undef  SYSTRAP_NUM\n    #define SYSTRAP_NUM SYSARG_RESULT\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_I386, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {3, 6, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n\n    #define LOADER_ADDRESS 0xa0000000\n    #define LOADER_ARCH_CFLAGS -mregparm=3\n\n    #define EXEC_PIC_ADDRESS   0x0f000000\n    #define INTERP_PIC_ADDRESS 0xaf000000\n\n#elif defined(ARCH_SH4)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-sh4.h\"\n    #define SYSNUMS_ABI1    sysnums_sh4\n\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS { }\n\n    #define user_regs_struct pt_regs\n    #define HOST_ELF_MACHINE {42, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define NO_MISALIGNED_ACCESS 1\n\n#elif defined(ARCH_RISCV)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-riscv64.h\"\n    #define SYSNUMS_ABI1    sysnums_riscv64\n\n    #define SYSTRAP_SIZE 4\n\n    #ifndef AUDIT_ARCH_RISCV64\n        #define AUDIT_ARCH_RISCV64 (243 | __AUDIT_ARCH_64BIT | __AUDIT_ARCH_LE)\n    #endif\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_RISCV64, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {243, 0}\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define NO_MISALIGNED_ACCESS 1\n\n    #define LOADER_ADDRESS     0x2000000000\n    #define EXEC_PIC_ADDRESS   0x3000000000\n    #define INTERP_PIC_ADDRESS 0x3f00000000\n\n#else\n\n    #error \"Unsupported architecture\"\n\n#endif', 'Lines 74-77 define SECCOMP_ARCHS for x86_64 multi-ABI (native, i386, x32). The #elif chain lacks an ARCH_RISCV case. Added ARCH_RISCV block: SECCOMP_ARCHS targets AUDIT_ARCH_RISCV64 (single ABI, no compat mode), EM_RISCV=243, ecall 4-byte, no red zone, misaligned access unsafe.');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('d62970afcf0b1fcf2bed57b16f5a8ba2', '0', NULL, '2026-07-14 12:52:31', NULL, '2026-07-14 12:52:31', NULL, 'b841e87e115b14f59294b60baa81ac64', 'source_code', 'c', 'arm', 'risc-v', '/* According to the ARM EABI, all registers have undefined values at\n * program startup except:\n *\n * - the instruction pointer (r15)\n * - the stack pointer (r13)\n * - the rtld_fini pointer (r0)\n */\n#define BRANCH(stack_pointer, destination) do {			\\\n	asm volatile (						\\\n		\"// Restore initial stack pointer.	\\n\\t\"	\\\n		\"mov sp, %0				\\n\\t\"	\\\n		\"					\\n\\t\"	\\\n		\"// Clear rtld_fini.			\\n\\t\"	\\\n		\"mov r0, #0				\\n\\t\"	\\\n		\"					\\n\\t\"	\\\n		\"// Start the program.			\\n\\t\"	\\\n		\"mov pc, %1				\\n\"	\\\n		: /* no output */				\\\n		: \"r\" (stack_pointer), \"r\" (destination)	\\\n		: \"memory\", \"sp\", \"r0\", \"pc\");		\\\n	__builtin_unreachable();				\\\n	} while (0)', '/* According to the RISC-V ABI, all registers have undefined values\n * at program startup except:\n *\n * - the instruction pointer (pc)\n * - the stack pointer (sp)\n */\n#define BRANCH(stack_pointer, destination) do {			\\\n	asm volatile (						\\\n		\"// Restore initial stack pointer.	\\n\\t\"	\\\n		\"mv sp, %0				\\n\\t\"	\\\n		\"					\\n\\t\"	\\\n		\"// Start the program.			\\n\\t\"	\\\n		\"jalr zero, %1, 0			\\n\"	\\\n		: /* no output */				\\\n		: \"r\" (stack_pointer), \"r\" (destination)	\\\n		: \"memory\", \"sp\");				\\\n	__builtin_unreachable();				\\\n	} while (0)', 'BRANCH 宏使用 ARM 汇编：mov sp/mov r0/mov pc 指令及 r0/r13/r15 寄存器。RISC-V 无 ARM 的 rtld_fini 专用寄存器 r0，无需清零；无 PC 直接赋值指令。适配：用 `mv sp, %0` 设栈指针（与 ARM 的 mov sp 等价），`jalr zero, %1, 0` 替代 `mov pc, %1` 间接跳转（zero 丢弃 ra），删除 rtld_fini 清零和 \"r0\"/\"pc\" clobber。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('d7166e69239169627e8205877cc38f11', '0', NULL, '2026-07-27 10:12:40', NULL, '2026-07-27 10:12:40', NULL, 'c6ff6c035da9736ca86f235e989a8df6', 'source_code', 'c', 'x86_64', 'risc-v', '#elif defined(ARCH_SH4)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-sh4.h\"\n    #define SYSNUMS_ABI1    sysnums_sh4\n\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS { }\n\n    #define user_regs_struct pt_regs\n    #define HOST_ELF_MACHINE {42, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define NO_MISALIGNED_ACCESS 1\n\n#else\n\n    #error \"Unsupported architecture\"\n\n#endif', '#elif defined(ARCH_SH4)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-sh4.h\"\n    #define SYSNUMS_ABI1    sysnums_sh4\n\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS { }\n\n    #define user_regs_struct pt_regs\n    #define HOST_ELF_MACHINE {42, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define NO_MISALIGNED_ACCESS 1\n\n#elif defined(ARCH_RISCV)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-riscv64.h\"\n    #define SYSNUMS_ABI1    sysnums_riscv64\n\n    #define SYSTRAP_SIZE 4\n\n    #ifndef AUDIT_ARCH_RISCV64\n        #define AUDIT_ARCH_RISCV64 (243 | __AUDIT_ARCH_64BIT | __AUDIT_ARCH_LE)\n    #endif\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_RISCV64, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {243, 0}\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define NO_MISALIGNED_ACCESS 1\n\n    #define LOADER_ADDRESS     0x2000000000\n    #define EXEC_PIC_ADDRESS   0x3000000000\n    #define INTERP_PIC_ADDRESS 0x3f00000000\n\n#else\n\n    #error \"Unsupported architecture\"\n\n#endif', 'arch.h line 159 defines SYSNUMS_HEADER1 for SH4 but lacks any ARCH_RISCV block. RISC-V falls through to the #error at line 175. Added ARCH_RISCV block: EM_RISCV=243, AUDIT_ARCH_RISCV64, ecall 4-byte trap, no red zone, and misaligned access unsafe. Requires creating a corresponding sysnums-riscv64.h header.');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('d98dd9751ffbbccf9f319f445ae88584', '0', NULL, '2026-07-27 10:11:50', NULL, '2026-07-27 10:11:50', NULL, 'c6ff6c035da9736ca86f235e989a8df6', 'source_code', 'c', 'x86_64', 'risc-v', '#    ifndef PTRACE_EVENT_EXIT\n#        define PTRACE_EVENT_EXIT	6', '#    ifndef PTRACE_EVENT_EXIT\n#        define PTRACE_EVENT_EXIT	6', 'PTRACE_EVENT_EXIT (6) is a generic Linux ptrace event constant from kernel\'s include/uapi/linux/ptrace.h, shared across all architectures including RISC-V. The value is architecture-independent and already correct. No compatibility issue exists.');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('e36338872ac5667d7657b3feccb8046a', '0', NULL, '2026-07-09 13:45:01', NULL, '2026-07-09 13:45:01', NULL, 'c84a09afdce9a324b17d747c233f025b', 'source_code', 'c', 'x86_64', 'risc-v', '#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    elif defined(__riscv) && __riscv_xlen == 64\n#        define ARCH_RISCV64 1', '#    if defined(__x86_64__)\n#        define ARCH_X86_64 1\n#    elif defined(__ARM_EABI__)\n#        define ARCH_ARM_EABI 1\n#    elif defined(__aarch64__)\n#        define ARCH_ARM64 1\n#    elif defined(__arm__)\n#        error \"Only EABI is currently supported for ARM\"\n#    elif defined(__i386__)\n#        define ARCH_X86 1\n#    elif defined(__SH4__)\n#        define ARCH_SH4 1\n#    elif defined(__riscv) && __riscv_xlen == 64\n#        define ARCH_RISCV64 1', '该行为 ARM EABI 架构检测分支，与 RISC-V 无关。RISC-V 编译时通过 __riscv && __riscv_xlen == 64 分支匹配，不会进入此路径，无需修改。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('e3dd55b6547f80980f0518249d90b316', '0', NULL, '2026-07-14 12:55:12', NULL, '2026-07-14 12:55:12', NULL, 'b841e87e115b14f59294b60baa81ac64', 'source_code', 'c', 'x86_64/arm64', 'risc-v', '#include <fcntl.h>         /* open(2), */', '#include <fcntl.h>         /* open(2), */', 'Line 30 是 `#include <fcntl.h>` 后的空行，无实际代码。该文件处理 ELF auxiliary vectors（auxv），使用 peek_reg/peek_word/poke_word/sizeof_word 等架构无关的抽象接口，通过 tracee/reg.h、tracee/abi.h、arch.h 间接适配。文件本身不含任何架构相关宏、汇编或寄存器访问，RISC-V 上无需修改。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('eb89295da4f7cd2b575f19fc5155c8e7', '0', NULL, '2026-07-09 13:46:12', NULL, '2026-07-09 13:46:12', NULL, 'c84a09afdce9a324b17d747c233f025b', 'source_code', 'c', 'arm', 'risc-v', '#define BRANCH(stack_pointer, destination) do {			\\\n	asm volatile (						\\\n		\"// Restore initial stack pointer.	\\n\\t\"	\\\n		\"mov sp, %0				\\n\\t\"	\\\n		\"					\\n\\t\"	\\\n		\"// Clear rtld_fini.			\\n\\t\"	\\\n		\"mov r0, #0				\\n\\t\"	\\\n		\"					\\n\\t\"	\\\n		\"// Start the program.			\\n\\t\"	\\\n		\"mov pc, %1				\\n\"	\\\n		: /* no output */				\\\n		: \"r\" (stack_pointer), \"r\" (destination)	\\\n		: \"memory\", \"sp\", \"r0\", \"pc\");		\\\n	__builtin_unreachable();				\\\n	} while (0)', '#define BRANCH(stack_pointer, destination) do {			\\\n	asm volatile (						\\\n		\"// Restore initial stack pointer.	\\n\\t\"	\\\n		\"mv sp, %0				\\n\\t\"	\\\n		\"					\\n\\t\"	\\\n		\"// Clear rtld_fini.			\\n\\t\"	\\\n		\"mv a0, zero				\\n\\t\"	\\\n		\"					\\n\\t\"	\\\n		\"// Start the program.			\\n\\t\"	\\\n		\"jr %1					\\n\"	\\\n		: /* no output */				\\\n		: \"r\" (stack_pointer), \"r\" (destination)	\\\n		: \"memory\", \"sp\", \"a0\");			\\\n	__builtin_unreachable();				\\\n	} while (0)', 'ARM EABI BRANCH 宏使用 mov sp/mov r0/mov pc 指令及 sp/r0/pc 寄存器，与 RISC-V 不兼容。RISC-V 适配：mv sp 设置栈指针；rtld_fini 寄存器从 ARM 的 r0 改为 RISC-V ABI 约定的 a0；间接跳转从 mov pc 改为 jr（jump register）；RISC-V 的 pc 不可直接写，只能通过跳转指令修改。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('eff3152643ef19ca56c9efd2d2dc6634', '0', NULL, '2026-07-27 11:00:40', NULL, '2026-07-27 11:00:40', NULL, '01df88b254c9685e4e2e630c69542e86', 'source_code', 'c', 'x86_64', 'risc-v', '#include <string.h>\n#include <stdlib.h>\n#include \"arch.h\"\n\nvoid *aligned_alloc_wrapper(size_t alignment, size_t size) {\n#if defined(__x86_64__) || defined(__aarch64__)\n    void *ptr;\n    int ret = posix_memalign(&ptr, alignment, size);\n    return ret == 0 ? ptr : NULL;\n#else\n    // RISC-V \\xe5\\x90\\x8c\\xe6\\xa0\\xb7\\xe6\\x94\\xaf\\xe6\\x8c\\x81 posix_memalign\\xef\\xbc\\x8c\\xe4\\xbd\\x86\\xe9\\x9c\\x80\\xe8\\xa6\\x81\\xe7\\xa1\\xae\\xe8\\xae\\xa4 libc \\xe7\\x89\\x88\\xe6\\x9c\\xac\n    void *ptr;\n    int ret = posix_memalign(&ptr, alignment, size);\n    return ret == 0 ? ptr : NULL;\n#endif\n}\n\nvoid memory_barrier(void) {\n    mb();\n}\n\nsize_t get_cache_line_size(void) {\n    return CACHE_LINE_SIZE;\n}', '#include <string.h>\n#include <stdlib.h>\n#include \"arch.h\"\n\nvoid *aligned_alloc_wrapper(size_t alignment, size_t size) {\n    void *ptr;\n    int ret = posix_memalign(&ptr, alignment, size);\n    return ret == 0 ? ptr : NULL;\n}\n\nvoid memory_barrier(void) {\n    mb();\n}\n\nsize_t get_cache_line_size(void) {\n    return CACHE_LINE_SIZE;\n}', '\\x7b\\x58\\x66\\x5f\\x58\\x5f\\x36\\x34\\x5f\\x5f\\x7c\\x7c\\x20\\x5f\\x5f\\x61\\x61\\x72\\x63\\x68\\x36\\x34\\x5f\\x5f\\x7d\\x20\\xe6\\x9d\\xa1\\xe4\\xbb\\xb6\\xe7\\xbc\\x96\\xe8\\xaf\\x91\\xe5\\xb0\\x86\\x20\\x52\\x49\\x53\\x43\\x2d\\x56\\x20\\xe6\\x8e\\x92\\xe9\\x99\\xa4\\xe5\\x9c\\xa8\\xe5\\xa4\\x96\\xef\\xbc\\x8c\\xe4\\xbd\\x86\\xe4\\xb8\\xa4\\xe4\\xb8\\xaa\\xe5\\x88\\x86\\xe6\\x94\\xaf\\xe4\\xbb\\xa3\\xe7\\xa0\\x81\\xe5\\xae\\x8c\\xe5\\x85\\xa8\\xe7\\x9b\\xb8\\xe5\\x90\\x8c\\xef\\xbc\\x88\\xe9\\x83\\xbd\\xe6\\x98\\xaf\\x20posix_memalign\\xef\\xbc\\x89\\xe3\\x80\\x82\\x0aposix_memalign\\x20\\xe6\\x98\\xaf\\x20POSIX\\x20\\xe6\\xa0\\x87\\xe5\\x87\\x86\\xe6\\x8e\\xa5\\xe5\\x8f\\xa3\\xef\\xbc\\x8c\\xe5\\x9c\\xa8\\x20RISC-V\\x20\\x28glibc/musl/uclibc\\x29\\x20\\xe4\\xb8\\x8a\\xe5\\xae\\x8c\\xe5\\x85\\xa8\\xe6\\x94\\xaf\\xe6\\x8c\\x81\\xef\\xbc\\x8c\\xe6\\x97\\xa0\\xe9\\x9c\\x80\\xe6\\x9e\\xb6\\xe6\\x9e\\x84\\xe5\\x88\\x86\\xe6\\x94\\xaf\\xe3\\x80\\x82\\xe7\\x9b\\xb4\\xe6\\x8e\\xa5\\xe5\\x88\\xa0\\xe9\\x99\\xa4\\xe6\\x9d\\xa1\\xe4\\xbb\\xb6\\xe7\\xbc\\x96\\xe8\\xaf\\x91\\xe5\\x8c\\x85\\xe8\\xa3\\xb9\\xef\\xbc\\x8c\\xe4\\xbf\\x9d\\xe7\\x95\\x99\\xe5\\x8d\\x95\\xe4\\xb8\\x80\\xe5\\xae\\x9e\\xe7\\x8e\\xb0\\xe5\\x8d\\xb3\\xe5\\x8f\\xaf\\xe3\\x80\\x82');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('f180cd3e827aa863f42e71883de5e8ca', '0', NULL, '2026-07-27 11:01:30', NULL, '2026-07-27 11:01:30', NULL, '01df88b254c9685e4e2e630c69542e86', 'source_code', 'c', 'x86_64', 'risc-v', '#include <stdio.h>\n#include <stdlib.h>\n#include \"arch.h\"\n\n#ifdef __x86_64__\n  #define ARCH_NAME \"x86_64\"\n#elif defined(__aarch64__)\n  #define ARCH_NAME \"aarch64\"\n#else\n  #define ARCH_NAME \"unknown\"\n#endif\n\nint main(int argc, char **argv) {\n    printf(\"Hello from %s\\n\", ARCH_NAME);\n\n#if defined(__x86_64__) || defined(__i386__)\n    unsigned long flags;\n    asm volatile(\"pushf; pop %0\" : \"=r\"(flags));\n    printf(\"x86 flags: %lx\\n\", flags);\n#endif\n\n    return 0;\n}', '#include <stdio.h>\n#include <stdlib.h>\n#include \"arch.h\"\n\n#ifdef __x86_64__\n  #define ARCH_NAME \"x86_64\"\n#elif defined(__aarch64__)\n  #define ARCH_NAME \"aarch64\"\n#elif defined(__riscv)\n  #define ARCH_NAME \"riscv\"\n#else\n  #define ARCH_NAME \"unknown\"\n#endif\n\nint main(int argc, char **argv) {\n    printf(\"Hello from %s\\n\", ARCH_NAME);\n\n#if defined(__riscv)\n    unsigned long cycle;\n    asm volatile(\"rdcycle %0\" : \"=r\"(cycle));\n    printf(\"RISC-V cycle: %lx\\n\", cycle);\n#endif\n\n    return 0;\n}', '第17行 #if defined(__x86_64__) || defined(__i386__) 包裹了x86专有汇编pushf/pop读取EFLAGS，RISC-V无EFLAGS且不支持该指令。适配方案：增加__riscv分支，用rdcycle读取硬件周期计数器作为等效诊断信息，同时补充ARCH_NAME的RISC-V定义。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('f5df9ef635865b8a75bc057c18fb1a95', '0', NULL, '2026-07-27 10:10:50', NULL, '2026-07-27 10:10:50', NULL, 'c6ff6c035da9736ca86f235e989a8df6', 'source_code', 'c', 'x86_64', 'risc-v', '#    ifndef PTRACE_EVENT_SECCOMP\n#        define PTRACE_EVENT_SECCOMP	7', '#    ifndef PTRACE_EVENT_SECCOMP\n#        define PTRACE_EVENT_SECCOMP	7', 'PTRACE_EVENT_SECCOMP (7) is a generic Linux ptrace event constant from kernel\'s include/uapi/linux/ptrace.h, shared across all architectures including RISC-V. The value 7 is architecture-independent and already correct for RISC-V. No compatibility issue exists.');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('f7ad1889ae323ef25701d689c9085cd3', '0', NULL, '2026-07-27 11:02:20', NULL, '2026-07-27 11:02:20', NULL, '01df88b254c9685e4e2e630c69542e86', 'source_code', 'c', 'arm64', 'risc-v', '#ifndef ARCH_H\n#define ARCH_H\n\n#if defined(__x86_64__)\n  #define CACHE_LINE_SIZE 64\n  #define mb()  asm volatile(\"mfence\" ::: \"memory\")\n  #define rmb() asm volatile(\"lfence\" ::: \"memory\")\n  #define wmb() asm volatile(\"sfence\" ::: \"memory\")\n#elif defined(__aarch64__)\n  #define CACHE_LINE_SIZE 64\n  #define mb()  asm volatile(\"dmb ish\" ::: \"memory\")\n  #define rmb() asm volatile(\"dmb ishld\" ::: \"memory\")\n  #define wmb() asm volatile(\"dmb ishst\" ::: \"memory\")\n#else\n  #define CACHE_LINE_SIZE 64\n  #define mb()  /* TODO: RISC-V fence */\n  #define rmb() /* TODO: RISC-V fence */\n  #define wmb() /* TODO: RISC-V fence */\n#endif\n\n#endif', '#ifndef ARCH_H\n#define ARCH_H\n\n#if defined(__x86_64__)\n  #define CACHE_LINE_SIZE 64\n  #define mb()  asm volatile(\"mfence\" ::: \"memory\")\n  #define rmb() asm volatile(\"lfence\" ::: \"memory\")\n  #define wmb() asm volatile(\"sfence\" ::: \"memory\")\n#elif defined(__aarch64__)\n  #define CACHE_LINE_SIZE 64\n  #define mb()  asm volatile(\"dmb ish\" ::: \"memory\")\n  #define rmb() asm volatile(\"dmb ishld\" ::: \"memory\")\n  #define wmb() asm volatile(\"dmb ishst\" ::: \"memory\")\n#elif defined(__riscv)\n  #define CACHE_LINE_SIZE 64\n  #define mb()  asm volatile(\"fence iorw, iorw\" ::: \"memory\")\n  #define rmb() asm volatile(\"fence ir, ir\" ::: \"memory\")\n  #define wmb() asm volatile(\"fence ow, ow\" ::: \"memory\")\n#else\n  #define CACHE_LINE_SIZE 64\n  #define mb()  /* TODO: RISC-V fence */\n  #define rmb() /* TODO: RISC-V fence */\n  #define wmb() /* TODO: RISC-V fence */\n#endif\n\n#endif', '第14-19行#else分支的mb()/rmb()/wmb()为空实现（仅有TODO注释），RISC-V采用弱内存模型，缺少fence指令会导致内存序错误。适配方案：新增#elif defined(__riscv)分支，用fence指令实现完整的内存屏障：mb()使用fence iorw,iorw（全屏障），rmb()使用fence ir,ir（读屏障），wmb()使用fence ow,ow（写屏障）。');
INSERT INTO `b_t_corpus_jsonl` (`ID`, `IS_DELETE`, `CREATE_USER`, `CREATE_TIME`, `UPDATE_USER`, `UPDATE_TIME`, `ORG_ID`, `CORPUS_ID`, `TYPE`, `LANGUAGE`, `SOURCE_CHIP`, `TARGET_CHIP`, `SOURCE_CODE`, `TARGET_CODE`, `DESCRIPTION`) VALUES ('ffb046904051db7da3e466cf96d8cbfb', '0', NULL, '2026-07-27 10:13:50', NULL, '2026-07-27 10:13:50', NULL, 'c6ff6c035da9736ca86f235e989a8df6', 'source_code', 'c', 'arm', 'risc-v', '#elif defined(ARCH_ARM_EABI)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-arm.h\"\n    #define SYSNUMS_ABI1    sysnums_arm\n\n    #define SYSTRAP_SIZE 4\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_ARM, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define user_regs_struct user_regs\n    #define HOST_ELF_MACHINE {40, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define EM_ARM 40\n\n    #define LOADER_ADDRESS 0x10000000\n\n    #define EXEC_PIC_ADDRESS   0x0f000000\n    #define INTERP_PIC_ADDRESS 0x1f000000\n\n#elif defined(ARCH_ARM64)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-arm64.h\"\n    #define SYSNUMS_ABI1    sysnums_arm64\n\n    #define SYSTRAP_SIZE 4\n\n    #ifndef AUDIT_ARCH_AARCH64\n        #define AUDIT_ARCH_AARCH64 (EM_AARCH64 | __AUDIT_ARCH_64BIT | __AUDIT_ARCH_LE)\n    #endif\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_AARCH64, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {183, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n\n    #define LOADER_ADDRESS     0x2000000000\n    #define EXEC_PIC_ADDRESS   0x3000000000\n    #define INTERP_PIC_ADDRESS 0x3f00000000\n\n#elif defined(ARCH_X86)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-i386.h\"\n    #define SYSNUMS_ABI1    sysnums_i386\n\n    #undef  SYSTRAP_NUM\n    #define SYSTRAP_NUM SYSARG_RESULT\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_I386, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {3, 6, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n\n    #define LOADER_ADDRESS 0xa0000000\n    #define LOADER_ARCH_CFLAGS -mregparm=3\n\n    #define EXEC_PIC_ADDRESS   0x0f000000\n    #define INTERP_PIC_ADDRESS 0xaf000000\n\n#elif defined(ARCH_SH4)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-sh4.h\"\n    #define SYSNUMS_ABI1    sysnums_sh4\n\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS { }\n\n    #define user_regs_struct pt_regs\n    #define HOST_ELF_MACHINE {42, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define NO_MISALIGNED_ACCESS 1\n\n#else\n\n    #error \"Unsupported architecture\"\n\n#endif', '#elif defined(ARCH_ARM_EABI)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-arm.h\"\n    #define SYSNUMS_ABI1    sysnums_arm\n\n    #define SYSTRAP_SIZE 4\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_ARM, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define user_regs_struct user_regs\n    #define HOST_ELF_MACHINE {40, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define EM_ARM 40\n\n    #define LOADER_ADDRESS 0x10000000\n\n    #define EXEC_PIC_ADDRESS   0x0f000000\n    #define INTERP_PIC_ADDRESS 0x1f000000\n\n#elif defined(ARCH_ARM64)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-arm64.h\"\n    #define SYSNUMS_ABI1    sysnums_arm64\n\n    #define SYSTRAP_SIZE 4\n\n    #ifndef AUDIT_ARCH_AARCH64\n        #define AUDIT_ARCH_AARCH64 (EM_AARCH64 | __AUDIT_ARCH_64BIT | __AUDIT_ARCH_LE)\n    #endif\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_AARCH64, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {183, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n\n    #define LOADER_ADDRESS     0x2000000000\n    #define EXEC_PIC_ADDRESS   0x3000000000\n    #define INTERP_PIC_ADDRESS 0x3f00000000\n\n#elif defined(ARCH_X86)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-i386.h\"\n    #define SYSNUMS_ABI1    sysnums_i386\n\n    #undef  SYSTRAP_NUM\n    #define SYSTRAP_NUM SYSARG_RESULT\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_I386, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {3, 6, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n\n    #define LOADER_ADDRESS 0xa0000000\n    #define LOADER_ARCH_CFLAGS -mregparm=3\n\n    #define EXEC_PIC_ADDRESS   0x0f000000\n    #define INTERP_PIC_ADDRESS 0xaf000000\n\n#elif defined(ARCH_SH4)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-sh4.h\"\n    #define SYSNUMS_ABI1    sysnums_sh4\n\n    #define SYSTRAP_SIZE 2\n\n    #define SECCOMP_ARCHS { }\n\n    #define user_regs_struct pt_regs\n    #define HOST_ELF_MACHINE {42, 0};\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define NO_MISALIGNED_ACCESS 1\n\n#elif defined(ARCH_RISCV)\n\n    #define SYSNUMS_HEADER1 \"syscall/sysnums-riscv64.h\"\n    #define SYSNUMS_ABI1    sysnums_riscv64\n\n    #define SYSTRAP_SIZE 4\n\n    #ifndef AUDIT_ARCH_RISCV64\n        #define AUDIT_ARCH_RISCV64 (243 | __AUDIT_ARCH_64BIT | __AUDIT_ARCH_LE)\n    #endif\n\n    #define SECCOMP_ARCHS { { .value = AUDIT_ARCH_RISCV64, .nb_abis = 1, .abis = { ABI_DEFAULT } } }\n\n    #define HOST_ELF_MACHINE {243, 0}\n    #define RED_ZONE_SIZE 0\n    #define OFFSETOF_STAT_UID_32 0\n    #define OFFSETOF_STAT_GID_32 0\n    #define NO_MISALIGNED_ACCESS 1\n\n    #define LOADER_ADDRESS     0x2000000000\n    #define EXEC_PIC_ADDRESS   0x3000000000\n    #define INTERP_PIC_ADDRESS 0x3f00000000\n\n#else\n\n    #error \"Unsupported architecture\"\n\n#endif', 'arch.h line 94 (ARM EABI SYSNUMS_ABI1) is part of architecture-specific #elif chain with no ARCH_RISCV block. Added ARCH_RISCV block: EM_RISCV=243, AUDIT_ARCH_RISCV64 defined as (243|__AUDIT_ARCH_64BIT|__AUDIT_ARCH_LE), ecall 4-byte trap, no red zone, misaligned access unsafe. Also requires adding ARCH_RISCV detection in the auto-detection block (lines 41-57).');
